/**
 * 11. BLOCK ALL PLUGIN INSTALLATION GLOBALLY — Platform Security
 *
 * Strips install_plugins and activate_plugins capabilities from every user
 * on the platform. No user — including administrators — can install or activate
 * plugins via the Elementor notice banners (e.g. "Install Ally"), the WordPress
 * admin plugin page, or any direct wp-admin/update.php URL.
 *
 * This is a platform-level security lock, not a role-level permission.
 */
add_filter( 'user_has_cap', function( $allcaps, $caps, $args, $user ) {
    $blocked = array( 'install_plugins', 'activate_plugins', 'update_plugins', 'delete_plugins', 'upload_plugins' );
    foreach ( $blocked as $cap ) {
        $allcaps[ $cap ] = false;
    }
    return $allcaps;
}, 999, 4 );

/**
 * Map administrator capabilities to cora_super_admin and cora_shruti dynamically
 */
add_filter( 'user_has_cap', function( $allcaps, $caps, $args, $user ) {
    if ( ! $user ) {
        return $allcaps;
    }
    $roles = (array) $user->roles;
    if ( in_array( 'cora_super_admin', $roles, true ) || in_array( 'cora_shruti', $roles, true ) ) {
        $admin_role = get_role( 'administrator' );
        if ( $admin_role ) {
            foreach ( $admin_role->capabilities as $cap => $grant ) {
                if ( ! in_array( $cap, array( 'manage_options', 'install_plugins', 'activate_plugins', 'update_plugins', 'delete_plugins', 'upload_plugins' ), true ) ) {
                    $allcaps[ $cap ] = $grant;
                }
            }
        }
    }
    return $allcaps;
}, 10, 4 );

/**
 * Grant Elementor library, page, and post edit capabilities to all logged-in Workspace users
 * to prevent "Error 403 / Access denied" exceptions inside Elementor builder iframe.
 */
add_filter( 'user_has_cap', function( $allcaps, $caps, $args, $user ) {
    if ( is_user_logged_in() ) {
        $el_caps = array(
            'edit_posts', 'edit_pages', 'edit_published_pages', 'edit_others_pages', 
            'publish_pages', 'read', 'elementor_edit_posts', 'edit_theme_options'
        );
        foreach ( $el_caps as $c ) {
            $allcaps[ $c ] = true;
        }
        if ( ! empty( $args ) && ( $args[0] === 'edit_post' || $args[0] === 'edit_others_posts' || $args[0] === 'edit_published_posts' || $args[0] === 'edit_page' ) ) {
            foreach ( $caps as $cap ) {
                $allcaps[ $cap ] = true;
            }
        }
    }
    return $allcaps;
}, 10, 4 );

