/**
 * Fast in-memory static & transient cache for MySQL table existence checks.
 * Completely eliminates repetitive SHOW TABLES LIKE queries per page load.
 */
if ( ! function_exists( 'cora_table_exists' ) ) {
function cora_table_exists( $table_name ) {
    static $static_table_cache = array();
    if ( empty( $table_name ) ) {
        return false;
    }
    if ( isset( $static_table_cache[ $table_name ] ) ) {
        return $static_table_cache[ $table_name ];
    }
    $transient_key = 'cora_tbl_ex_' . md5( $table_name );
    $cached_exists = get_transient( $transient_key );
    if ( false !== $cached_exists ) {
        $exists = ( '1' === $cached_exists );
        $static_table_cache[ $table_name ] = $exists;
        return $exists;
    }
    global $wpdb;
    $found = $wpdb->get_var( $wpdb->prepare( "SHOW TABLES LIKE %s", $table_name ) );
    $exists = ( strtolower( (string) $found ) === strtolower( (string) $table_name ) );
    set_transient( $transient_key, $exists ? '1' : '0', DAY_IN_SECONDS );
    $static_table_cache[ $table_name ] = $exists;
    return $exists;
}
}

/**
 * Resource hints for Google Fonts & external assets to eliminate render-blocking connection latency.
 */
if ( ! function_exists( 'cora_add_performance_resource_hints' ) ) {
function cora_add_performance_resource_hints() {
    echo '<link rel="preconnect" href="https://fonts.googleapis.com" crossorigin>' . "\n";
    echo '<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>' . "\n";
    echo '<link rel="dns-prefetch" href="https://fonts.googleapis.com">' . "\n";
    echo '<link rel="dns-prefetch" href="https://fonts.gstatic.com">' . "\n";
}
add_action( 'wp_head', 'cora_add_performance_resource_hints', 1 );
add_action( 'admin_head', 'cora_add_performance_resource_hints', 1 );
}

/**
 * Adapt a URL dynamically to the current request's scheme and HTTP host to avoid CORS/session issues on domain aliases.
 */
if ( ! function_exists( 'cora_get_origin_relative_url' ) ) {
function cora_get_origin_relative_url( $url ) {
    if ( empty( $url ) ) {
        return $url;
    }
    $parsed_url = parse_url( $url );
    if ( ! isset( $parsed_url['host'] ) ) {
        return $url;
    }
    $current_host = $_SERVER['HTTP_HOST'] ?? '';
    if ( empty( $current_host ) ) {
        return $url;
    }
    $scheme = ( is_ssl() || ( isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] === 'on' ) ) ? 'https' : 'http';
    $new_url = $scheme . '://' . $current_host;
    if ( isset( $parsed_url['path'] ) ) {
        $new_url .= $parsed_url['path'];
    }
    if ( isset( $parsed_url['query'] ) ) {
        $new_url .= '?' . $parsed_url['query'];
    }
    if ( isset( $parsed_url['fragment'] ) ) {
        $new_url .= '#' . $parsed_url['fragment'];
    }
    return $new_url;
}
}

/**
 * Helper to check if the current user's workspace is suspended.
 */
if ( ! function_exists( 'cora_is_agency_suspended' ) ) {
function cora_is_agency_suspended( $user_id = 0 ) {
    if ( ! $user_id ) {
        $user_id = get_current_user_id();
    }
    if ( ! $user_id ) return false;

    $user = get_userdata( $user_id );
    if ( ! $user ) return false;

    // Super Admin / Shruti is NEVER suspended
    if ( cora_is_super_owner( $user ) ) {
        return false;
    }

    global $wpdb;
    $agencies_table = $wpdb->prefix . 'cora_agencies';

    // 1. Check if user is owner of a suspended workspace in DB
    if ( cora_table_exists( $agencies_table ) ) {
        $status = $wpdb->get_var( $wpdb->prepare( "SELECT status FROM {$agencies_table} WHERE owner_user_id = %d", $user_id ) );
        if ( $status === 'suspended' ) {
            return true;
        }
    }

    // 2. Check user's assigned agency_id
    $agency_id = get_user_meta( $user_id, 'cora_agency_id', true );
    if ( ! empty( $agency_id ) && $agency_id !== 'super' ) {
        if ( cora_table_exists( $agencies_table ) ) {
            $status = $wpdb->get_var( $wpdb->prepare( "SELECT status FROM {$agencies_table} WHERE slug = %s OR id = %d", $agency_id, intval( $agency_id ) ) );
            if ( $status === 'suspended' ) {
                return true;
            }
        }
        $agencies = get_option( 'cora_agencies', array() );
        if ( is_array( $agencies ) ) {
            foreach ( $agencies as $ag ) {
                if ( ( isset( $ag['slug'] ) && $ag['slug'] === $agency_id ) || ( isset( $ag['id'] ) && (string)$ag['id'] === (string)$agency_id ) ) {
                    if ( isset( $ag['status'] ) && $ag['status'] === 'suspended' ) {
                        return true;
                    }
                }
            }
        }
    }

    // 3. Check direct user meta status
    $meta_status = get_user_meta( $user_id, 'cora_workspace_status', true ) ?: get_user_meta( $user_id, 'cora_agency_status', true );
    if ( $meta_status === 'suspended' ) {
        return true;
    }

    return false;
}
}

/**
 * Helper to get active workspace plan.
 */
if ( ! function_exists( 'cora_get_active_workspace_plan' ) ) {
function cora_get_active_workspace_plan( $user_id = 0 ) {
    if ( ! $user_id ) {
        $user_id = get_current_user_id();
    }
    if ( ! $user_id ) return 'starter';

    $user = get_userdata( $user_id );
    if ( $user && cora_is_super_owner( $user ) ) {
        return 'enterprise';
    }

    $context = function_exists( 'cora_get_current_workspace_context' ) ? cora_get_current_workspace_context() : null;
    if ( $context && ! empty( $context['plan'] ) ) {
        return strtolower( $context['plan'] );
    }

    $agency_id = get_user_meta( $user_id, 'cora_agency_id', true );
    if ( ! empty( $agency_id ) ) {
        global $wpdb;
        $agencies_table = $wpdb->prefix . 'cora_agencies';
        if ( cora_table_exists( $agencies_table ) ) {
            $plan = $wpdb->get_var( $wpdb->prepare( "SELECT plan FROM {$agencies_table} WHERE slug = %s OR id = %d OR owner_user_id = %d", $agency_id, intval( $agency_id ), $user_id ) );
            if ( $plan ) return strtolower( $plan );
        }
    }

    $user_plan = get_user_meta( $user_id, 'cora_workspace_plan', true ) ?: get_user_meta( $user_id, 'cora_agency_plan', true );
    if ( $user_plan ) return strtolower( $user_plan );

    return 'starter';
}
}

/**
 * Check if active workspace plan satisfies required tier level.
 */
if ( ! function_exists( 'cora_workspace_has_plan_access' ) ) {
function cora_workspace_has_plan_access( $required_plan = 'starter', $user_id = 0 ) {
    $plan = cora_get_active_workspace_plan( $user_id );

    $levels = array(
        'starter'    => 1,
        'pro'        => 2,
        'enterprise' => 3,
        'beta'       => 3,
    );

    $current_level  = isset( $levels[$plan] ) ? $levels[$plan] : 1;
    $required_level = isset( $levels[$required_plan] ) ? $levels[$required_plan] : 1;

    return $current_level >= $required_level;
}
}

/**
 * Lookup workspace by slug in database or options (cached).
 */
if ( ! function_exists( 'cora_get_workspace_by_slug' ) ) {
function cora_get_workspace_by_slug( $slug ) {
    if ( empty( $slug ) ) return null;
    $slug_clean = strtolower( trim( $slug ) );
    if ( $slug_clean === 'super' ) {
        return array(
            'id'     => 'super',
            'name'   => 'Platform Control Center',
            'slug'   => 'super',
            'plan'   => 'enterprise',
            'status' => 'active'
        );
    }

    static $slug_cache = array();
    if ( isset( $slug_cache[ $slug_clean ] ) ) {
        return $slug_cache[ $slug_clean ];
    }

    global $wpdb;
    $table_name = $wpdb->prefix . 'cora_agencies';
    
    if ( cora_table_exists( $table_name ) ) {
        $db_workspace = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$table_name} WHERE slug = %s", $slug_clean ), ARRAY_A );
        if ( $db_workspace ) {
            $slug_cache[ $slug_clean ] = $db_workspace;
            return $db_workspace;
        }
    }

    $agencies = get_option( 'cora_agencies', array() );
    if ( is_array( $agencies ) ) {
        foreach ( $agencies as $ag ) {
            if ( isset( $ag['slug'] ) && strtolower( $ag['slug'] ) === $slug_clean ) {
                $slug_cache[ $slug_clean ] = $ag;
                return $ag;
            }
        }
    }

    if ( is_user_logged_in() ) {
        $user_agency = get_user_meta( get_current_user_id(), 'cora_workspace_agency_name', true );
        if ( ! empty( $user_agency ) && ( sanitize_title( $user_agency ) === $slug_clean || $slug_clean === 'workspace' ) ) {
            $res = array(
                'id'     => get_current_user_id(),
                'name'   => $user_agency,
                'slug'   => $slug_clean,
                'plan'   => 'enterprise',
                'status' => 'active'
            );
            $slug_cache[ $slug_clean ] = $res;
            return $res;
        }
    }

    if ( in_array( $slug_clean, array( 'workspace', 'default' ), true ) ) {
        $display_name = 'Cora Workspace';
        $res = array(
            'id'     => 1,
            'name'   => $display_name,
            'slug'   => $slug_clean,
            'plan'   => 'enterprise',
            'status' => 'active'
        );
        $slug_cache[ $slug_clean ] = $res;
        return $res;
    }

    return null;
}
}

/**
 * Get all available workspaces for a given user.
 */
if ( ! function_exists( 'cora_get_user_workspaces' ) ) {
function cora_get_user_workspaces( $user_id = 0 ) {
    if ( ! $user_id ) {
        $user_id = get_current_user_id();
    }
    $user = get_userdata( $user_id );
    if ( ! $user ) return array();

    global $wpdb;
    $table_name = $wpdb->prefix . 'cora_agencies';

    // If Shruti / Super Admin, return ALL registered workspaces
    if ( cora_is_super_owner( $user ) ) {
        if ( cora_table_exists( $table_name ) ) {
            $workspaces = $wpdb->get_results( "SELECT * FROM {$table_name} ORDER BY name ASC", ARRAY_A );
            if ( ! empty( $workspaces ) ) return $workspaces;
        }
        $agencies = get_option( 'cora_agencies', array() );
        return is_array( $agencies ) ? array_values( $agencies ) : array();
    }

    // Otherwise find workspace(s) assigned to this user
    $assigned_agency_id = get_user_meta( $user_id, 'cora_agency_id', true );
    if ( empty( $assigned_agency_id ) ) {
        $cora_users_table = $wpdb->prefix . 'cora_users';
        if ( cora_table_exists( $cora_users_table ) ) {
            $cora_user = $wpdb->get_row( $wpdb->prepare( "SELECT agency_id FROM {$cora_users_table} WHERE wp_user_id = %d", $user_id ), ARRAY_A );
            if ( $cora_user ) {
                $assigned_agency_id = $cora_user['agency_id'];
            }
        }
    }

    if ( ! empty( $assigned_agency_id ) ) {
        $ws = cora_get_workspace_by_slug( (string) $assigned_agency_id );
        if ( $ws ) return array( $ws );

        if ( cora_table_exists( $table_name ) ) {
            $ws_db = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$table_name} WHERE id = %d", intval( $assigned_agency_id ) ), ARRAY_A );
            if ( $ws_db ) return array( $ws_db );
        }
    }

    $user_agency  = get_user_meta( $user_id, 'cora_workspace_agency_name', true );
    $default_name = ! empty( $user_agency ) ? $user_agency : 'Cora Workspace';
    $default_slug = ! empty( $user_agency ) ? sanitize_title( $user_agency ) : 'workspace';
    return array(
        array(
            'id'     => $user_id ? $user_id : 1,
            'name'   => $default_name,
            'slug'   => $default_slug,
            'plan'   => 'enterprise',
            'status' => 'active'
        )
    );
}
}

/**
 * Validate if a user is permitted to access a specific workspace.
 */
if ( ! function_exists( 'cora_user_can_access_workspace' ) ) {
function cora_user_can_access_workspace( $user_id, $workspace_slug ) {
    $user = get_userdata( $user_id );
    if ( ! $user ) return false;

    if ( in_array( strtolower( $workspace_slug ), array( 'workspace', 'apex-realty', 'default' ), true ) ) {
        return true;
    }

    // Shruti / Super Admin can access ANY workspace
    if ( cora_is_super_owner( $user ) ) {
        return true;
    }

    $workspaces = cora_get_user_workspaces( $user_id );
    foreach ( $workspaces as $ws ) {
        if ( isset( $ws['slug'] ) && strtolower( $ws['slug'] ) === strtolower( $workspace_slug ) ) {
            return true;
        }
        if ( isset( $ws['id'] ) && strtolower( (string)$ws['id'] ) === strtolower( $workspace_slug ) ) {
            return true;
        }
    }
    return false;
}
}

/**
 * Get active workspace context for the current request/session.
 */
if ( ! function_exists( 'cora_get_current_workspace_context' ) ) {
function cora_get_current_workspace_context() {
    if ( isset( $GLOBALS['cora_active_workspace'] ) && ! empty( $GLOBALS['cora_active_workspace'] ) ) {
        return $GLOBALS['cora_active_workspace'];
    }

    if ( isset( $_GET['workspace'] ) ) {
        $ws = cora_get_workspace_by_slug( sanitize_title( $_GET['workspace'] ) );
        if ( $ws ) {
            $GLOBALS['cora_active_workspace'] = $ws;
            return $ws;
        }
    }

    if ( isset( $_COOKIE['cora_active_workspace_slug'] ) ) {
        $ws = cora_get_workspace_by_slug( sanitize_title( $_COOKIE['cora_active_workspace_slug'] ) );
        if ( $ws ) {
            $GLOBALS['cora_active_workspace'] = $ws;
            return $ws;
        }
    }

    $user_workspaces = cora_get_user_workspaces( get_current_user_id() );
    if ( ! empty( $user_workspaces ) ) {
        $active_industry = function_exists('cora_get_active_industry') ? cora_get_active_industry() : 'real_estate';
        $matched_ws = null;
        foreach ( $user_workspaces as $ws ) {
            if ( isset( $ws['slug'] ) ) {
                if ( $active_industry === 'real_estate' && ( $ws['slug'] === 'real-estate' || $ws['slug'] === 'workspace' || $ws['slug'] === 'apex-realty' ) ) {
                    $matched_ws = $ws;
                    break;
                } elseif ( $active_industry === 'photography_studio' && ( $ws['slug'] === 'studio' || $ws['slug'] === 'photography' ) ) {
                    $matched_ws = $ws;
                    break;
                }
            }
        }
        $selected_ws = $matched_ws ?: $user_workspaces[0];
        $GLOBALS['cora_active_workspace'] = $selected_ws;
        return $selected_ws;
    }

    $user_agency = get_user_meta( get_current_user_id(), 'cora_workspace_agency_name', true );
    $default_name = ! empty( $user_agency ) ? $user_agency : 'Cora Workspace';
    $default_ws = array(
        'id' => 1,
        'name' => $default_name,
        'slug' => 'workspace',
        'plan' => 'enterprise',
        'status' => 'active'
    );
    $GLOBALS['cora_active_workspace'] = $default_ws;
    return $default_ws;
}
}

/**
 * Intercept requests to /workspace or /{{workspace_slug}} and render the standalone dashboard
 */
if ( ! function_exists( 'cora_real_estate_ai_handle_workspace_route' ) ) {
function cora_real_estate_ai_handle_workspace_route() {
    $request_uri = $_SERVER['REQUEST_URI'];
    $home_path = parse_url( home_url(), PHP_URL_PATH ) ?: '';
    $path = substr( $request_uri, strlen( $home_path ) );
    $path = trim( parse_url( $path, PHP_URL_PATH ), '/' );

    $path_parts = explode( '/', $path );
    
    // Bypass standalone router for REST API or WP admin/AJAX requests
    if ( defined( 'REST_REQUEST' ) && REST_REQUEST ) {
        return;
    }
    if ( in_array( 'wp-json', $path_parts, true ) || in_array( 'wp-admin', $path_parts, true ) || in_array( 'admin-ajax.php', $path_parts, true ) ) {
        return;
    }
    
    // Intercept REST API v1 requests
    if ( isset( $path_parts[0] ) && 'api' === $path_parts[0] && isset( $path_parts[1] ) && 'v1' === $path_parts[1] ) {
        cora_handle_api_v1_request( $path_parts );
        exit;
    }
    
    // Intercept PWA Manifest and Service Worker to serve them from the root scope
    if ( $path === 'cora-service-worker.js' ) {
        status_header( 200 );
        header( 'Content-Type: application/javascript' );
        header( 'Service-Worker-Allowed: /' );
        echo file_get_contents( CORA_WORKSPACE_PATH . 'assets/pwa/service-worker.js' );
        exit;
    }
    if ( $path === 'cora-manifest.json' ) {
        status_header( 200 );
        header( 'Content-Type: application/json' );
        echo file_get_contents( CORA_WORKSPACE_PATH . 'assets/pwa/manifest.json' );
        exit;
    }
    if ( $path === 'cora-offline.html' ) {
        status_header( 200 );
        header( 'Content-Type: text/html; charset=UTF-8' );
        echo file_get_contents( CORA_WORKSPACE_PATH . 'assets/pwa/offline.html' );
        exit;
    }

    if ( isset( $path_parts[0] ) && 'shared-doc' === $path_parts[0] ) {
        $hash = isset( $path_parts[1] ) ? sanitize_text_field( $path_parts[1] ) : '';
        if ( ! empty( $hash ) ) {
            $documents = get_option( 'cora_documents', array() );
            if ( ! is_array( $documents ) ) $documents = array();
            
            // Also merge with cora_workspace_vault_docs for safety
            $vault_docs = get_option( 'cora_workspace_vault_docs', array() );
            if ( is_array( $vault_docs ) ) {
                $documents = array_merge( $documents, $vault_docs );
            }

            $found_doc = null;
            $found_share = null;
            foreach ( $documents as $doc ) {
                if ( ! empty( $doc['secured_shares'] ) ) {
                    foreach ( $doc['secured_shares'] as $share ) {
                        if ( isset($share['hash']) && $share['hash'] === $hash ) {
                            $found_doc = $doc;
                            $found_share = $share;
                            break 2;
                        }
                    }
                }
            }

            if ( $found_doc && $found_share ) {
                $is_expired = false;
                if ( ! empty( $found_share['expiry_time'] ) && intval( $found_share['expiry_time'] ) > 0 && time() > intval( $found_share['expiry_time'] ) ) {
                    $is_expired = true;
                }
                
                nocache_headers();
                include CORA_WORKSPACE_PATH . 'public-doc-view.php';
                exit;
            }
        }
        wp_die( __( 'Invalid or expired secure document link.', 'cora-workspace' ), __( 'Access Denied', 'cora-workspace' ), array( 'response' => 403 ) );
    }

    if ( isset( $path_parts[0] ) && 'shared-portfolio' === $path_parts[0] ) {
        $hash = isset( $path_parts[1] ) ? sanitize_text_field( $path_parts[1] ) : '';
        if ( ! empty( $hash ) ) {
            $portfolios = get_option( 'cora_workspace_portfolios', array() );
            $found_portfolio = null;
            if ( is_array( $portfolios ) ) {
                foreach ( $portfolios as $portfolio ) {
                    if ( isset( $portfolio['hash'] ) && $portfolio['hash'] === $hash ) {
                        $found_portfolio = $portfolio;
                        break;
                    }
                }
            }

            if ( $found_portfolio ) {
                nocache_headers();
                include CORA_WORKSPACE_PATH . 'public-gallery-view.php';
                exit;
            }
        }
        wp_die( __( 'Invalid or secure portfolio link.', 'cora-workspace' ), __( 'Access Denied', 'cora-workspace' ), array( 'response' => 403 ) );
    }

    $shared_form_idx = -1;
    if ( isset( $path_parts[0] ) && 'shared-form' === $path_parts[0] ) {
        $shared_form_idx = 1;
    } else if ( isset( $path_parts[1] ) && 'shared-form' === $path_parts[1] ) {
        $shared_form_idx = 2;
    }

    if ( $shared_form_idx !== -1 ) {
        $identifier = isset( $path_parts[$shared_form_idx] ) ? sanitize_text_field( $path_parts[$shared_form_idx] ) : '';
        if ( ! empty( $identifier ) ) {
            global $wpdb;
            $form = null;
            if ( is_numeric( $identifier ) ) {
                $form = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$wpdb->prefix}cora_forms WHERE id = %d OR form_key = %s", intval( $identifier ), $identifier ), ARRAY_A );
            } else {
                $form = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$wpdb->prefix}cora_forms WHERE form_key = %s", $identifier ), ARRAY_A );
            }
            if ( $form ) {
                nocache_headers();
                include CORA_WORKSPACE_PATH . 'public-form-view.php';
                exit;
            }
        }
        wp_die( __( 'Invalid or inactive form link.', 'cora-workspace' ), __( 'Access Denied', 'cora-workspace' ), array( 'response' => 403 ) );
    }

    // Determine if request targets /workspace or a registered /{{workspace_slug}}
    $first_segment = isset( $path_parts[0] ) ? sanitize_title( $path_parts[0] ) : '';
    $matched_workspace = null;
    $is_workspace_route = false;

    if ( $first_segment === 'workspace' ) {
        $is_workspace_route = true;
        $sub_page = isset( $path_parts[1] ) ? sanitize_title( $path_parts[1] ) : '';
    } else if ( ! empty( $first_segment ) && ! in_array( $first_segment, array( 'wp-admin', 'wp-includes', 'wp-content', 'wp-json', 'assets' ) ) ) {
        if ( isset( $path_parts[0] ) && strpos( $path_parts[0], '.' ) === false ) {
            $matched_workspace = cora_get_workspace_by_slug( $first_segment );
            if ( $matched_workspace ) {
                $is_workspace_route = true;
                $GLOBALS['cora_active_workspace'] = $matched_workspace;
                $sub_page = isset( $path_parts[1] ) ? sanitize_title( $path_parts[1] ) : '';
            }
        }
    }

    if ( $is_workspace_route ) {
        $public_subs = array( 'login', 'forgot-password', 'reset-password', 'setup-account', 'register', 'verify-pending', 'onboarding' );

        // ── Public Canvas Website Routes — intercept BEFORE any login check (allows guest visitors) ──────
        if ( ( isset( $sub_page ) && ( $sub_page === 'site' || $sub_page === 'p' ) ) || $first_segment === 'site' ) {
            if ( function_exists( 'cora_canvas_theme_frontend_router' ) ) {
                cora_canvas_theme_frontend_router();
            } else {
                $ws_name = ! empty( $matched_workspace['name'] ) ? $matched_workspace['name'] : 'Workspace';
                $ws_slug = ! empty( $matched_workspace['slug'] ) ? $matched_workspace['slug'] : 'workspace';
                cora_render_default_workspace_welcome_site( $ws_name, $ws_slug );
            }
            exit;
        }

        // ── Google OAuth — intercept BEFORE any login check (works for guests) ──────
        if ( isset( $path_parts[1] ) && $path_parts[1] === 'auth' ) {
            $auth_provider = isset( $path_parts[2] ) ? sanitize_text_field( $path_parts[2] ) : '';
            $auth_step     = isset( $path_parts[3] ) ? sanitize_text_field( $path_parts[3] ) : '';
            if ( $auth_provider === 'google' ) {
                nocache_headers();
                if ( $auth_step === 'callback' ) {
                    // Check if this is a GBP OAuth callback returning to auth/google/callback
                    if ( isset( $_GET['code'] ) && ( ( isset( $_GET['scope'] ) && strpos( $_GET['scope'], 'business.manage' ) !== false ) || empty( $_GET['state'] ) || ! get_transient( 'cora_google_oauth_state_' . ( $_GET['state'] ?? '' ) ) ) ) {
                        wp_redirect( home_url( '/workspace/gbp?' . ( $_SERVER['QUERY_STRING'] ?? '' ) ) );
                        exit;
                    }
                    cora_handle_google_oauth_callback();
                } else {
                    cora_initiate_google_oauth();
                }
                exit;
            }
        }

        // Active workspace context resolution
        $current_ws = cora_get_current_workspace_context();

        // Enforce onboarding for logged-in users who have not completed it
        if ( is_user_logged_in() && $sub_page !== 'onboarding' ) {
            $onboarding_done = get_user_meta( get_current_user_id(), 'cora_onboarding_completed', true );
            if ( $onboarding_done !== '1' ) {
                wp_redirect( home_url( '/workspace/onboarding' ) );
                exit;
            }
        }

        // Allow logged-in users to access onboarding if not completed
        if ( is_user_logged_in() && $sub_page === 'onboarding' ) {
            $onboarding_done = get_user_meta( get_current_user_id(), 'cora_onboarding_completed', true );
            if ( $onboarding_done === '1' ) {
                $target_slug = isset( $current_ws['slug'] ) ? $current_ws['slug'] : 'workspace';
                wp_redirect( home_url( '/' . $target_slug . '/dashboard' ) );
                exit;
            }
            nocache_headers();
            status_header( 200 );
            include CORA_WORKSPACE_PATH . 'views/onboarding.php';
            exit;
        }

        // If logged in and hitting public auth pages, redirect to active workspace dashboard
        if ( is_user_logged_in() && in_array( $sub_page, $public_subs ) ) {
            $target_slug = isset( $current_ws['slug'] ) ? $current_ws['slug'] : 'workspace';
            wp_redirect( home_url( '/' . $target_slug . '/dashboard' ) );
            exit;
        }

        // If not logged in
        if ( ! is_user_logged_in() ) {
            if ( in_array( $sub_page, $public_subs ) ) {
                nocache_headers();
                $template_file = CORA_WORKSPACE_PATH . 'views/' . $sub_page . '.php';
                if ( file_exists( $template_file ) ) {
                    status_header( 200 );
                    include $template_file;
                    exit;
                }
            }
            // Redirect to custom login page
            $redirect_url = home_url( '/workspace/login' );
            if ( ! empty( $_SERVER['REQUEST_URI'] ) && strpos( $_SERVER['REQUEST_URI'], '/workspace/login' ) === false ) {
                $redirect_url = add_query_arg( 'redirect_to', urlencode( home_url( $_SERVER['REQUEST_URI'] ) ), $redirect_url );
            }
            wp_redirect( $redirect_url );
            exit;
        }

        // Allow administrators and custom photography roles to view workspace
        $user = wp_get_current_user();

        // If this is a public front-end site request, render default site instead of access restricted
        if ( isset( $sub_page ) && ( $sub_page === 'site' || $sub_page === 'p' || $first_segment === 'site' ) ) {
            $ws_name = ! empty( $matched_workspace['name'] ) ? $matched_workspace['name'] : 'Workspace';
            $ws_slug = ! empty( $matched_workspace['slug'] ) ? $matched_workspace['slug'] : 'workspace';
            cora_render_default_workspace_welcome_site( $ws_name, $ws_slug );
            exit;
        }

        // Verify Workspace Level Access Control
        if ( $matched_workspace && ! cora_user_can_access_workspace( $user->ID, $matched_workspace['slug'] ) ) {
            $user_ws = cora_get_user_workspaces( $user->ID );
            $fallback_slug = ! empty( $user_ws[0]['slug'] ) ? $user_ws[0]['slug'] : 'workspace';
            $debug_msg = sprintf(
                'Access Restricted. Debug info - User ID: %d, User Login: %s, Matched WS: %s, User Workspaces: %s',
                $user->ID,
                $user->user_login,
                $matched_workspace['slug'],
                print_r( $user_ws, true )
            );
            wp_die(
                $debug_msg,
                __( 'Access Restricted', 'cora-workspace' ),
                array( 'response' => 403 )
            );
        }
        
        // Deactivated user check (Spec Section 6.3)
        $user_status = get_user_meta( $user->ID, 'cora_user_status', true );
        if ( $user_status === 'inactive' ) {
            wp_logout();
            wp_redirect( home_url( '/workspace/login?deactivated=1' ) );
            exit;
        }

        // Account expiry check (Onboarding duration control)
        $expires_at = get_user_meta( $user->ID, 'cora_account_expires_at', true );
        if ( ! empty( $expires_at ) && intval( $expires_at ) > 0 && time() > intval( $expires_at ) ) {
            wp_logout();
            wp_redirect( home_url( '/workspace/login?expired=1' ) );
            exit;
        }

        // Agency suspension check (Spec Section 3.4)
        if ( is_user_logged_in() && cora_is_agency_suspended( $user->ID ) ) {
            wp_logout();
            wp_redirect( home_url( '/workspace/login?suspended=1' ) );
            exit;
        }

        $allowed_roles = array( 'administrator', 'cora_shruti', 'cora_super_admin', 'cora_manager', 'cora_branch_manager', 'cora_photographer', 'cora_videographer', 'cora_drone_pilot', 'cora_editor', 'cora_viewer' );
        $user_roles = (array) $user->roles;
        $has_access = false;
        foreach ( $allowed_roles as $role ) {
            if ( in_array( $role, $user_roles ) ) {
                $has_access = true;
                break;
            }
        }
        if ( ! $has_access ) {
            wp_die( __( 'You do not have sufficient permissions to access this page.', 'cora-workspace' ) );
        }

        // Parse sub-page
        $sub_page = isset( $path_parts[1] ) ? sanitize_title( $path_parts[1] ) : 'dashboard';
        if ( empty( $sub_page ) ) {
            $sub_page = 'dashboard';
        }
        $GLOBALS['sub_page'] = $sub_page;
        if ( $sub_page === 'audit-panel' ) {
            wp_redirect( home_url( '/workspace/settings-suite?settings_tab=audit' ) );
            exit;
        }
        if ( $sub_page === 'settings-suite' && isset( $_GET['settings_tab'] ) && $_GET['settings_tab'] === 'mcp' ) {
            wp_redirect( home_url( '/workspace/mcp' ) );
            exit;
        }

        // Role-based access control check (Server-Side)
        $cora_ws_slug = ! empty( $matched_workspace['slug'] ) ? $matched_workspace['slug'] : 'workspace';
        if ( $sub_page === 'super-admin' ) {
            if ( ! cora_is_super_owner() ) {
                wp_redirect( home_url( '/' . $cora_ws_slug . '/dashboard' ) );
                exit;
            }
        } else {
            // Prevent accessing disallowed sub-pages
            if ( $sub_page !== 'dashboard' && $sub_page !== 'setup-account' && function_exists( 'cora_user_has_feature_access' ) && ! cora_user_has_feature_access( $sub_page ) ) {
                wp_redirect( home_url( '/' . $cora_ws_slug . '/dashboard' ) );
                exit;
            }
        }

        // ── INDUSTRY MODE SWITCHER (Server-side, reliable) ──────────────────────
        if ( ! empty( $_GET['set_industry'] ) && cora_is_super_owner() ) {
            $requested = sanitize_text_field( $_GET['set_industry'] );
            if ( in_array( $requested, array( 'real_estate', 'photography_studio' ), true ) ) {
                update_option( 'cora_workspace_industry', $requested );
                // Set cookie for 1 year
                setcookie( 'cora_workspace_industry', $requested, time() + 86400 * 365, '/', '', is_ssl(), false );
                $_COOKIE['cora_workspace_industry'] = $requested;
            }
            // Redirect to clean URL (remove set_industry param)
            $clean_url = remove_query_arg( 'set_industry' );
            wp_redirect( $clean_url );
            exit;
        }

        // Standalone presentation page intercept for Ecosystem Map
        if ( $sub_page === 'ecosystem' ) {
            nocache_headers();
            include CORA_WORKSPACE_PATH . 'views/view-ecosystem.php';
            exit;
        }

        // Handle Google Business Profile OAuth callback (code exchange) for /workspace/auth/google/callback or /workspace/gbp
        if ( ( strpos( $_SERVER['REQUEST_URI'] ?? '', '/workspace/auth/google/callback' ) !== false || $sub_page === 'auth' || $sub_page === 'gbp' ) && isset( $_GET['code'] ) ) {
            $client_id     = cora_gbp_get_client_id();
            $client_secret = cora_gbp_get_client_secret();
            $redirect_uri  = ( strpos( $_SERVER['REQUEST_URI'] ?? '', '/workspace/auth/google/callback' ) !== false )
                ? home_url( '/workspace/auth/google/callback' )
                : home_url( '/workspace/gbp' );
            $code          = sanitize_text_field( $_GET['code'] );

            $response = wp_remote_post( 'https://oauth2.googleapis.com/token', array(
                'timeout' => 15,
                'body'    => array(
                    'code'          => $code,
                    'client_id'     => $client_id,
                    'client_secret' => $client_secret,
                    'redirect_uri'  => $redirect_uri,
                    'grant_type'    => 'authorization_code',
                ),
            ) );

            if ( ! is_wp_error( $response ) ) {
                $body = json_decode( wp_remote_retrieve_body( $response ), true );
                if ( ! empty( $body['access_token'] ) ) {
                    $tokens = array(
                        'access_token'  => $body['access_token'],
                        'refresh_token' => $body['refresh_token'] ?? '',
                        'expires_at'    => time() + ( intval( $body['expires_in'] ?? 3600 ) - 60 ),
                        'token_type'    => $body['token_type'] ?? 'Bearer',
                    );
                    update_option( 'cora_gbp_tokens', $tokens );
                    delete_option( 'cora_gbp_profile' );
                }
            }

            // Redirect clean to GBP workspace
            wp_redirect( home_url( '/workspace/gbp' ) );
            exit;
        }

        // Prevent browser caching
        nocache_headers();

        // Fetch real WordPress posts for the Content Suite
        $cora_posts_query = new WP_Query(array(
            'post_type' => 'post',
            'post_status' => array('publish', 'draft', 'pending', 'future', 'private'),
            'posts_per_page' => 50,
            'orderby' => 'date',
            'order' => 'DESC'
        ));
        $cora_posts = $cora_posts_query->posts;

        status_header( 200 );
        // Load the dashboard HTML template directly
        include CORA_WORKSPACE_PATH . 'admin-dashboard.php';
        exit;
    }
}
}
add_action( 'init', 'cora_real_estate_ai_handle_workspace_route', 1 );
add_action( 'template_redirect', 'cora_real_estate_ai_handle_workspace_route' );

/**
 * Enqueue scripts and styles only on our admin page
 */
if ( ! function_exists( 'cora_real_estate_ai_admin_assets' ) ) {
function cora_real_estate_ai_admin_assets( $hook ) {
    // Only load on our plugin page
    if ( 'toplevel_page_cora-real-estate' !== $hook ) {
        return;
    }

    // Enqueue Google Font: Inter
    wp_enqueue_style(
        'cora-font-inter',
        'https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap',
        array(),
        null
    );

    // Enqueue styles
    wp_enqueue_style(
        'cora-tailwind',
        CORA_WORKSPACE_URL . 'assets/css/tailwind-built.css',
        array(),
        CORA_WORKSPACE_VERSION
    );

    wp_enqueue_style(
        'cora-admin-style',
        CORA_WORKSPACE_URL . 'assets/css/admin-style.css',
        array(),
        CORA_WORKSPACE_VERSION
    );

    // Enqueue scripts
    wp_enqueue_script(
        'cora-admin-script',
        CORA_WORKSPACE_URL . 'assets/js/admin-script.js',
        array( 'jquery' ),
        CORA_WORKSPACE_VERSION,
        true // Load in footer
    );

    wp_enqueue_script(
        'cora-autosave-engine',
        CORA_WORKSPACE_URL . 'assets/js/cora-autosave-engine.js',
        array( 'jquery' ),
        CORA_WORKSPACE_VERSION,
        true
    );

    // Enqueue WordPress media libraries for logo upload
    wp_enqueue_media();

    // Localize script to pass server variables if needed (e.g. site URL, ajaxurl)
    $cora_gemini_key_saved  = defined( 'CORA_PLATFORM_GEMINI_API_KEY' ) && ! empty( CORA_PLATFORM_GEMINI_API_KEY );
    $cora_openai_key_saved  = ! empty( get_option( 'cora_workspace_ai_openai_key', '' ) );
    $cora_active_ai_model   = get_option( 'cora_workspace_active_ai_model', 'cora-core-v2' );
    wp_localize_script( 'cora-admin-script', 'coraREWPData', array(
        'ajaxUrl'          => cora_get_origin_relative_url( admin_url( 'admin-ajax.php' ) ),
        'siteUrl'          => cora_get_origin_relative_url( get_site_url() ),
        'restUrl'          => cora_get_origin_relative_url( esc_url_raw( rest_url() ) ),
        'nonce'            => wp_create_nonce( 'wp_rest' ),
        'ajaxNonce'        => wp_create_nonce( 'cora_ajax_nonce' ),
        'geminiKeySaved'   => $cora_gemini_key_saved,
        'openaiKeySaved'   => $cora_openai_key_saved,
        'activeAiModel'    => $cora_active_ai_model,
        'aiUsage'          => function_exists( 'cora_workspace_get_ai_usage_stats' ) ? cora_workspace_get_ai_usage_stats() : array( 'five_hour_count' => 0, 'five_hour_limit' => 30, 'daily_count' => 0, 'daily_limit' => 100 ),
        'site_title'       => get_option( 'blogname', 'Cora Workspace' ),
        'favicon_url'      => get_option( 'cora_brand_favicon_url', '' ),
        'logo_url'         => get_option( 'cora_brand_logo_url', '' ),
        'sidebar_title'    => get_option( 'cora_sidebar_title', 'cora' ),
    ) );
}
}
add_action( 'admin_enqueue_scripts', 'cora_real_estate_ai_admin_assets' );

/**
 * Handle AJAX request to save a module draft.
 */
if ( ! function_exists( 'cora_save_module_draft_ajax_handler' ) ) {
function cora_save_module_draft_ajax_handler() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );
    if ( ! current_user_can( 'read' ) ) {
        wp_send_json_error( array( 'message' => 'Unauthorized access' ) );
    }

    $module_key = isset( $_POST['module_key'] ) ? sanitize_text_field( wp_unslash( $_POST['module_key'] ) ) : '';
    $draft_data = isset( $_POST['draft_data'] ) ? wp_unslash( $_POST['draft_data'] ) : ''; // Leave unslashed to save the exact form data

    if ( empty( $module_key ) ) {
        wp_send_json_error( array( 'message' => 'Missing module key' ) );
    }

    $option_key = 'cora_draft_' . sanitize_key( $module_key );
    update_option( $option_key, $draft_data, false ); // Not autoloaded to save memory

    wp_send_json_success( array(
        'message'   => 'Draft saved successfully',
        'timestamp' => time()
    ) );
}
}
add_action( 'wp_ajax_cora_save_module_draft', 'cora_save_module_draft_ajax_handler' );

/**
 * Redirect custom studio roles and administrators to our custom dashboard after login
 */
if ( ! function_exists( 'cora_real_estate_ai_login_redirect' ) ) {
function cora_real_estate_ai_login_redirect( $redirect_to, $request, $user ) {
    if ( $user instanceof WP_User ) {
        $allowed_roles = array( 'administrator', 'cora_manager', 'cora_branch_manager', 'cora_photographer', 'cora_videographer', 'cora_drone_pilot', 'cora_editor', 'cora_viewer' );
        foreach ( $allowed_roles as $role ) {
            if ( in_array( $role, (array) $user->roles ) ) {
                $onb_done = get_user_meta( $user->ID, 'cora_onboarding_completed', true );
                if ( $onb_done !== '1' ) {
                    return home_url( '/workspace/onboarding' );
                }
                return home_url( '/workspace' );
            }
        }
    } else {
        $current_user = wp_get_current_user();
        if ( $current_user && $current_user->exists() ) {
            $allowed_roles = array( 'administrator', 'cora_manager', 'cora_branch_manager', 'cora_photographer', 'cora_videographer', 'cora_drone_pilot', 'cora_editor', 'cora_viewer' );
            foreach ( $allowed_roles as $role ) {
                if ( in_array( $role, (array) $current_user->roles ) ) {
                    $onb_done = get_user_meta( $current_user->ID, 'cora_onboarding_completed', true );
                    if ( $onb_done !== '1' ) {
                        return home_url( '/workspace/onboarding' );
                    }
                    return home_url( '/workspace' );
                }
            }
        }
    }
    return $redirect_to;
}
}
add_filter( 'login_redirect', 'cora_real_estate_ai_login_redirect', 10, 3 );

/**
 * Handle direct login event redirect
 */
if ( ! function_exists( 'cora_real_estate_ai_on_wp_login' ) ) {
function cora_real_estate_ai_on_wp_login( $user_login, $user ) {
    if ( defined( 'DOING_AJAX' ) && DOING_AJAX ) {
        return;
    }
    if ( $user instanceof WP_User ) {
        $allowed_roles = array( 'administrator', 'cora_manager', 'cora_branch_manager', 'cora_photographer', 'cora_videographer', 'cora_drone_pilot', 'cora_editor', 'cora_viewer' );
        foreach ( $allowed_roles as $role ) {
            if ( in_array( $role, (array) $user->roles ) ) {
                $onb_done = get_user_meta( $user->ID, 'cora_onboarding_completed', true );
                if ( $onb_done !== '1' ) {
                    wp_redirect( home_url( '/workspace/onboarding' ) );
                } else {
                    wp_redirect( home_url( '/workspace' ) );
                }
                exit;
            }
        }
    }
}
}
add_action( 'wp_login', 'cora_real_estate_ai_on_wp_login', 10, 2 );

/**
 * Restrict non-administrators from accessing the default WP Admin backend entirely
 */
if ( ! function_exists( 'cora_real_estate_ai_restrict_admin_access' ) ) {
function cora_real_estate_ai_restrict_admin_access() {
    if ( is_admin() && ! ( defined( 'DOING_AJAX' ) && DOING_AJAX ) ) {
        if ( current_user_can( 'manage_options' ) ) {
            return;
        }
        $user = wp_get_current_user();
        $roles = (array) $user->roles;
        if ( in_array( 'cora_super_admin', $roles, true ) || in_array( 'cora_shruti', $roles, true ) ) {
            return;
        }
        wp_redirect( home_url( '/workspace' ) );
        exit;
    }
}
}
add_action( 'admin_init', 'cora_real_estate_ai_restrict_admin_access' );

