/**
 * AJAX Action: Submit Blog Lead
 */
if ( ! function_exists( 'cora_ajax_submit_blog_lead' ) ) {
function cora_ajax_submit_blog_lead() {
    global $wpdb;
    $post_id    = isset( $_POST['post_id'] ) ? intval( $_POST['post_id'] ) : 0;
    $first_name = isset( $_POST['first_name'] ) ? sanitize_text_field( $_POST['first_name'] ) : '';
    $last_name  = isset( $_POST['last_name'] ) ? sanitize_text_field( $_POST['last_name'] ) : '';
    $email      = isset( $_POST['email'] ) ? sanitize_email( $_POST['email'] ) : '';
    $phone      = isset( $_POST['phone'] ) ? sanitize_text_field( $_POST['phone'] ) : '';
    $notes      = isset( $_POST['notes'] ) ? sanitize_textarea_field( $_POST['notes'] ) : '';

    if ( empty( $first_name ) || empty( $email ) ) {
        wp_send_json_error( 'Name and email are required.' );
    }

    $lead_data = array(
        'agency_id'     => 1,
        'branch_id'     => 1,
        'first_name'    => $first_name,
        'last_name'     => $last_name,
        'email'         => $email,
        'phone'         => $phone,
        'source'        => 'Blog Post ID: ' . $post_id,
        'status'        => 'new',
        'notes'         => $notes,
        'created_at'    => current_time('mysql'),
        'updated_at'    => current_time('mysql')
    );

    $inserted = $wpdb->insert(
        $wpdb->prefix . 'cora_leads',
        $lead_data,
        array( '%d', '%d', '%s', '%s', '%s', '%s', '%s', '%s', '%s', '%s', '%s' )
    );

    if ( $inserted ) {
        $inserted_id = $wpdb->insert_id;
        $leads_opt = get_option( 'cora_workspace_leads', array() );
        if ( ! is_array( $leads_opt ) ) {
            $leads_opt = array();
        }
        $leads_opt[] = array(
            'id'         => $inserted_id,
            'names'      => trim( $first_name . ' ' . $last_name ),
            'email'      => $email,
            'phone'      => $phone,
            'source'     => 'Blog Post ID: ' . $post_id,
            'status'     => 'new',
            'notes'      => $notes,
            'created_at' => time()
        );
        update_option( 'cora_workspace_leads', $leads_opt );

        cora_sync_db_tables_to_options();
        wp_send_json_success( array( 'message' => 'Your request was submitted successfully!' ) );
    } else {
        wp_send_json_error( 'Failed to submit request.' );
    }
}
}
add_action( 'wp_ajax_cora_submit_blog_lead', 'cora_ajax_submit_blog_lead' );
add_action( 'wp_ajax_nopriv_cora_submit_blog_lead', 'cora_ajax_submit_blog_lead' );

/**
 * AJAX Action: Editor Slash Command Search
 * Lightweight, transient-cached search for articles, listings, and equipment.
 * Returns max 8 results. Cache TTL: 60 seconds.
 */
if ( ! function_exists( 'cora_ajax_editor_search' ) ) {
function cora_ajax_editor_search() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );

    $type  = isset( $_POST['type'] ) ? sanitize_key( $_POST['type'] ) : '';
    $query = isset( $_POST['q'] )    ? sanitize_text_field( $_POST['q'] ) : '';

    if ( ! in_array( $type, array( 'article', 'listing', 'equipment' ), true ) ) {
        wp_send_json_error( 'Invalid type.' );
    }

    // Transient cache key — safe, short-lived
    $cache_key = 'cora_es_' . $type . '_' . md5( $query );
    $cached    = get_transient( $cache_key );
    if ( false !== $cached ) {
        wp_send_json_success( $cached );
        return;
    }

    $results = array();

    if ( $type === 'article' ) {
        $args = array(
            'post_type'      => 'post',
            'post_status'    => array( 'publish', 'draft', 'pending' ),
            'posts_per_page' => 8,
            'orderby'        => 'modified',
            'order'          => 'DESC',
            'no_found_rows'  => true,  // Performance: skip pagination count
            'fields'         => 'all',
        );
        if ( ! empty( $query ) ) {
            $args['s'] = $query;
        }
        $wp_query = new WP_Query( $args );
        foreach ( $wp_query->posts as $post ) {
            $thumb_id  = get_post_thumbnail_id( $post->ID );
            $thumb_url = $thumb_id ? wp_get_attachment_image_url( $thumb_id, 'thumbnail' ) : '';
            $results[] = array(
                'id'        => $post->ID,
                'title'     => $post->post_title ?: '(Untitled)',
                'url'       => get_permalink( $post->ID ),
                'status'    => $post->post_status,
                'thumb'     => $thumb_url,
                'excerpt'   => wp_trim_words( $post->post_excerpt ?: $post->post_content, 12, '…' ),
            );
        }
        wp_reset_postdata();

    } else {
        // listings and equipment share the same cached WP option
        $inventory = get_option( 'cora_workspace_listings_inventory', array() );
        if ( ! is_array( $inventory ) ) {
            $inventory = array();
        }

        $category_filter = ( $type === 'equipment' ) ? null : null; // future: filter by category
        $count = 0;
        foreach ( $inventory as $item ) {
            if ( $count >= 8 ) break;
            $name = isset( $item['name'] ) ? $item['name'] : '';
            if ( ! empty( $query ) && stripos( $name, $query ) === false ) {
                continue;
            }
            $results[] = array(
                'id'       => isset( $item['id'] ) ? $item['id'] : '',
                'title'    => $name,
                'category' => isset( $item['category'] ) ? $item['category'] : '',
                'status'   => isset( $item['status'] ) ? $item['status'] : '',
                'thumb'    => isset( $item['photo_url'] ) ? $item['photo_url'] : '',
                'rera'     => isset( $item['rera_reg_id'] ) ? $item['rera_reg_id'] : '',
                'notes'    => isset( $item['notes'] ) ? wp_trim_words( $item['notes'], 10, '…' ) : '',
            );
            $count++;
        }
    }

    // Cache for 60 seconds to prevent repeated DB/option hits
    set_transient( $cache_key, $results, 60 );
    wp_send_json_success( $results );
}
}
add_action( 'wp_ajax_cora_editor_search', 'cora_ajax_editor_search' );

/**
 * AJAX Action: Get captured leads for Blog Post Drawer
 */
if ( ! function_exists( 'cora_ajax_get_article_leads' ) ) {
