/**
 * AJAX Action: Analyze SEO
 */
if ( ! function_exists( 'cora_ajax_analyze_seo' ) ) {
function cora_ajax_analyze_seo() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );

    $title = isset($_POST['title']) ? sanitize_text_field($_POST['title']) : '';
    $content = isset($_POST['content']) ? wp_kses_post($_POST['content']) : '';

    $score = 50; // Base score
    
    // Word count calculation
    $word_count = str_word_count(strip_tags($content));
    if ($word_count > 500) $score += 20;
    elseif ($word_count > 300) $score += 10;
    
    // Content structure
    if (strpos($content, '<h') !== false) $score += 10; // Uses headings
    if (strpos($content, '<ul>') !== false || strpos($content, '<ol>') !== false) $score += 5; // Uses lists
    
    // Title length
    $title_length = strlen($title);
    if ($title_length > 30 && $title_length < 65) $score += 15;

    $score = min($score, 100);

    wp_send_json_success(array('score' => $score));
}
}
add_action( 'wp_ajax_cora_analyze_seo', 'cora_ajax_analyze_seo' );

/**
 * AJAX Action: Fetch SEO Article Data
 */
if ( ! function_exists( 'cora_ajax_fetch_seo_article' ) ) {
function cora_ajax_fetch_seo_article() {
    if ( ! is_user_logged_in() ) {
        wp_send_json_error( 'Permission denied.' );
    }

    $post_id = isset( $_REQUEST['post_id'] ) ? intval( $_REQUEST['post_id'] ) : 0;
    if ( ! $post_id ) {
        wp_send_json_error( 'Invalid Post ID.' );
    }

    $post = get_post( $post_id );
    if ( ! $post ) {
        wp_send_json_error( 'Post not found.' );
    }

    $focus_keyword    = get_post_meta( $post->ID, '_cora_focus_keyword', true );
    $meta_title       = get_post_meta( $post->ID, '_cora_seo_title', true );
    $meta_description = get_post_meta( $post->ID, '_cora_meta_description', true );
    $seo_score        = get_post_meta( $post->ID, '_cora_seo_score', true );
    $canonical_url    = get_post_meta( $post->ID, '_cora_canonical_url', true );
    $geo_score        = get_post_meta( $post->ID, '_cora_geo_score', true );

    $clean_content = wp_strip_all_tags( $post->post_content );
    $word_count    = str_word_count( $clean_content );
    $last_analyzed = get_the_modified_date( 'Y-m-d H:i:s', $post->ID );

    wp_send_json_success( array(
        'post_id'          => $post->ID,
        'title'            => $post->post_title,
        'content'          => $post->post_content,
        'slug'             => $post->post_name,
        'word_count'       => $word_count,
        'focus_keyword'    => $focus_keyword ? $focus_keyword : '',
        'meta_title'       => $meta_title ? $meta_title : '',
        'meta_description' => $meta_description ? $meta_description : '',
        'canonical_url'    => $canonical_url ? $canonical_url : '',
        'seo_score'        => ( $seo_score !== '' ) ? intval( $seo_score ) : 0,
        'geo_score'        => ( $geo_score !== '' ) ? intval( $geo_score ) : 0,
        'last_analyzed'    => $last_analyzed ? $last_analyzed : '',
    ) );
}
}
add_action( 'wp_ajax_cora_fetch_seo_article', 'cora_ajax_fetch_seo_article' );
add_action( 'wp_ajax_nopriv_cora_fetch_seo_article', 'cora_ajax_fetch_seo_article' );

/**
 * AJAX Action: Run 11-Point SEO Audit
 */
if ( ! function_exists( 'cora_ajax_run_11point_seo_audit' ) ) {
function cora_ajax_run_11point_seo_audit() {
    if ( ! is_user_logged_in() ) {
        wp_send_json_error( 'Permission denied.' );
    }

    $post_id          = isset( $_REQUEST['post_id'] ) ? intval( $_REQUEST['post_id'] ) : 0;
    $focus_keyword    = isset( $_REQUEST['focus_keyword'] ) ? sanitize_text_field( $_REQUEST['focus_keyword'] ) : '';
    $meta_title       = isset( $_REQUEST['meta_title'] ) ? sanitize_text_field( $_REQUEST['meta_title'] ) : '';
    $meta_description = isset( $_REQUEST['meta_description'] ) ? sanitize_textarea_field( $_REQUEST['meta_description'] ) : '';
    $slug             = isset( $_REQUEST['slug'] ) ? sanitize_title( $_REQUEST['slug'] ) : '';

    if ( ! $post_id ) {
        wp_send_json_error( 'Invalid Post ID.' );
    }

    $post = get_post( $post_id );
    if ( ! $post ) {
        wp_send_json_error( 'Post not found.' );
    }

    $content    = $post->post_content;
    $post_title = $post->post_title;
    $post_slug  = $slug ? $slug : $post->post_name;

    if ( empty( $focus_keyword ) ) {
        $focus_keyword = get_post_meta( $post_id, '_cora_focus_keyword', true );
        if ( empty( $focus_keyword ) ) {
            $title_words = preg_split( '/\s+/', trim( $post_title ) );
            $focus_keyword = implode( ' ', array_slice( $title_words, 0, min( 4, count( $title_words ) ) ) );
        }
    }
    if ( empty( $meta_title ) ) {
        $meta_title = get_post_meta( $post_id, '_cora_seo_title', true );
        if ( empty( $meta_title ) ) {
            $meta_title = $post_title;
        }
    }
    if ( empty( $meta_description ) ) {
        $meta_description = get_post_meta( $post_id, '_cora_meta_description', true );
    }

    $clean_content = wp_strip_all_tags( $content );
    $word_count    = str_word_count( $clean_content );
    $kw_lower      = mb_strtolower( trim( $focus_keyword ) );

    // Extended Readability & Media Calculations
    $reading_time_mins = max( 1, (int) ceil( $word_count / 200 ) );

    preg_match_all( '/<img[^>]*>/i', $content, $img_matches );
    $image_count = count( $img_matches[0] ?? array() );

    $images_with_alt_count = 0;
    if ( ! empty( $img_matches[0] ) ) {
        foreach ( $img_matches[0] as $img_tag ) {
            if ( preg_match( '/alt=["\'](?!["\'])\s*[^"\']+\s*["\']/i', $img_tag ) ) {
                $images_with_alt_count++;
            }
        }
    }

    preg_match_all( '/<h[23][^>]*>/i', $content, $h_matches );
    $header_count = count( $h_matches[0] ?? array() );

    // Flesch Reading Ease score calculation
    $sentence_count  = max( 1, preg_match_all( '/[.!?]+(\s+|$)/', $clean_content, $s_m ) );
    $words_list      = preg_split( '/\s+/', $clean_content );
    $total_syllables = 0;
    foreach ( $words_list as $w ) {
        $w_clean = strtolower( trim( preg_replace( '/[^a-zA-Z]/', '', $w ) ) );
        if ( empty( $w_clean ) ) continue;
        if ( strlen( $w_clean ) <= 3 ) {
            $total_syllables += 1;
            continue;
        }
        $syllable_matches = preg_match_all( '/[aeiouy]{1,2}/i', $w_clean, $syl_m );
        if ( substr( $w_clean, -1 ) === 'e' && substr( $w_clean, -2 ) !== 'le' ) {
            $syllable_matches--;
        }
        $total_syllables += max( 1, $syllable_matches );
    }

    if ( $word_count > 50 && $sentence_count > 0 ) {
        $flesch_calc = 206.835 - ( 1.015 * ( $word_count / $sentence_count ) ) - ( 84.6 * ( $total_syllables / $word_count ) );
        $flesch_num  = max( 15, min( 98, intval( round( $flesch_calc ) ) ) );
    } else {
        $flesch_num = 75;
    }

    if ( $flesch_num >= 85 )     $flesch_label = 'Very Easy to Read';
    elseif ( $flesch_num >= 70 ) $flesch_label = 'Easy to Read';
    elseif ( $flesch_num >= 60 ) $flesch_label = 'Fairly Easy to Read';
    elseif ( $flesch_num >= 50 ) $flesch_label = 'Standard Readability';
    elseif ( $flesch_num >= 35 ) $flesch_label = 'Fairly Difficult';
    else                         $flesch_label = 'Difficult to Read';

    $readability_score = sprintf( '%d/100 (%s)', $flesch_num, $flesch_label );

    // Core Web Vitals dynamic metrics
    $perf_num = 96;
    if ( $image_count > 4 ) $perf_num -= 3;
    if ( $images_with_alt_count < $image_count ) $perf_num -= 4;
    if ( $word_count > 2000 ) $perf_num -= 2;
    if ( $word_count < 400 ) $perf_num -= 6;
    $perf_num = max( 60, min( 98, $perf_num ) );

    $performance_score = sprintf( '%d%%', $perf_num );
    $lcp               = sprintf( '%.1fs - %s', max( 0.8, min( 3.5, 1.0 + ( $word_count / 1500 ) * 0.5 + ( $image_count * 0.2 ) ) ), ( $perf_num >= 85 ? 'Fast' : 'Moderate' ) );
    $cls               = sprintf( '%.2f - %s', max( 0.01, min( 0.15, 0.01 + ( $image_count * 0.02 ) ) ), 'Good' );
    $fcp               = sprintf( '%.1fs - %s', max( 0.5, min( 2.5, 0.6 + ( $word_count / 2000 ) * 0.4 ) ), 'Fast' );

    // 1. word_count: Word count >= 1000 (Pass/Fail)
    $passed_1 = ( $word_count >= 1000 );
    $msg_1    = $passed_1
        ? sprintf( 'Word count is %d (meets 1,000+ recommendation)', $word_count )
        : sprintf( 'Word count is %d (recommended minimum: 1,000 words)', $word_count );
    $rec_1    = $passed_1
        ? 'Great content depth! Ensure long-form sections remain easy to skim with subheadings and bullet points.'
        : 'Expand your article to at least 1,000 words. Add detailed explanations, real-world examples, or an FAQ section.';

    // 2. keyword_in_title: Focus keyword present in Meta Title or Post Title
    $passed_2 = ( $kw_lower !== '' && ( mb_stripos( $meta_title, $kw_lower ) !== false || mb_stripos( $post_title, $kw_lower ) !== false ) );
    $msg_2    = $passed_2
        ? 'Focus keyword is present in the page or meta title'
        : 'Focus keyword missing from page title or meta title';
    $rec_2    = $passed_2
        ? 'Title is well-optimized with target focus keyword.'
        : 'Place your focus keyword near the beginning of your Meta Title and Post Title to increase keyword relevance in SERPs.';

    // 3. keyword_in_h1: Focus keyword present in H1 / Title
    $passed_3 = false;
    if ( $kw_lower !== '' ) {
        if ( mb_stripos( $post_title, $kw_lower ) !== false ) {
            $passed_3 = true;
        } elseif ( preg_match_all( '/<h1[^>]*>(.*?)<\/h1>/is', $content, $h1_matches ) ) {
            foreach ( $h1_matches[1] as $h1_text ) {
                if ( mb_stripos( wp_strip_all_tags( $h1_text ), $kw_lower ) !== false ) {
                    $passed_3 = true;
                    break;
                }
            }
        }
    }
    $msg_3 = $passed_3
        ? 'Focus keyword present in H1 heading or post title'
        : 'Focus keyword not found in H1 header tag';
    $rec_3 = $passed_3
        ? 'H1 main header properly incorporates focus keyword.'
        : 'Ensure your main H1 title tag explicitly includes your primary focus keyword.';

    // 4. h2_present: Post content contains <h2> or <h3> tags
    $passed_4 = ( $header_count >= 2 );
    $msg_4    = $passed_4
        ? sprintf( 'Post content contains %d subheadings (H2/H3)', $header_count )
        : 'No H2 or H3 heading tags found in content';
    $rec_4    = $passed_4
        ? 'Clear structural hierarchy detected across subheadings.'
        : 'Break up long text blocks by introducing clear H2 and H3 subheadings to structure your article.';

    // 5. keyword_first_paragraph: Focus keyword appears in first 150 words of content
    $words_array     = preg_split( '/\s+/', $clean_content, 151 );
    $first_150_words = implode( ' ', array_slice( $words_array, 0, 150 ) );
    $passed_5        = ( $kw_lower !== '' && mb_stripos( $first_150_words, $kw_lower ) !== false );
    $msg_5           = $passed_5
        ? 'Focus keyword appears in the first 150 words of content'
        : 'Focus keyword does not appear in the opening paragraph (first 150 words)';
    $rec_5           = $passed_5
        ? 'Opening paragraph successfully establishes topic focus.'
        : 'Incorporate your primary focus keyword within the first 150 words (opening paragraph) to signal relevance immediately.';

    // 6. keyword_density: Focus keyword density between 0.8% and 2.5%
    $kw_density_pct = 0.0;
    if ( $word_count > 0 && $kw_lower !== '' ) {
        $kw_occurrences = mb_substr_count( mb_strtolower( $clean_content ), $kw_lower );
        $kw_word_len    = max( 1, count( preg_split( '/\s+/', $kw_lower ) ) );
        $kw_density_pct = round( ( ( $kw_occurrences * $kw_word_len ) / $word_count ) * 100, 2 );
    }
    $passed_6 = ( $kw_density_pct >= 0.8 && $kw_density_pct <= 2.5 );
    $msg_6    = $passed_6
        ? sprintf( 'Focus keyword density is optimal at %.2f%%', $kw_density_pct )
        : sprintf( 'Focus keyword density is %.2f%% (target range: 0.8%% - 2.5%%)', $kw_density_pct );
    $rec_6    = $passed_6
        ? 'Keyword frequency is balanced without over-optimization.'
        : ( $kw_density_pct < 0.8
            ? 'Increase keyword frequency slightly throughout your body copy to achieve at least 0.8% density.'
            : 'Reduce keyword occurrences to keep density under 2.5% and prevent search penalty for keyword stuffing.' );

    // 7. meta_title_len: Meta Title length between 45 and 65 chars
    $meta_title_len = mb_strlen( trim( $meta_title ) );
    $passed_7       = ( $meta_title_len >= 45 && $meta_title_len <= 65 );
    $msg_7          = $passed_7
        ? sprintf( 'Meta Title length is %d chars (45-65 chars)', $meta_title_len )
        : sprintf( 'Meta Title length is %d chars (recommended: 45-65 chars)', $meta_title_len );
    $rec_7          = $passed_7
        ? 'Meta Title character length fits search result displays well.'
        : ( $meta_title_len < 45
            ? 'Extend your Meta Title to 45-65 characters to maximize search snippet visibility.'
            : 'Shorten your Meta Title to under 65 characters to prevent truncation in Google SERPs.' );

    // 8. meta_desc_len: Meta Description length between 120 and 165 chars
    $meta_desc_len = mb_strlen( trim( $meta_description ) );
    $passed_8      = ( $meta_desc_len >= 120 && $meta_desc_len <= 165 );
    $msg_8         = $passed_8
        ? sprintf( 'Meta Description length is %d chars (120-165 chars)', $meta_desc_len )
        : sprintf( 'Meta Description length is %d chars (recommended: 120-165 chars)', $meta_desc_len );
    $rec_8         = $passed_8
        ? 'Meta Description is well-crafted within recommended bounds.'
        : ( $meta_desc_len < 120
            ? 'Expand your Meta Description to 120-165 characters to provide a full summary and call to action.'
            : 'Trim your Meta Description to under 165 characters to avoid snippet truncation.' );

    // 9. slug_clean: URL slug contains hyphens and focus keyword
    $sanitized_kw   = sanitize_title( $focus_keyword );
    $has_hyphen     = ( strpos( $post_slug, '-' ) !== false );
    $has_kw_in_slug = ( ! empty( $sanitized_kw ) && strpos( $post_slug, $sanitized_kw ) !== false );
    $passed_9       = ( $has_hyphen && $has_kw_in_slug );
    $msg_9          = $passed_9
        ? 'URL slug contains hyphens and focus keyword'
        : 'URL slug should contain hyphens and the focus keyword';
    $rec_9          = $passed_9
        ? 'Permalink slug follows search engine best practices.'
        : 'Format URL slug with lowercase hyphens and include target focus keyword (e.g. /my-focus-keyword).';

    // 10. internal_links: Content contains <a href="..."> links
    $passed_10 = ( preg_match( '/<a\s+[^>]*href=["\'][^"\']+["\'][^>]*>/i', $content ) === 1 );
    $msg_10    = $passed_10
        ? 'Content contains internal or external links'
        : 'No links (<a href="...">) found in content';
    $rec_10    = $passed_10
        ? 'Link architecture connects to additional relevant resources.'
        : 'Add contextual internal links to related website posts or authoritative external sources.';

    // 11. has_schema: Schema markup or structured JSON-LD present
    $has_json_ld     = ( preg_match( '/<script[^>]*type=["\']application\/ld\+json["\'][^>]*>/i', $content ) === 1 );
    $has_itemscope   = ( strpos( $content, 'itemscope' ) !== false );
    $has_meta_schema = ! empty( get_post_meta( $post_id, '_cora_schema_markup', true ) );
    $passed_11       = ( $has_json_ld || $has_itemscope || $has_meta_schema );
    $msg_11          = $passed_11
        ? 'Schema markup or structured JSON-LD detected'
        : 'No schema markup or structured JSON-LD present';
    $rec_11          = $passed_11
        ? 'Structured JSON-LD schema empowers search engines to extract rich snippets.'
        : 'Add JSON-LD Schema (Article, NewsArticle, or FAQPage) to qualify for rich snippets and AI answer engines.';

    $checklist = array(
        array(
            'id'                        => 'word_count',
            'label'                     => 'Word Count (>= 1000 words)',
            'passed'                    => $passed_1,
            'message'                   => $msg_1,
            'actionable_recommendation' => $rec_1,
            'recommendation'            => $rec_1,
        ),
        array(
            'id'                        => 'keyword_in_title',
            'label'                     => 'Focus Keyword in Meta Title or Post Title',
            'passed'                    => $passed_2,
            'message'                   => $msg_2,
            'actionable_recommendation' => $rec_2,
            'recommendation'            => $rec_2,
        ),
        array(
            'id'                        => 'keyword_in_h1',
            'label'                     => 'Focus Keyword in H1 / Title',
            'passed'                    => $passed_3,
            'message'                   => $msg_3,
            'actionable_recommendation' => $rec_3,
            'recommendation'            => $rec_3,
        ),
        array(
            'id'                        => 'h2_present',
            'label'                     => 'Subheadings (H2 or H3 tags present)',
            'passed'                    => $passed_4,
            'message'                   => $msg_4,
            'actionable_recommendation' => $rec_4,
            'recommendation'            => $rec_4,
        ),
        array(
            'id'                        => 'keyword_first_paragraph',
            'label'                     => 'Focus Keyword in First 150 Words',
            'passed'                    => $passed_5,
            'message'                   => $msg_5,
            'actionable_recommendation' => $rec_5,
            'recommendation'            => $rec_5,
        ),
        array(
            'id'                        => 'keyword_density',
            'label'                     => 'Keyword Density (0.8% - 2.5%)',
            'passed'                    => $passed_6,
            'message'                   => $msg_6,
            'actionable_recommendation' => $rec_6,
            'recommendation'            => $rec_6,
        ),
        array(
            'id'                        => 'meta_title_len',
            'label'                     => 'Meta Title Length (45-65 chars)',
            'passed'                    => $passed_7,
            'message'                   => $msg_7,
            'actionable_recommendation' => $rec_7,
            'recommendation'            => $rec_7,
        ),
        array(
            'id'                        => 'meta_desc_len',
            'label'                     => 'Meta Description Length (120-165 chars)',
            'passed'                    => $passed_8,
            'message'                   => $msg_8,
            'actionable_recommendation' => $rec_8,
            'recommendation'            => $rec_8,
        ),
        array(
            'id'                        => 'slug_clean',
            'label'                     => 'URL Slug Formatting & Focus Keyword',
            'passed'                    => $passed_9,
            'message'                   => $msg_9,
            'actionable_recommendation' => $rec_9,
            'recommendation'            => $rec_9,
        ),
        array(
            'id'                        => 'internal_links',
            'label'                     => 'Content Links (<a href="...">)',
            'passed'                    => $passed_10,
            'message'                   => $msg_10,
            'actionable_recommendation' => $rec_10,
            'recommendation'            => $rec_10,
        ),
        array(
            'id'                        => 'has_schema',
            'label'                     => 'Schema Markup or Structured JSON-LD',
            'passed'                    => $passed_11,
            'message'                   => $msg_11,
            'actionable_recommendation' => $rec_11,
            'recommendation'            => $rec_11,
        ),
    );

    $passed_count = 0;
    foreach ( $checklist as $item ) {
        if ( $item['passed'] ) {
            $passed_count++;
        }
    }

    $seo_score = intval( round( ( $passed_count / 11 ) * 100 ) );

    // Calculate GEO AI Visibility Score dynamically based on search engine factors
    $geo_weights = 0;
    if ( $passed_1 )  $geo_weights += 20; // 1000+ words depth
    if ( $passed_4 )  $geo_weights += 20; // H2/H3 structural hierarchy
    if ( $passed_11 ) $geo_weights += 20; // Schema JSON-LD structured data
    if ( $passed_5 )  $geo_weights += 15; // KW in opening paragraph
    if ( $passed_8 )  $geo_weights += 15; // Optimal meta description
    if ( $passed_10 ) $geo_weights += 10; // Outbound / internal context links
    $geo_score = min( 100, $geo_weights );

    // Update post meta with calculated scores
    update_post_meta( $post_id, '_cora_seo_score', $seo_score );
    update_post_meta( $post_id, '_cora_geo_score', $geo_score );

    wp_send_json_success( array(
        'seo_score'             => $seo_score,
        'geo_score'             => $geo_score,
        'kw_density_pct'        => $kw_density_pct,
        'passed_count'          => $passed_count,
        'total_count'           => 11,
        'checklist'             => $checklist,
        'readability_score'     => $readability_score,
        'flesch_score'          => $flesch_num,
        'flesch_label'          => $flesch_label,
        'reading_time_mins'     => $reading_time_mins,
        'word_count'            => $word_count,
        'image_count'           => $image_count,
        'images_with_alt_count' => $images_with_alt_count,
        'alt_image_count'       => $images_with_alt_count,
        'header_count'          => $header_count,
        'performance_score'     => $performance_score,
        'lcp'                   => $lcp,
        'cls'                   => $cls,
        'fcp'                   => $fcp,
        'core_web_vitals'       => array(
            'performance_score' => $performance_score,
            'lcp'               => $lcp,
            'cls'               => $cls,
            'fcp'               => $fcp,
        ),
    ) );
}
}
add_action( 'wp_ajax_cora_run_11point_seo_audit', 'cora_ajax_run_11point_seo_audit' );
add_action( 'wp_ajax_nopriv_cora_run_11point_seo_audit', 'cora_ajax_run_11point_seo_audit' );

/**
 * AJAX Action: Save SEO Meta
 */
if ( ! function_exists( 'cora_ajax_save_seo_meta' ) ) {
function cora_ajax_save_seo_meta() {
    $post_id          = isset( $_REQUEST['post_id'] ) ? intval( $_REQUEST['post_id'] ) : 0;
    $focus_keyword    = isset( $_REQUEST['focus_keyword'] ) ? sanitize_text_field( $_REQUEST['focus_keyword'] ) : '';
    $meta_title       = isset( $_REQUEST['meta_title'] ) ? sanitize_text_field( $_REQUEST['meta_title'] ) : '';
    $meta_description = isset( $_REQUEST['meta_description'] ) ? sanitize_textarea_field( $_REQUEST['meta_description'] ) : '';
    $slug             = isset( $_REQUEST['slug'] ) ? sanitize_title( $_REQUEST['slug'] ) : '';
    $canonical_url    = isset( $_REQUEST['canonical_url'] ) ? esc_url_raw( $_REQUEST['canonical_url'] ) : '';

    if ( ! $post_id ) {
        wp_send_json_error( 'Invalid Post ID.' );
    }

    $post = get_post( $post_id );
    if ( ! $post ) {
        wp_send_json_error( 'Post not found.' );
    }

    update_post_meta( $post_id, '_cora_focus_keyword', $focus_keyword );
    update_post_meta( $post_id, '_cora_seo_title', $meta_title );
    update_post_meta( $post_id, '_cora_meta_description', $meta_description );
    update_post_meta( $post_id, '_cora_canonical_url', $canonical_url );

    if ( ! empty( $slug ) ) {
        global $wpdb;
        $sanitized_slug = sanitize_title( $slug );
        $wpdb->update(
            $wpdb->posts,
            array( 'post_name' => $sanitized_slug ),
            array( 'ID' => $post_id ),
            array( '%s' ),
            array( '%d' )
        );
        clean_post_cache( $post_id );
    }

    wp_send_json_success( array(
        'message' => 'SEO Meta saved successfully!',
    ) );
}
}
add_action( 'wp_ajax_cora_save_seo_meta', 'cora_ajax_save_seo_meta' );

/**
 * AJAX Action: Fetch Media Library
 */
if ( ! function_exists( 'cora_ajax_get_media' ) ) {
function cora_ajax_get_media() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );
    
    $folder_id = isset($_POST['folder']) ? intval($_POST['folder']) : 0;
    
    $query_images_args = array(
        'post_type'      => 'attachment',
        'post_mime_type' => 'image',
        'post_status'    => 'inherit',
        'posts_per_page' => 100,
        'orderby'        => 'date',
        'order'          => 'DESC'
    );
    
    if ($folder_id > 0) {
        $query_images_args['tax_query'] = array(
            array(
                'taxonomy' => 'cora_media_folder',
                'field'    => 'term_id',
                'terms'    => $folder_id,
            )
        );
    } else {
        // If root, we might want to show all, or only those without a folder. 
        // For simplicity, root shows everything, but organized into folders if needed.
    }

    $query_images = new WP_Query( $query_images_args );
    $images = array();
    
    foreach ( $query_images->posts as $image ) {
        $images[] = array(
            'id'  => $image->ID,
            'url' => wp_get_attachment_url( $image->ID )
        );
    }
    
    // Also fetch all media folders
    $folders = get_terms( array(
        'taxonomy' => 'cora_media_folder',
        'hide_empty' => false,
    ) );
    
    $formatted_folders = array();
    if (!is_wp_error($folders)) {
        foreach ($folders as $folder) {
            $formatted_folders[] = array(
                'id' => $folder->term_id,
                'name' => $folder->name,
                'count' => $folder->count
            );
        }
    }
    
    wp_send_json_success(array('images' => $images, 'folders' => $formatted_folders));
}
}
add_action( 'wp_ajax_cora_get_media', 'cora_ajax_get_media' );

/**
 * AJAX Action: Create Media Folder
 */
if ( ! function_exists( 'cora_ajax_create_media_folder' ) ) {
function cora_ajax_create_media_folder() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );
    $name = isset($_POST['name']) ? sanitize_text_field($_POST['name']) : '';
    if (empty($name)) {
        wp_send_json_error('Folder name is required.');
    }
    
    $term = wp_insert_term($name, 'cora_media_folder');
    if (is_wp_error($term)) {
        wp_send_json_error($term->get_error_message());
    }
    
    wp_send_json_success(array(
        'id' => $term['term_id'],
        'name' => $name
    ));
}
}
add_action( 'wp_ajax_cora_create_media_folder', 'cora_ajax_create_media_folder' );

/**
 * AJAX Action: Upload Media
 */
if ( ! function_exists( 'cora_ajax_upload_media' ) ) {
function cora_ajax_upload_media() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );
    
    if ( empty($_FILES['file']) ) {
        wp_send_json_error('No file provided.');
    }
    
    $file = $_FILES['file'];
    
    require_once( ABSPATH . 'wp-admin/includes/image.php' );
    require_once( ABSPATH . 'wp-admin/includes/file.php' );
    require_once( ABSPATH . 'wp-admin/includes/media.php' );
    
    // Check for upload errors
    if ($file['error'] !== UPLOAD_ERR_OK) {
        wp_send_json_error('Upload failed with error code: ' . $file['error']);
    }
    
    // Use media_handle_sideload because we are dealing with $_FILES directly but outside the typical admin post form
    $upload_overrides = array( 'test_form' => false );
    $movefile = wp_handle_upload( $file, $upload_overrides );
    
    if ( $movefile && ! isset( $movefile['error'] ) ) {
        $filename = $movefile['file'];
        $attachment = array(
            'post_mime_type' => $movefile['type'],
            'post_title'     => preg_replace( '/\.[^.]+$/', '', basename( $filename ) ),
            'post_content'   => '',
            'post_status'    => 'inherit'
        );
        $attachment_id = wp_insert_attachment( $attachment, $filename );
        $attach_data = wp_generate_attachment_metadata( $attachment_id, $filename );
        wp_update_attachment_metadata( $attachment_id, $attach_data );
        
        $folder_id = isset($_POST['folder']) ? intval($_POST['folder']) : 0;
        if ($folder_id > 0) {
            wp_set_object_terms($attachment_id, $folder_id, 'cora_media_folder');
        }

        $agency_id = cora_get_current_user_agency_id();
        $branch_id = cora_get_current_user_branch_id();
        if ( ! empty( $agency_id ) ) {
            update_post_meta( $attachment_id, 'cora_agency_id', $agency_id );
        }
        if ( ! empty( $branch_id ) ) {
            update_post_meta( $attachment_id, 'cora_branch_id', $branch_id );
        }
        
        wp_send_json_success(array(
            'id' => $attachment_id,
            'url' => wp_get_attachment_url($attachment_id)
        ));
    } else {
        wp_send_json_error($movefile['error']);
    }
}
}
add_action( 'wp_ajax_cora_upload_media', 'cora_ajax_upload_media' );

/**
 * AJAX Action: Assign Media to Folder
 */
if ( ! function_exists( 'cora_ajax_assign_media_folder' ) ) {
function cora_ajax_assign_media_folder() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );
    
    $folder_id = isset($_POST['folder']) ? intval($_POST['folder']) : 0;
    $attachments = isset($_POST['attachments']) ? $_POST['attachments'] : array();
    
    if ($folder_id > 0 && !empty($attachments) && is_array($attachments)) {
        foreach ($attachments as $attachment_id) {
            wp_set_object_terms(intval($attachment_id), $folder_id, 'cora_media_folder', true);
        }
        wp_send_json_success('Successfully assigned folder.');
    }
    wp_send_json_error('Invalid folder or attachments.');
}
}
add_action( 'wp_ajax_cora_assign_media_folder', 'cora_ajax_assign_media_folder' );

/**
 * AJAX Handler: Save Google Business Profile connection details
 */
if ( ! function_exists( 'cora_ajax_gbp_save_profile' ) ) {
function cora_ajax_gbp_save_profile() {
    check_ajax_referer( 'cora_ajax_nonce', 'security' );
    if ( ! current_user_can( 'manage_options' ) ) {
        wp_send_json_error( 'Unauthorized access.' );
    }

    $profile = array(
        'business_name'    => sanitize_text_field( $_POST['business_name'] ?? '' ),
        'category'         => sanitize_text_field( $_POST['category'] ?? '' ),
        'address'          => sanitize_text_field( $_POST['address'] ?? '' ),
        'phone'            => sanitize_text_field( $_POST['phone'] ?? '' ),
        'website'          => esc_url_raw( $_POST['website'] ?? '' ),
        'google_account'   => sanitize_email( $_POST['google_account'] ?? '' ),
        'connected'        => true,
        'connected_at'     => current_time( 'mysql' ),
    );

    if ( empty( $profile['business_name'] ) || empty( $profile['google_account'] ) ) {
        wp_send_json_error( 'Business name and Google account email are required.' );
    }

    update_option( 'cora_gbp_profile', $profile );
    wp_send_json_success( $profile );
}
}
add_action( 'wp_ajax_cora_gbp_save_profile', 'cora_ajax_gbp_save_profile' );

/**
 * AJAX Handler: Save a review reply to the GBP review log
 */
if ( ! function_exists( 'cora_ajax_gbp_save_review_reply' ) ) {
function cora_ajax_gbp_save_review_reply() {
    check_ajax_referer( 'cora_ajax_nonce', 'security' );
    if ( ! is_user_logged_in() ) {
        wp_send_json_error( 'Unauthorized.' );
    }

    $reviewer  = sanitize_text_field( $_POST['reviewer'] ?? '' );
    $reply     = sanitize_textarea_field( $_POST['reply'] ?? '' );
    $review_id = sanitize_text_field( $_POST['review_id'] ?? '' );

    if ( empty( $reply ) || empty( $reviewer ) ) {
        wp_send_json_error( 'Reviewer and reply text are required.' );
    }

    $replies = get_option( 'cora_gbp_review_replies', array() );
    $replies[ $review_id ] = array(
        'reviewer'   => $reviewer,
        'reply'      => $reply,
        'replied_at' => current_time( 'mysql' ),
    );
    update_option( 'cora_gbp_review_replies', $replies );

    wp_send_json_success( array( 'review_id' => $review_id, 'reply' => $reply ) );
}
}
add_action( 'wp_ajax_cora_gbp_save_review_reply', 'cora_ajax_gbp_save_review_reply' );

/**
 * AJAX Handler: Save / log a GBP post to the post history
 */
if ( ! function_exists( 'cora_ajax_gbp_save_post' ) ) {
function cora_ajax_gbp_save_post() {
    check_ajax_referer( 'cora_ajax_nonce', 'security' );
    if ( ! is_user_logged_in() ) {
        wp_send_json_error( 'Unauthorized.' );
    }

    $content  = sanitize_textarea_field( $_POST['content'] ?? '' );
    $geo_tag  = sanitize_text_field( $_POST['geo_tag'] ?? '' );
    $cta      = sanitize_text_field( $_POST['cta'] ?? '' );
    $schedule = sanitize_text_field( $_POST['schedule'] ?? 'now' );

    if ( empty( $content ) ) {
        wp_send_json_error( 'Post content cannot be empty.' );
    }

    $posts = get_option( 'cora_gbp_posts', array() );
    $new_post = array(
        'id'         => uniqid( 'gbp_post_' ),
        'content'    => $content,
        'geo_tag'    => $geo_tag,
        'cta'        => $cta,
        'schedule'   => $schedule,
        'status'     => ( $schedule === 'now' ) ? 'published' : 'scheduled',
        'created_at' => current_time( 'mysql' ),
    );
    array_unshift( $posts, $new_post );
    update_option( 'cora_gbp_posts', $posts );

    wp_send_json_success( $new_post );
}
}
add_action( 'wp_ajax_cora_gbp_save_post', 'cora_ajax_gbp_save_post' );

