    if ( ! empty( $api_key ) && str_replace( array('•', '*'), '', $api_key ) !== '' ) {
        update_option( 'cora_google_maps_api_key', $api_key );
    }

    wp_send_json_success( 'Google API Keys saved successfully.' );
