// CLIENT TASKS ENGINE AND REPOSITORIES

add_action( 'wp_ajax_cora_fetch_client_tasks', 'cora_ajax_fetch_client_tasks' );
if ( ! function_exists( 'cora_ajax_fetch_client_tasks' ) ) {
function cora_ajax_fetch_client_tasks() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );
    if ( ! current_user_can( 'read' ) ) {
        wp_send_json_error( 'Permission denied' );
    }

    $tasks = get_option('cora_workspace_client_tasks', array());
    if ( empty($tasks) ) {
        // Provide 1 clean default sample task
        $tasks = array(
            array(
                'id' => 'task_sample_101',
                'agency_id' => cora_get_current_user_agency_id() ?: 'default',
                'title' => 'Initial Project Onboarding & Scope',
                'client_id' => 'c1',
                'client_name' => 'Sample Client Project',
                'booking_id' => 'b1',
                'booking_title' => 'Sample Shoot Booking',
                'assignee_id' => 'u1',
                'assignee_name' => 'Team Member',
                'deliverable_type' => 'Planning',
                'priority' => 'high',
                'due_date' => date('Y-m-d', strtotime('+3 days')),
                'status' => 'in_progress',
                'desc' => 'Define project scope, timeline, and client deliverables.',
                'subtasks' => array(
                    array('id' => 'st_1', 'text' => 'Confirm project specifications', 'completed' => true),
                    array('id' => 'st_2', 'text' => 'Send welcome briefing packet', 'completed' => false)
                )
            )
        );
        update_option( 'cora_workspace_client_tasks', $tasks, false );
    }

    global $wpdb;
    
    // Clients
    $clients = array();
    $opt_clients = get_option('cora_workspace_clients', array());
    if ( is_array($opt_clients) && ! empty($opt_clients) ) {
        foreach ($opt_clients as $oc) {
            $clients[] = array(
                'id' => $oc['id'],
                'name' => $oc['names'] ?? $oc['name'] ?? 'Client'
            );
        }
    }
    if ( empty($clients) ) {
        $leads_table = $wpdb->prefix . 'cora_leads';
        if ( cora_table_exists( $leads_table ) ) {
            $agency_id = cora_db_get_agency_id();
            $db_clients = $wpdb->get_results($wpdb->prepare("SELECT id, name FROM {$leads_table} WHERE (status = 'client' OR status = 'converted') AND agency_id = %d ORDER BY name ASC", $agency_id), ARRAY_A);
            if ( ! empty($db_clients) ) {
                $clients = $db_clients;
            }
        }
    }
    if ( empty($clients) ) {
        $clients = array(
            array('id' => 'c1', 'name' => 'Sample Client Project')
        );
    }

    // Bookings
    $bookings = array();
    $bookings_table = $wpdb->prefix . 'cora_bookings';
    $leads_table = $wpdb->prefix . 'cora_leads';
    if ( cora_table_exists( $bookings_table ) ) {
        // Safe check for database columns to prevent SQL exceptions
        $has_deal_type = $wpdb->get_var("SHOW COLUMNS FROM {$bookings_table} LIKE 'deal_type'");
        $has_showing_date = $wpdb->get_var("SHOW COLUMNS FROM {$bookings_table} LIKE 'showing_date'");
        $has_package_value = $wpdb->get_var("SHOW COLUMNS FROM {$bookings_table} LIKE 'package_value'");
        $has_status = $wpdb->get_var("SHOW COLUMNS FROM {$bookings_table} LIKE 'status'");
        
        $select_fields = "b.id, b.lead_id as client_id";
        if ( $has_deal_type ) $select_fields .= ", b.deal_type";
        if ( $has_showing_date ) $select_fields .= ", b.showing_date";
        if ( $has_package_value ) $select_fields .= ", b.package_value";
        if ( $has_status ) $select_fields .= ", b.status";
        
        $order_by = $has_showing_date ? "ORDER BY b.showing_date DESC" : "";
        
        $agency_id = cora_db_get_agency_id();
        $query = $wpdb->prepare("SELECT {$select_fields}, l.name as client_name 
                  FROM {$bookings_table} b 
                  LEFT JOIN {$leads_table} l ON b.lead_id = l.id 
                  WHERE b.agency_id = %d 
                  {$order_by}", $agency_id);
                  
        $db_bookings = $wpdb->get_results($query, ARRAY_A);
        if ( ! empty($db_bookings) ) {
            foreach ($db_bookings as $db_b) {
                $bookings[] = array(
                    'id' => $db_b['id'],
                    'title' => ($db_b['deal_type'] ?? '') ?: ('Shoot Booking #' . $db_b['id']),
                    'client_id' => $db_b['client_id'],
                    'client_name' => $db_b['client_name'] ?: 'Client',
                    'showing_date' => $db_b['showing_date'] ?? '',
                    'package_value' => $db_b['package_value'] ?? '',
                    'status' => $db_b['status'] ?? 'confirmed'
                );
            }
        }
    }
    if ( empty($bookings) ) {
        $bookings = array(
            array('id' => 'b1', 'title' => 'Sample Shoot Booking', 'client_id' => 'c1', 'client_name' => 'Sample Client Project', 'showing_date' => date('Y-m-d'), 'package_value' => '100000', 'status' => 'confirmed')
        );
    }

    // Inject mock bookings for option store clients so they are selectable in the task dropdowns
    if ( is_array($opt_clients) && ! empty($opt_clients) ) {
        foreach ($opt_clients as $oc) {
            $client_has_booking = false;
            foreach ($bookings as $b) {
                if ((string)$b['client_id'] === (string)$oc['id']) {
                    $client_has_booking = true;
                    break;
                }
            }
            if (!$client_has_booking) {
                $bookings[] = array(
                    'id' => 'b_' . $oc['id'],
                    'title' => ($oc['scale'] ?? 'Standard Shoot') . ' - ' . ($oc['city'] ?? 'Mumbai'),
                    'client_id' => $oc['id'],
                    'client_name' => $oc['names'] ?? $oc['name'] ?? 'Client',
                    'showing_date' => '',
                    'package_value' => '',
                    'status' => 'confirmed'
                );
            }
        }
    }

    // Team Members (Dynamically query from system users)
    $team_members = array();
    $current_agency = cora_get_current_user_agency_id();
    $user_args = array( 'number' => 100, 'orderby' => 'display_name' );
    if ( $current_agency !== 'super' ) {
        $user_args['meta_query'] = array(
            array(
                'key'     => 'cora_agency_id',
                'value'   => function_exists('cora_get_agency_identifiers') ? cora_get_agency_identifiers( $current_agency ) : $current_agency,
                'compare' => 'IN'
            )
        );
    }
    $wp_users = get_users( $user_args );
    if ( ! empty( $wp_users ) ) {
        foreach ( $wp_users as $u ) {
            $display_name = trim( $u->display_name ?: $u->user_login );
            $role_name = 'Team Member';
            if ( in_array( 'administrator', $u->roles ) || in_array( 'cora_super_admin', $u->roles ) ) {
                $role_name = 'Super Admin';
            } elseif ( in_array( 'cora_manager', $u->roles ) ) {
                $role_name = 'Manager';
            }
            
            // Contextual studio role mappings
            if ( stripos( $display_name, 'Karan' ) !== false ) {
                $role_name = 'Drone Pilot';
            } elseif ( stripos( $display_name, 'Rohan' ) !== false ) {
                $role_name = 'Lead Photographer';
            } elseif ( stripos( $display_name, 'Aarav' ) !== false ) {
                $role_name = 'Senior Editor';
            } elseif ( stripos( $display_name, 'Priya' ) !== false ) {
                $role_name = 'Videographer';
            } elseif ( stripos( $display_name, 'Shruti' ) !== false ) {
                $role_name = 'Super Admin';
            }
            
            $team_members[] = array(
                'id' => (string) $u->ID,
                'name' => $display_name,
                'role' => $role_name
            );
        }
    }
    if ( empty( $team_members ) ) {
        $cur_user = wp_get_current_user();
        $cur_display_name = trim( $cur_user->display_name ?: $cur_user->user_login );
        $cur_role = 'Team Member';
        if ( in_array( 'administrator', $cur_user->roles ) || in_array( 'cora_super_admin', $cur_user->roles ) ) {
            $cur_role = 'Super Admin';
        } elseif ( in_array( 'cora_manager', $cur_user->roles ) ) {
            $cur_role = 'Manager';
        }
        $team_members = array(
            array(
                'id' => (string) $cur_user->ID,
                'name' => $cur_display_name,
                'role' => $cur_role
            )
        );
    }

    // Templates
    $templates = array(
        array('key' => 'wedding_photo', 'name' => 'Wedding Photography Workflow'),
        array('key' => 'commercial_video', 'name' => 'Commercial Video Production'),
        array('key' => 'drone_survey', 'name' => 'Drone Reel & Aerial Survey'),
        array('key' => 'client_onboarding', 'name' => 'Client Onboarding & Contract')
    );

    wp_send_json_success(array(
        'tasks' => $tasks,
        'clients' => $clients,
        'bookings' => $bookings,
        'team_members' => $team_members,
        'templates' => $templates
    ));
}
}

add_action( 'wp_ajax_cora_save_client_task', 'cora_ajax_save_client_task' );
if ( ! function_exists( 'cora_ajax_save_client_task' ) ) {
function cora_ajax_save_client_task() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );
    if ( ! current_user_can( 'read' ) ) {
        wp_send_json_error( 'Permission denied' );
    }

    $raw_task = $_POST['task'] ?? null;
    if ( $raw_task ) {
        $task = json_decode(stripslashes($raw_task), true);
    } else {
        $task_id = sanitize_text_field($_POST['id'] ?? '');
        $subtasks_json = stripslashes($_POST['subtasks'] ?? '[]');
        $subtasks = json_decode($subtasks_json, true) ?: array();

        $task = array(
            'id' => $task_id ?: uniqid(),
            'title' => sanitize_text_field($_POST['title'] ?? ''),
            'client_id' => sanitize_text_field($_POST['client_id'] ?? ''),
            'client_name' => sanitize_text_field($_POST['client_name'] ?? ''),
            'booking_id' => sanitize_text_field($_POST['booking_id'] ?? ''),
            'booking_title' => sanitize_text_field($_POST['booking_title'] ?? ''),
            'assignee_id' => sanitize_text_field($_POST['assignee_id'] ?? ''),
            'assignee_name' => sanitize_text_field($_POST['assignee_name'] ?? ''),
            'deliverable_type' => sanitize_text_field($_POST['deliverable_type'] ?? ''),
            'priority' => sanitize_text_field($_POST['priority'] ?? 'medium'),
            'due_date' => sanitize_text_field($_POST['due_date'] ?? ''),
            'status' => sanitize_text_field($_POST['status'] ?? 'todo'),
            'desc' => sanitize_textarea_field($_POST['desc'] ?? ''),
            'subtasks' => is_array($subtasks) ? $subtasks : array(),
            'comments' => array()
        );
    }

    if ( empty($task['id']) ) $task['id'] = uniqid();

    $current_agency = cora_get_current_user_agency_id() ?: 'default';
    if ( $current_agency === 'super' ) {
        if ( empty($task['agency_id']) ) {
            $task['agency_id'] = 'super';
        }
    } else {
        $task['agency_id'] = $current_agency;
    }

    $current_branch = cora_get_current_user_branch_id();
    if ( ! empty($current_branch) && empty($task['branch_id']) ) {
        $task['branch_id'] = $current_branch;
    }

    $tasks = get_option('cora_workspace_client_tasks', array());
    if ( ! is_array($tasks) ) $tasks = array();

    $updated = false;
    foreach ($tasks as &$t) {
        if ( (string) $t['id'] === (string) $task['id'] ) {
            $t = array_merge($t, $task);
            $updated = true;
            break;
        }
    }
    if ( ! $updated ) {
        $tasks[] = $task;
    }

    update_option( 'cora_workspace_client_tasks', $tasks, false );

    // Send email notification if requested
    if ( ! empty($_POST['notify_email']) && ! empty($task['assignee_name']) ) {
        $admin_email = get_option('admin_email');
        $subject = '[Cora Studio Alert] Task Assigned: ' . $task['title'];
        $body = "<h2>Task Assignment Notification</h2>" .
                "<p><strong>Task:</strong> " . esc_html($task['title']) . "</p>" .
                "<p><strong>Project / Client:</strong> " . esc_html($task['client_name'] ?: 'Studio General') . "</p>" .
                "<p><strong>Due Date:</strong> " . esc_html($task['due_date'] ?: 'No deadline') . "</p>" .
                "<p><strong>Priority:</strong> " . esc_html(strtoupper($task['priority'])) . "</p>" .
                "<p><a href='" . esc_url(site_url('/workspace/tasks')) . "'>Open Task Workspace</a></p>";
        $headers = array('Content-Type: text/html; charset=UTF-8');
        @wp_mail($admin_email, $subject, $body, $headers);
    }

    // Send WhatsApp notification if requested
    if ( ! empty($_POST['notify_wa']) && ! empty($task['whatsapp_phone']) ) {
        // Log or trigger WhatsApp API dispatch
        error_log("WhatsApp alert dispatched to " . $task['whatsapp_phone'] . " for task: " . $task['title']);
    }

    wp_send_json_success(array('message' => 'Task saved successfully', 'task' => $task, 'tasks' => $tasks));
}
}

