if ( ! function_exists( 'cora_ajax_save_media_metadata' ) ) {
function cora_ajax_save_media_metadata() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );
    if ( ! is_user_logged_in() || ( ! cora_is_super_owner() && ! current_user_can( 'upload_files' ) && ! current_user_can( 'manage_options' ) && ! current_user_can( 'edit_posts' ) ) ) {
        wp_send_json_error( array( 'message' => 'Unauthorized' ) );
    }

    $attachment_id = isset( $_POST['attachment_id'] ) ? intval( $_POST['attachment_id'] ) : 0;
    if ( ! $attachment_id ) {
        wp_send_json_error( array( 'message' => 'Invalid attachment ID.' ) );
    }

    $title       = isset( $_POST['title'] ) ? mb_substr( sanitize_text_field( $_POST['title'] ), 0, 200 ) : '';
    $alt         = isset( $_POST['alt'] ) ? sanitize_text_field( $_POST['alt'] ) : '';
    $caption     = isset( $_POST['caption'] ) ? sanitize_textarea_field( $_POST['caption'] ) : '';
    $description = isset( $_POST['description'] ) ? sanitize_textarea_field( $_POST['description'] ) : '';

    wp_update_post( array(
        'ID'           => $attachment_id,
        'post_title'   => $title,
        'post_excerpt' => $caption,
        'post_content' => $description,
    ) );

    update_post_meta( $attachment_id, '_wp_attachment_image_alt', $alt );

    wp_send_json_success( array( 'message' => 'Media metadata updated successfully.' ) );
}
}
add_action( 'wp_ajax_cora_save_media_metadata', 'cora_ajax_save_media_metadata' );

if ( ! function_exists( 'cora_ajax_save_system_settings_suite' ) ) {
function cora_ajax_save_system_settings_suite() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );
    if ( ! cora_is_super_owner() && ! current_user_can( 'manage_options' ) && ! cora_is_workspace_owner() ) {
        wp_send_json_error( array( 'message' => 'Unauthorized' ) );
    }

    $fields = array(
        'blogname',
        'blogdescription',
        'admin_email',
        'default_role',
        'users_can_register',
        'show_on_front',
        'page_on_front',
        'page_for_posts',
        'blog_public',
        'default_category',
        'default_post_format',
        'default_pingback_flag',
        'default_comment_status',
        'comment_moderation',
        'moderation_keys',
        'disallowed_keys',
        'permalink_structure',
        'wp_page_for_privacy_policy',
        'cora_brand_favicon_url',
        'cora_brand_logo_url',
        'cora_sidebar_title',
        'cora_tab_title_format',
        'cora_gbp_maps_api_key',
        'cora_whatsapp_api_token',
        'cora_whatsapp_phone_number',
        'cora_currency_format',
        'cora_workspace_name',
        'cora_workspace_address',
        'cora_workspace_tax_details',
        'cora_pwd_policy_min_len',
        'cora_activity_logs_retention',
        'cora_workspace_allow_tours',
        'cora_mcp_access_token',
        'cora_git_sync_enabled',
        'cora_git_sync_repo',
        'cora_git_sync_branch',
        'cora_git_sync_token',
        'cora_git_sync_page_id',
        'cora_git_sync_live_url',
        'cora_onboarding_enabled',
        'cora_onboarding_google_enabled',
        'cora_onboarding_email_enabled',
        'cora_onboarding_require_verification',
        'cora_onboarding_default_role',
        'cora_onboarding_account_duration',
        'cora_onboarding_welcome_message',
        'cora_google_client_id',
        'cora_google_client_secret',
        'cora_workspace_industry',
        'cora_workspace_language',
        'cora_backup_google_drive_enabled',
        'cora_backup_google_folder_id',
        'cora_backup_schedule',
        'cora_workspace_updates_server_url'
    );

    foreach ( $fields as $field ) {
        if ( $field === 'blog_public' ) {
            // Checked (Hide site) = 0; Unchecked (Show site) = 1
            $val = isset( $_POST['blog_public'] ) ? 0 : 1;
            update_option( 'blog_public', $val );
            continue;
        }
        if ( isset( $_POST[ $field ] ) ) {
            $val = $_POST[ $field ];
            if ( in_array( $field, array( 'users_can_register', 'blog_public', 'default_pingback_flag', 'comment_moderation', 'cora_pwd_policy_min_len', 'cora_activity_logs_retention', 'cora_workspace_allow_tours', 'cora_git_sync_enabled', 'cora_onboarding_enabled', 'cora_onboarding_google_enabled', 'cora_onboarding_email_enabled', 'cora_onboarding_require_verification', 'cora_backup_google_drive_enabled' ) ) ) {
                $val = intval( $val );
            } elseif ( in_array( $field, array( 'page_on_front', 'page_for_posts', 'default_category', 'wp_page_for_privacy_policy', 'cora_git_sync_page_id', 'cora_onboarding_account_duration' ) ) ) {
                $val = intval( $val );
            } elseif ( in_array( $field, array( 'moderation_keys', 'disallowed_keys', 'cora_onboarding_welcome_message' ) ) ) {
                $val = trim( $val );
            } else {
                $val = sanitize_text_field( $val );
            }
            // Skip updating secure credentials if they match the mask pattern or are empty
            $credential_fields = array(
                'cora_google_client_id',
                'cora_google_client_secret',
                'cora_gbp_maps_api_key',
                'cora_whatsapp_api_token',
                'cora_git_sync_token'
            );
            if ( in_array( $field, $credential_fields, true ) ) {
                if ( empty( $val ) || str_replace( array('•', '*'), '', $val ) === '' ) {
                    continue;
                }
            }
            update_option( $field, $val );
        } elseif ( in_array( $field, array( 'users_can_register', 'blog_public', 'default_pingback_flag', 'comment_moderation', 'cora_workspace_allow_tours', 'cora_git_sync_enabled', 'cora_onboarding_enabled', 'cora_onboarding_google_enabled', 'cora_onboarding_email_enabled', 'cora_onboarding_require_verification', 'cora_backup_google_drive_enabled' ) ) ) {
            update_option( $field, 0 );
        }
    }

    // Sync industry-specific site title and tagline
    $active_ind_save = isset( $_POST['cora_workspace_industry'] ) ? sanitize_text_field( $_POST['cora_workspace_industry'] ) : get_option( 'cora_workspace_industry', 'real_estate' );
    $is_studio_save  = ( $active_ind_save === 'photography' || $active_ind_save === 'photography_studio' || $active_ind_save === 'studio' );

    if ( isset( $_POST['blogname'] ) ) {
        $b_title = sanitize_text_field( $_POST['blogname'] );
        if ( $is_studio_save ) {
            update_option( 'cora_site_title_studio', $b_title );
        } else {
            update_option( 'cora_site_title_real_estate', $b_title );
        }
    }

    if ( isset( $_POST['blogdescription'] ) ) {
        $b_desc = sanitize_text_field( $_POST['blogdescription'] );
        if ( $is_studio_save ) {
            update_option( 'cora_tagline_studio', $b_desc );
        } else {
            update_option( 'cora_tagline_real_estate', $b_desc );
        }
    }

    $policy_checkboxes = array( 'cora_pwd_policy_numbers', 'cora_pwd_policy_uppercase', 'cora_pwd_policy_special' );
    foreach ( $policy_checkboxes as $cb ) {
        if ( ! isset( $_POST[ $cb ] ) ) {
            update_option( $cb, 0 );
        } else {
            update_option( $cb, 1 );
        }
    }

    if ( isset( $_POST['permalink_structure'] ) ) {
        global $wp_rewrite;
        $wp_rewrite->set_permalink_structure( sanitize_text_field( $_POST['permalink_structure'] ) );
        flush_rewrite_rules();
    }

    // If retention is set to a non-zero value, prune logs
    $retention = intval( $_POST['cora_activity_logs_retention'] ?? 0 );
    if ( $retention > 0 ) {
        global $wpdb;
        $wpdb->query( $wpdb->prepare(
            "DELETE FROM {$wpdb->prefix}cora_activity_logs WHERE created_at < DATE_SUB(NOW(), INTERVAL %d DAY)",
            $retention
        ) );
    }

    // Setup backup scheduling cron
    $schedule = sanitize_text_field( $_POST['cora_backup_schedule'] ?? 'manual' );
    wp_clear_scheduled_hook( 'cora_workspace_backup_cron' );
    if ( $schedule !== 'manual' ) {
        wp_schedule_event( time() + HOUR_IN_SECONDS, $schedule, 'cora_workspace_backup_cron' );
    }

    cora_log_activity( 'Permissions', 'Updated global workspace and system settings.' );

    wp_send_json_success( array( 'message' => 'Global system settings updated successfully.' ) );
}
}
add_action( 'wp_ajax_cora_save_system_settings_suite', 'cora_ajax_save_system_settings_suite' );

/**
 * AJAX Action: Clear System Cache
 */
if ( ! function_exists( 'cora_ws_ajax_clear_cache' ) ) {
function cora_ws_ajax_clear_cache() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );
    if ( ! cora_is_super_owner() && ! current_user_can( 'manage_options' ) ) {
        wp_send_json_error( array( 'message' => 'Unauthorized capability.' ) );
    }

    global $wpdb;
    delete_option( 'cora_git_sync_repo' );
    delete_option( 'cora_git_sync_branch' );
    delete_option( 'cora_git_sync_token' );
    delete_option( 'cora_git_sync_live_url' );
    wp_cache_delete( 'cora_git_sync_repo', 'options' );
    wp_cache_delete( 'cora_git_sync_branch', 'options' );
    wp_cache_delete( 'cora_git_sync_token', 'options' );
    wp_cache_delete( 'cora_git_sync_live_url', 'options' );
    wp_cache_delete( 'alloptions', 'options' );

    $table  = $wpdb->prefix . 'cora_canvas_themes';
    $themes = $wpdb->get_results( "SELECT id, settings FROM {$table}" );
    if ( $themes ) {
        foreach ( $themes as $t ) {
            $s = json_decode( $t->settings, true ) ?: array();
            unset( $s['github_repo'], $s['github_branch'], $s['lovable_pat'], $s['lovable_project_url'] );
            $wpdb->update( $table, array( 'settings' => json_encode( $s ), 'updated_at' => current_time('mysql') ), array( 'id' => $t->id ) );
        }
    }

    if ( function_exists( 'wp_cache_flush' ) ) {
        wp_cache_flush();
    }

    wp_send_json_success( array( 'message' => 'System cache and option caches cleared successfully.' ) );
}
}
add_action( 'wp_ajax_cora_clear_cache', 'cora_ws_ajax_clear_cache' );
add_action( 'wp_ajax_cora_clear_system_cache', 'cora_ws_ajax_clear_cache' );

/**
 * AJAX Action: Save Git Sync Field
 */
if ( ! function_exists( 'cora_ws_ajax_save_git_sync_field' ) ) {
function cora_ws_ajax_save_git_sync_field() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );
    if ( ! cora_is_super_owner() && ! current_user_can( 'manage_options' ) ) {
        wp_send_json_error( array( 'message' => 'Unauthorized capability.' ) );
    }

    global $wpdb;
    $field = isset( $_POST['field'] ) ? sanitize_text_field( $_POST['field'] ) : '';
    $value = isset( $_POST['value'] ) ? sanitize_text_field( $_POST['value'] ) : '';

    $allowed_fields = array( 'cora_git_sync_repo', 'cora_git_sync_branch', 'cora_git_sync_live_url' );
    if ( in_array( $field, $allowed_fields, true ) ) {
        update_option( $field, $value );
        wp_cache_delete( $field, 'options' );
        wp_cache_delete( 'alloptions', 'options' );

        $table  = $wpdb->prefix . 'cora_canvas_themes';
        $themes = $wpdb->get_results( "SELECT id, settings FROM {$table}" );
        if ( $themes ) {
            foreach ( $themes as $t ) {
                $s = json_decode( $t->settings, true ) ?: array();
                if ( $field === 'cora_git_sync_repo' ) {
                    $s['github_repo'] = $value;
                } elseif ( $field === 'cora_git_sync_branch' ) {
                    $s['github_branch'] = $value;
                } elseif ( $field === 'cora_git_sync_live_url' ) {
                    $s['lovable_project_url'] = $value;
                }
                $wpdb->update( $table, array( 'settings' => json_encode( $s ), 'updated_at' => current_time('mysql') ), array( 'id' => $t->id ) );
            }
        }

        if ( function_exists( 'wp_cache_flush' ) ) {
            wp_cache_flush();
        }

        wp_send_json_success( array( 'message' => 'Setting saved.' ) );
    } else {
        wp_send_json_error( array( 'message' => 'Invalid field.' ) );
    }
}
}
add_action( 'wp_ajax_cora_save_git_sync_field', 'cora_ws_ajax_save_git_sync_field' );

