add_action( 'wp_ajax_cora_media_library_get_activity', 'cora_ajax_media_library_get_activity' );

if ( ! function_exists( 'cora_get_workspace_storage_usage_bytes' ) ) {
function cora_get_workspace_storage_usage_bytes() {
    $upload_dir  = wp_upload_dir();
    $base        = $upload_dir['basedir'];
    $total_bytes = 0;
    if ( is_dir( $base ) ) {
        $it = new RecursiveIteratorIterator( new RecursiveDirectoryIterator( $base, FilesystemIterator::SKIP_DOTS ) );
        foreach ( $it as $f ) { if ( $f->isFile() ) $total_bytes += $f->getSize(); }
    }
    return $total_bytes;
}
}

if ( ! function_exists( 'cora_get_workspace_storage_limit_bytes' ) ) {
function cora_get_workspace_storage_limit_bytes() {
    return apply_filters( 'cora_media_storage_limit', 5 * 1024 * 1024 * 1024 ); // 5 GB default
}
}

/**
 * AJAX: Storage statistics
 */
if ( ! function_exists( 'cora_ajax_media_library_get_storage' ) ) {
function cora_ajax_media_library_get_storage() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );
    $total_bytes = cora_get_workspace_storage_usage_bytes();
    $limit_bytes = cora_get_workspace_storage_limit_bytes();
    $pct = $limit_bytes > 0 ? round( ( $total_bytes / $limit_bytes ) * 100, 1 ) : 0;
    wp_send_json_success( array(
        'total_human' => cora_media_human_size( $total_bytes ),
        'limit_human' => cora_media_human_size( $limit_bytes ),
        'percent_used'=> $pct,
        'total_bytes' => $total_bytes,
        'limit_bytes' => $limit_bytes,
    ) );
}
}
add_action( 'wp_ajax_cora_media_library_get_storage', 'cora_ajax_media_library_get_storage' );

/**
 * ═══ PROPOS: MULTI-TENANCY & USER MANAGEMENT MODULE ═════════════════════════════
 */

/**
 * Helper to resolve all possible agency identifiers (slug, DB ID, and legacy keys).
 */
if ( ! function_exists( 'cora_get_agency_identifiers' ) ) {
function cora_get_agency_identifiers( $agency_id ) {
    if ( empty( $agency_id ) || $agency_id === 'super' ) {
        return array( 'super' );
    }
    
    global $wpdb;
    $agency_ids = array( $agency_id );
    $agency_row = null;
    
    $table_exists = cora_table_exists( $wpdb->prefix . 'cora_agencies' );
    if ( $table_exists ) {
        if ( is_numeric( $agency_id ) ) {
            $agency_row = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$wpdb->prefix}cora_agencies WHERE id = %d", intval( $agency_id ) ), ARRAY_A );
        } elseif ( strpos( $agency_id, 'agency_' ) === 0 ) {
            $db_id = intval( substr( $agency_id, 7 ) );
            $agency_row = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$wpdb->prefix}cora_agencies WHERE id = %d", $db_id ), ARRAY_A );
        } else {
            $agency_row = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$wpdb->prefix}cora_agencies WHERE slug = %s", $agency_id ), ARRAY_A );
        }
    }
    
    if ( $agency_row ) {
        $agency_ids[] = (string) $agency_row['id'];
        if ( ! empty( $agency_row['slug'] ) ) {
            $agency_ids[] = $agency_row['slug'];
        }
        $agency_ids[] = 'agency_' . $agency_row['id'];
    } else {
        if ( strpos( $agency_id, 'agency_' ) === 0 ) {
            $db_id = substr( $agency_id, 7 );
            $agency_ids[] = $db_id;
        } elseif ( is_numeric( $agency_id ) ) {
            $agency_ids[] = 'agency_' . $agency_id;
        }
    }
    
    return array_unique( array_filter( $agency_ids ) );
}
}

if ( ! function_exists( 'cora_get_current_user_agency_id' ) ) {
function cora_get_current_user_agency_id() {
    $user_id = get_current_user_id();
    if ( ! $user_id && defined( 'LOGGED_IN_COOKIE' ) && ! empty( $_COOKIE[ LOGGED_IN_COOKIE ] ) ) {
        $validated_id = wp_validate_auth_cookie( $_COOKIE[ LOGGED_IN_COOKIE ], 'logged_in' );
        if ( $validated_id ) {
            $user_id = $validated_id;
            wp_set_current_user( $user_id );
        }
    }
    if ( ! $user_id ) {
        return '';
    }
    if ( cora_is_real_shruti() ) {
        $current_ws = cora_get_current_workspace_context();
        if ( ! empty( $current_ws ) && isset( $current_ws['slug'] ) ) {
            if ( $current_ws['slug'] === 'super' ) {
                return 'super';
            }
            return $current_ws['slug'];
        }
        $impersonated = get_user_meta( $user_id, 'cora_impersonate_agency_id', true );
        if ( ! empty( $impersonated ) ) {
            return $impersonated;
        }
        return 'super';
    }
    $user_agency = get_user_meta( $user_id, 'cora_agency_id', true );
    if ( empty( $user_agency ) ) {
        // Skip default setup for users who are undergoing onboarding
        $onboarding_completed = get_user_meta( $user_id, 'cora_onboarding_completed', true );
        if ( $onboarding_completed === '1' ) {
            // Fallback default setup to prevent breakages on first boot
            cora_ensure_default_agency_setup();
            $user_agency = get_user_meta( $user_id, 'cora_agency_id', true );
        } else {
            return '';
        }
    }
    if ( $user_agency === 'agency_1' ) {
        $user_agency = 'default';
    }
    return $user_agency;
}
}

if ( ! function_exists( 'cora_normalize_branch_id' ) ) {
function cora_normalize_branch_id( $branch_id ) {
    if ( empty( $branch_id ) ) {
        return '1';
    }
    if ( strpos( $branch_id, 'branch_' ) === 0 ) {
        return substr( $branch_id, 7 );
    }
    return (string) $branch_id;
}
}

if ( ! function_exists( 'cora_get_current_user_branch_id' ) ) {
function cora_get_current_user_branch_id() {
    $user_id = get_current_user_id();
    if ( ! $user_id ) {
        return '';
    }
    if ( cora_is_real_shruti() ) {
        return '';
    }
    if ( cora_is_workspace_owner() ) {
        return '';
    }
    $user = wp_get_current_user();
    $role = ! empty( $user->roles ) ? $user->roles[0] : '';
    $bypass_roles = array( 'administrator', 'cora_shruti', 'cora_super_admin', 'cora_manager', 'cora_workspace_owner', 'owner', 'cora_re_broker_owner', 'cora_studio_owner' );
    if ( in_array( $role, $bypass_roles, true ) ) {
        return '';
    }
    return get_user_meta( $user_id, 'cora_branch_id', true );
}
}

if ( ! function_exists( 'cora_create_user_workspace' ) ) {
function cora_create_user_workspace( $user_id, $business_name, $industry = 'real_estate' ) {
    global $wpdb;
    
    if ( empty( $business_name ) ) {
        $business_name = 'Custom Workspace';
    }
    if ( empty( $industry ) ) {
        $industry = get_user_meta( $user_id, 'cora_workspace_industry', true ) ?: 'real_estate';
    }
    if ( $industry === 'photography' ) {
        $industry = 'photography_studio';
    }
    update_user_meta( $user_id, 'cora_workspace_industry', $industry );
    
    // Check if the user already has an assigned agency (other than default placeholders)
    $existing_agency = get_user_meta( $user_id, 'cora_agency_id', true );
    if ( ! empty( $existing_agency ) && $existing_agency !== 'agency_1' && $existing_agency !== 'default' && $existing_agency !== 'super' ) {
        // Already has a valid workspace, just update the name and industry in case it changed
        $wpdb->update(
            $wpdb->prefix . 'cora_agencies',
            array( 'name' => $business_name, 'industry' => $industry, 'updated_at' => current_time( 'mysql' ) ),
            array( 'slug' => $existing_agency )
        );
        // Sync option
        $agencies = get_option( 'cora_agencies', array() );
        if ( is_array( $agencies ) ) {
            foreach ( $agencies as $k => $ag ) {
                if ( isset( $ag['slug'] ) && $ag['slug'] === $existing_agency ) {
                    $agencies[$k]['name'] = $business_name;
                    $agencies[$k]['industry'] = $industry;
                }
            }
            update_option( 'cora_agencies', $agencies );
        }
        return $existing_agency;
    }
    
    // Otherwise, create a new unique slug
    $slug_base = sanitize_title( $business_name );
    if ( empty( $slug_base ) ) {
        $slug_base = 'workspace';
    }
    $slug = $slug_base;
    $count = 1;
    $table_name = $wpdb->prefix . 'cora_agencies';
    $table_exists = cora_table_exists( $table_name );
    if ( $table_exists ) {
        while ( $wpdb->get_var( $wpdb->prepare( "SELECT id FROM {$table_name} WHERE slug = %s", $slug ) ) ) {
            $slug = $slug_base . '-' . $count;
            $count++;
        }
    }
    
    $now = current_time( 'mysql' );
    if ( $table_exists ) {
        $wpdb->insert(
            $table_name,
            array(
                'name'          => $business_name,
                'slug'          => $slug,
                'owner_user_id' => $user_id,
                'plan'          => 'enterprise',
                'status'        => 'active',
                'industry'      => $industry,
                'created_at'    => $now,
                'updated_at'    => $now
            ),
            array( '%s', '%s', '%d', '%s', '%s', '%s', '%s', '%s' )
        );
        $agency_db_id = $wpdb->insert_id;
    } else {
        $agency_db_id = time(); // fallback
    }
    
    // Sync to options array cora_agencies
    $agencies = get_option( 'cora_agencies', array() );
    if ( ! is_array( $agencies ) ) {
        $agencies = array();
    }
    $agencies[$agency_db_id] = array(
        'id'            => $agency_db_id,
        'name'          => $business_name,
        'slug'          => $slug,
        'plan'          => 'enterprise',
        'status'        => 'active',
        'industry'      => $industry,
        'owner_user_id' => $user_id,
        'created_at'    => $now
    );
    update_option( 'cora_agencies', $agencies );
    
    // Create default branch
    $branches_table = $wpdb->prefix . 'cora_branches';
    $branches_exists = cora_table_exists( $branches_table );
    if ( $branches_exists ) {
        $wpdb->insert(
            $branches_table,
            array(
                'agency_id'  => $agency_db_id,
                'name'       => 'Main Branch',
                'city'       => 'Default City',
                'address'    => 'Default Address',
                'manager_id' => 0,
                'status'     => 'active',
                'created_at' => $now,
                'updated_at' => $now
            ),
            array( '%d', '%s', '%s', '%s', '%d', '%s', '%s', '%s' )
        );
        $branch_db_id = $wpdb->insert_id;
    } else {
        $branch_db_id = time(); // fallback
    }
    
    // Sync branches option
    $branches = get_option( 'cora_branches', array() );
    if ( ! is_array( $branches ) ) {
        $branches = array();
    }
    $branches[$branch_db_id] = array(
        'id'         => $branch_db_id,
        'agency_id'  => $agency_db_id,
        'name'       => 'Main Branch',
        'city'       => 'Default City',
        'address'    => 'Default Address',
        'manager_id' => 0
    );
    update_option( 'cora_branches', $branches );
    
    // Assign user to the new workspace and branch
    update_user_meta( $user_id, 'cora_agency_id', $slug );
    update_user_meta( $user_id, 'cora_branch_id', $branch_db_id );
    
    return $slug;
}
}

if ( ! function_exists( 'cora_create_custom_tables' ) ) {
function cora_create_custom_tables() {
    global $wpdb;
    $theme_table = $wpdb->prefix . 'cora_canvas_themes';
    $table_exists = cora_table_exists( $theme_table );
    $forms_table = $wpdb->prefix . 'cora_forms';
    $forms_exists = cora_table_exists( $forms_table );
    $has_agency_col = false;
    $has_form_key_col = false;
    if ( $forms_exists ) {
        $has_agency_col = ! empty( $wpdb->get_results( "SHOW COLUMNS FROM {$forms_table} LIKE 'agency_id'" ) );
        $has_form_key_col = ! empty( $wpdb->get_results( "SHOW COLUMNS FROM {$forms_table} LIKE 'form_key'" ) );
    }
    $ledger_table = $wpdb->prefix . 'cora_ledger';
    $ledger_exists = cora_table_exists( $ledger_table );
    $has_category_col = false;
    if ( $ledger_exists ) {
        $has_category_col = ! empty( $wpdb->get_results( "SHOW COLUMNS FROM {$ledger_table} LIKE 'category'" ) );
    }
    if ( get_option( 'cora_db_v2_created' ) && $table_exists && $forms_exists && $has_agency_col && $has_form_key_col && $has_category_col ) {
        return;
    }
    $charset_collate = $wpdb->get_charset_collate();

    $table_queries = array();

    // 1. cora_agencies
    $table_queries[] = "CREATE TABLE {$wpdb->prefix}cora_agencies (
