if ( ! function_exists( 'cora_normalize_lead_stage' ) ) {
    function cora_normalize_lead_stage( $raw_stage ) {
        $st_lower = strtolower( trim( (string) $raw_stage ) );
        if ( empty( $st_lower ) || $st_lower === 'new' || $st_lower === 'new lead' || $st_lower === 'new inquiries' ) {
            return 'New Lead';
        }
        if ( $st_lower === 'contacted' || $st_lower === 'proposal sent' ) {
            return 'Contacted';
        }
        if ( $st_lower === 'site_visit' || $st_lower === 'site visit' || $st_lower === 'site visit / viewing' ) {
            return 'Site Visit';
        }
        if ( $st_lower === 'negotiation' || $st_lower === 'negotiat' ) {
            return 'Negotiation';
        }
        if ( $st_lower === 'converted' || $st_lower === 'closed' || $st_lower === 'won' ) {
            return 'Converted';
        }
        if ( $st_lower === 'lost' || $st_lower === 'on hold' || $st_lower === 'closed / lost' || $st_lower === 'hold' ) {
            return 'Lost';
        }
        return $raw_stage;
    }
}

if ( ! function_exists( 'cora_db_get_leads' ) ) {
function cora_db_get_leads() {
    global $wpdb;
    $agency_id = cora_db_get_agency_id();
    $branch_id = cora_db_get_branch_id();

    $user = wp_get_current_user();
    $current_role = ! empty( $user->roles ) ? $user->roles[0] : '';
    
    $query = "SELECT * FROM {$wpdb->prefix}cora_leads WHERE agency_id = %d";
    $params = array( $agency_id );

    if ( ! cora_is_workspace_owner() && ! in_array( $current_role, array( 'administrator', 'cora_shruti', 'cora_super_admin', 'cora_manager', 'cora_workspace_owner', 'owner', 'cora_re_broker_owner', 'cora_studio_owner', 'cora_studio_manager', 'cora_re_managing_agent', 'super_admin', 'agency_owner' ), true ) ) {
        $query .= " AND branch_id = %d";
        $params[] = $branch_id;
    }

    $query .= " ORDER BY created_at DESC";
    $rows = $wpdb->get_results( $wpdb->prepare( $query, $params ), ARRAY_A );

    $mapped = array();
    $seen_ids = array();

    if ( $rows ) {
        foreach ( $rows as $r ) {
            $status_text = $r['status'] ?? 'New Lead';
            switch($r['status']) {
                case 'new': $status_text = 'New Lead'; break;
                case 'contacted': $status_text = 'Contacted'; break;
                case 'site_visit': $status_text = 'Site Visit'; break;
                case 'negotiation': $status_text = 'Negotiation'; break;
                case 'closed': $status_text = 'Converted'; break;
                case 'lost': $status_text = 'Lost'; break;
            }

            $price_val = floatval($r['budget_max'] ?? 0);
            $price_text = $price_val > 0 ? '₹' . number_format($price_val) : ($r['budget_min'] ? '₹' . number_format(floatval($r['budget_min'])) : '₹0');
            $full_name = trim(($r['first_name'] ?? '') . ' ' . ($r['last_name'] ?? ''));
            if (empty($full_name)) $full_name = 'Client Inquiry';

            $entry = array(
                'id'                  => $r['id'],
                'names'               => $full_name,
                'email'               => $r['email'] ?? '',
                'phone'               => $r['phone'] ?? '',
                'assigned_to'         => isset( $r['assigned_to'] ) ? intval( $r['assigned_to'] ) : 0,
                'scale'               => !empty($r['property_type']) ? $r['property_type'] : 'Standard Shoot',
                'city'                => !empty($r['preferred_locations']) ? $r['preferred_locations'] : 'Mumbai',
                'notes'               => $r['notes'] ?? '',
                'price'               => $price_text,
                'status'              => $status_text,
                'score'               => !empty($r['priority']) ? strtolower($r['priority']) : 'warm',
                'followup_date'       => !empty($r['followup_date']) ? date('Y-m-d H:i', strtotime($r['followup_date'])) : '',
                'followup_notes'      => $r['followup_notes'] ?? '',
                'created_at'          => !empty($r['created_at']) ? strtotime($r['created_at']) : time(),
                'converted_to_client' => intval($r['converted_to_client'] ?? 0),
                'client_id'           => $r['client_id'] ?? null
            );
            $mapped[] = $entry;
            $seen_ids[(string)$r['id']] = true;
        }
    }

    // Merge option stored leads
    $option_leads = get_option( 'cora_workspace_leads', array() );

    if ( is_array( $option_leads ) && ! empty( $option_leads ) ) {
        foreach ( $option_leads as $ol ) {
            $id_key = (string)( $ol['id'] ?? '' );
            if ( empty( $id_key ) ) {
                continue;
            }

            $option_item = array(
                'id'                  => $ol['id'] ?? 'lead_' . time(),
                'names'               => $ol['names'] ?? 'Client Inquiry',
                'email'               => $ol['email'] ?? '',
                'phone'               => $ol['phone'] ?? '',
                'assigned_to'         => isset( $ol['assigned_to'] ) ? intval( $ol['assigned_to'] ) : 0,
                'scale'               => $ol['scale'] ?? 'Standard Shoot',
                'city'                => $ol['city'] ?? 'Mumbai',
                'notes'               => $ol['notes'] ?? '',
                'price'               => $ol['price'] ?? '₹0',
                'status'              => cora_normalize_lead_stage( $ol['status'] ?? 'New Lead' ),
                'score'               => $ol['score'] ?? 'warm',
                'followup_date'       => $ol['followup_date'] ?? '',
                'followup_notes'      => $ol['followup_notes'] ?? '',
                'created_at'          => $ol['created_at'] ?? time(),
                'converted_to_client' => intval( $ol['converted_to_client'] ?? 0 ),
                'client_id'           => $ol['client_id'] ?? null,
            );

            if ( isset( $seen_ids[$id_key] ) ) {
                foreach ( $mapped as $m_idx => $m_item ) {
                    if ( (string) $m_item['id'] === $id_key ) {
                        foreach ( $option_item as $k => $v ) {
                            // Never override status from option — SQL table is source of truth
                            if ( $k === 'status' ) {
                                continue;
                            }
                            if ( $v !== null && $v !== '' ) {
                                $mapped[$m_idx][$k] = $v;
                            }
                        }
                        break;
                    }
                }
            } else {
                $mapped[] = $option_item;
                $seen_ids[$id_key] = true;
            }
        }
    }

    return $mapped;
}
}

