if ( ! function_exists( 'cora_ensure_default_agency_setup' ) ) {
function cora_ensure_default_agency_setup() {
    cora_create_custom_tables();
    cora_migrate_options_to_custom_tables();
    cora_seed_3_leads_per_column();
    $agencies = get_option( 'cora_agencies', array() );
    if ( empty( $agencies ) ) {
        $agencies = array(
            'agency_1' => array(
                'id'          => 'agency_1',
                'name'        => 'Cora Default Agency',
                'subdomain'   => 'default',
                'plan'        => 'enterprise',
                'status'      => 'active',
                'created_at'  => date( 'Y-m-d H:i:s' )
            )
        );
        update_option( 'cora_agencies', $agencies );
    }

    $branches = get_option( 'cora_branches', array() );
    if ( empty( $branches ) ) {
        $branches = array(
            'branch_1' => array(
                'id'         => 'branch_1',
                'agency_id'  => 'agency_1',
                'name'       => 'Main Branch',
                'city'       => 'Default City',
                'address'    => 'Default Address',
                'manager_id' => 0
            )
        );
        update_option( 'cora_branches', $branches );
    }

    $branches = get_option( 'cora_branches', array() );
    if ( is_array( $branches ) ) {
        $seen_chennai = false;
        $modified = false;
        foreach ( $branches as $key => $b ) {
            if ( isset( $b['name'] ) && $b['name'] === 'Chennai Hub' ) {
                if ( $seen_chennai ) {
                    unset( $branches[$key] );
                    $modified = true;
                } else {
                    $seen_chennai = true;
                }
            }
        }
        if ( $modified ) {
            update_option( 'cora_branches', $branches );
        }
    }

    $user_id = get_current_user_id();
    if ( $user_id ) {
        $onboarding_completed = get_user_meta( $user_id, 'cora_onboarding_completed', true );
        if ( $onboarding_completed === '1' ) {
            $user_agency = get_user_meta( $user_id, 'cora_agency_id', true );
            if ( empty( $user_agency ) ) {
                update_user_meta( $user_id, 'cora_agency_id', 'agency_1' );
                update_user_meta( $user_id, 'cora_branch_id', 'branch_1' );
            }
        }
    }

    if ( ! get_option( 'cora_workspace_industry' ) ) {
        add_option( 'cora_workspace_industry', 'real_estate' );
    }

    cora_seed_default_canvas_data();
    cora_sync_db_tables_to_options();
}
}
add_action( 'init', 'cora_create_custom_tables', 0 );
add_action( 'init', 'cora_ensure_default_agency_setup', 5 );

// ── Tenancy Query Filtering for Options ──────────────────────────────────────

if ( ! function_exists( 'cora_filter_tenancy_data' ) ) {
function cora_filter_tenancy_data( $items, $option_name = '' ) {
    if ( ! is_array( $items ) ) {
        return $items;
    }

    // Bypass tenancy filtering for public secure share pages and public portfolio liking AJAX
    $request_uri = $_SERVER['REQUEST_URI'] ?? '';
    if ( false !== strpos( $request_uri, 'shared-doc' ) || false !== strpos( $request_uri, 'shared-portfolio' ) || ( defined( 'DOING_AJAX' ) && DOING_AJAX && isset( $_REQUEST['action'] ) && ( $_REQUEST['action'] === 'cora_toggle_portfolio_like' || $_REQUEST['action'] === 'cora_client_esign' ) ) ) {
        return $items;
    }

    $agency_id = cora_get_current_user_agency_id();
    if ( $agency_id === 'super' ) {
        return $items;
    }
    if ( empty( $agency_id ) ) {
        return array();
    }
    if ( $agency_id === 'agency_1' ) {
        $agency_id = 'default';
    }
    $branch_id = cora_get_current_user_branch_id();

    $filtered = array();
    foreach ( $items as $item ) {
        if ( ! is_array( $item ) ) {
            continue;
        }
        $item_agency = isset( $item['agency_id'] ) ? $item['agency_id'] : 'default';
        if ( $item_agency === 'agency_1' || empty( $item_agency ) ) {
            $item_agency = 'default';
        }
        if ( $item_agency !== $agency_id ) {
            continue;
        }
        if ( ! empty( $branch_id ) ) {
            $item_branch = isset( $item['branch_id'] ) ? $item['branch_id'] : 'branch_1';
            if ( $item_branch !== $branch_id ) {
                continue;
            }
        }
        $filtered[] = $item;
    }
    return $filtered;
}
}

