if ( ! function_exists( 'cora_pre_update_tenancy_data' ) ) {
function cora_pre_update_tenancy_data( $new_value, $old_value, $option_name ) {
    if ( defined( 'DOING_AJAX' ) && DOING_AJAX && isset( $_REQUEST['action'] ) && $_REQUEST['action'] === 'cora_client_esign' ) {
        return $new_value;
    }
    if ( ! is_array( $new_value ) ) {
        return $new_value;
    }
    $agency_id = cora_get_current_user_agency_id();
    if ( $agency_id === 'super' ) {
        return $new_value;
    }
    if ( empty( $agency_id ) ) {
        return $old_value;
    }
    if ( $agency_id === 'agency_1' ) {
        $agency_id = 'default';
    }
    $branch_id = cora_get_current_user_branch_id();

    global $wpdb;
    $raw_db_json = $wpdb->get_var( $wpdb->prepare( "SELECT option_value FROM {$wpdb->options} WHERE option_name = %s", $option_name ) );
    $db_items = ! empty( $raw_db_json ) ? maybe_unserialize( $raw_db_json ) : array();
    if ( ! is_array( $db_items ) ) {
        $db_items = array();
    }

    $new_ids = array();
    foreach ( $new_value as $item ) {
        if ( is_array( $item ) && isset( $item['id'] ) ) {
            $new_ids[] = (string) $item['id'];
        }
    }

    $retained_items = array();
    foreach ( $db_items as $item ) {
        if ( ! is_array( $item ) ) {
            continue;
        }
        $item_id = isset( $item['id'] ) ? (string) $item['id'] : '';
        if ( ! empty( $item_id ) && in_array( $item_id, $new_ids, true ) ) {
            continue;
        }
        $item_agency = isset( $item['agency_id'] ) ? $item['agency_id'] : 'default';
        if ( $item_agency === 'agency_1' || empty( $item_agency ) ) {
            $item_agency = 'default';
        }
        if ( $item_agency === $agency_id ) {
            if ( ! empty( $branch_id ) ) {
                $item_branch = isset( $item['branch_id'] ) ? $item['branch_id'] : 'branch_1';
                if ( $item_branch === $branch_id ) {
                    continue;
                }
            } else {
                continue;
            }
        }
        $retained_items[] = $item;
    }

    $stamped_new_items = array();
    foreach ( $new_value as $item ) {
        if ( ! is_array( $item ) ) {
            continue;
        }
        $item_agency = isset( $item['agency_id'] ) ? $item['agency_id'] : '';
        if ( $item_agency === 'agency_1' ) {
            $item['agency_id'] = 'default';
        } elseif ( empty( $item_agency ) ) {
            $item['agency_id'] = $agency_id;
        }
        if ( ! empty( $branch_id ) && empty( $item['branch_id'] ) ) {
            $item['branch_id'] = $branch_id;
        }
        $stamped_new_items[] = $item;
    }

    return array_merge( $retained_items, $stamped_new_items );
}
}

