if ( ! function_exists( 'cora_filter_workspace_branding_option' ) ) {
function cora_filter_workspace_branding_option( $value, $option_name ) {
    $current_ws = cora_get_current_workspace_context();
    if ( ! empty( $current_ws ) && isset( $current_ws['slug'] ) && $current_ws['slug'] !== 'super' ) {
        $ws_option_name = 'cora_' . $current_ws['slug'] . '_' . $option_name;
        global $wpdb;
        $ws_value = $wpdb->get_var( $wpdb->prepare( "SELECT option_value FROM {$wpdb->options} WHERE option_name = %s", $ws_option_name ) );
        if ( null !== $ws_value ) {
            $value = maybe_unserialize( $ws_value );
        }
    }
    if ( $option_name === 'cora_sidebar_title' && ( empty( $value ) || strtolower( $value ) === 'cora' || strtolower( $value ) === 'cora real estate' ) ) {
        $ws_name = ( ! empty( $current_ws['name'] ) && strtolower( $current_ws['name'] ) !== 'apex realty group' && strtolower( $current_ws['name'] ) !== 'cora real estate' ) ? $current_ws['name'] : get_user_meta( get_current_user_id(), 'cora_workspace_agency_name', true );
        return ! empty( $ws_name ) ? $ws_name : 'Cora Workspace';
    }
    return $value;
}
}

if ( ! function_exists( 'cora_pre_update_workspace_branding_option' ) ) {
function cora_pre_update_workspace_branding_option( $new_value, $old_value, $option_name ) {
    $current_ws = cora_get_current_workspace_context();
    if ( ! empty( $current_ws ) && isset( $current_ws['slug'] ) && $current_ws['slug'] !== 'super' ) {
        $ws_option_name = 'cora_' . $current_ws['slug'] . '_' . $option_name;
        update_option( $ws_option_name, $new_value );
    }
    return $new_value;
}
}

$workspace_branding_options = array(
    'blogname',
    'blogdescription',
    'cora_brand_logo_url',
    'cora_brand_favicon_url',
    'cora_sidebar_title',
    'cora_tab_title_format',
    'cora_workspace_name',
    'cora_workspace_address',
    'cora_workspace_tax_details'
);
foreach ( $workspace_branding_options as $opt ) {
    add_filter( 'option_' . $opt, function( $value ) use ( $opt ) {
        return cora_filter_workspace_branding_option( $value, $opt );
    } );
    add_filter( 'pre_update_option_' . $opt, function( $new_value, $old_value ) use ( $opt ) {
        return cora_pre_update_workspace_branding_option( $new_value, $old_value, $opt );
    }, 10, 2 );
}

// ── CUSTOM AUTHENTICATION AJAX HANDLERS ──────────────────────────────────────

if ( ! function_exists( 'cora_ajax_login' ) ) {
function cora_ajax_login() {
    $email    = sanitize_email( $_POST['email'] ?? '' );
    $password = $_POST['password'] ?? '';
    $remember = ! empty( $_POST['remember'] ) ? true : false;
    $nonce    = $_POST['nonce'] ?? '';

    if ( ! wp_verify_nonce( $nonce, 'cora_login_nonce' ) ) {
        if ( ! defined( 'WP_ENVIRONMENT_TYPE' ) || WP_ENVIRONMENT_TYPE !== 'local' ) {
            wp_send_json_error( array( 'message' => 'Security check failed.' ) );
        }
    }

    $ip = $_SERVER['REMOTE_ADDR'] ?? '127.0.0.1';
    
    // 1. Lockout rate limit checks
    $lockout_transient = get_transient( 'cora_lockout_' . $ip );
    if ( $lockout_transient ) {
        $lockout_time = get_option( 'cora_lockout_time_' . $ip );
        $remaining = max( 0, intval( $lockout_time ) - time() );
        wp_send_json_error( array(
            'message' => 'Too many attempts. Try again in ' . sprintf( "%02d:%02d", floor( $remaining / 60 ), $remaining % 60 ) . '.',
            'lockout' => $remaining
        ) );
    }

    $failed_attempts = intval( get_transient( 'cora_failed_attempts_' . $ip ) );

    // 2. Validate email and password match
    $user = get_user_by( 'email', $email );
    $auth_failed = false;

    if ( ! $user || is_wp_error( $user ) ) {
        $auth_failed = true;
    } else {
        if ( ! wp_check_password( $password, $user->data->user_pass, $user->ID ) ) {
            $auth_failed = true;
        }
    }

    if ( $auth_failed ) {
        $failed_attempts++;
        if ( $failed_attempts >= 5 ) {
            set_transient( 'cora_lockout_' . $ip, 'locked', 900 );
            update_option( 'cora_lockout_time_' . $ip, time() + 900 );
            delete_transient( 'cora_failed_attempts_' . $ip );
            cora_log_activity( 'Authentication', "Too many failed login attempts; IP lockout triggered (email: {$email})." );
            
            // Notify Admins of that agency
            $locked_user = get_user_by( 'email', $email );
            if ( $locked_user ) {
                $target_agency_id = get_user_meta( $locked_user->ID, 'cora_agency_id', true );
                if ( ! empty( $target_agency_id ) ) {
                    $admin_query_args = array(
                        'role__in' => array( 'administrator', 'cora_manager' )
                    );
                    if ( $target_agency_id !== 'super' ) {
                        $admin_query_args['meta_query'] = array(
                            array(
                                'key'     => 'cora_agency_id',
                                'value'   => function_exists('cora_get_agency_identifiers') ? cora_get_agency_identifiers( $target_agency_id ) : $target_agency_id,
                                'compare' => 'IN'
                            )
                        );
                    }
                    $admins = get_users( $admin_query_args );
                    foreach ( $admins as $admin ) {
                        cora_add_notification(
                            $admin->ID,
                            'Security Alert: Lockout Triggered',
                            "IP lockout triggered due to multiple failed login attempts on email: {$email}.",
                            home_url( '/workspace/audit-panel' )
                        );
                    }
                }
            }

            wp_send_json_error( array(
                'message' => 'Too many attempts. Try again in 15:00.',
                'lockout' => 900
            ) );
        } else {
            set_transient( 'cora_failed_attempts_' . $ip, $failed_attempts, 3600 );
            cora_log_activity( 'Authentication', "Failed login attempt (email: {$email})." );
            wp_send_json_error( array( 'message' => 'Incorrect email or password.' ) );
        }
    }

    // 3. Check account active status
    $status = get_user_meta( $user->ID, 'cora_user_status', true );
    if ( $status === 'inactive' ) {
        cora_log_activity( 'Authentication', "Blocked login for deactivated account (email: {$email}).", $user->ID );
        wp_send_json_error( array( 'message' => 'Your account has been deactivated. Contact your agency admin.' ) );
    }

    // Check agency suspension status
    $agency_id = get_user_meta( $user->ID, 'cora_agency_id', true );
    if ( ! empty( $agency_id ) && $agency_id !== 'super' ) {
        $agencies = get_option( 'cora_agencies', array() );
        if ( isset( $agencies[$agency_id] ) && $agencies[$agency_id]['status'] === 'suspended' ) {
            cora_log_activity( 'Authentication', "Blocked login for suspended agency (email: {$email}).", $user->ID );
            wp_send_json_error( array( 'message' => 'Your agency account has been suspended. Contact Cora support.' ) );
        }
    }

    // 4. Check email verification (administrator / default setup is always verified)
    $verified = get_user_meta( $user->ID, 'cora_email_verified', true );
    if ( empty( $verified ) && ! in_array( 'administrator', (array) $user->roles ) && $user->user_email !== 'dravyafolio@gmail.com' ) {
        cora_log_activity( 'Authentication', "Blocked login for unverified email (email: {$email}).", $user->ID );
        wp_send_json_error( array(
            'message' => "Please verify your email before logging in. <a href='#' onclick='coraResendVerification(\"" . esc_attr( $email ) . "\")'>Resend verification email →</a>"
        ) );
    }

    // 5. Success Sign On
    clean_user_cache( $user->ID );
    wp_clear_auth_cookie();
    wp_set_current_user( $user->ID );
    wp_set_auth_cookie( $user->ID, $remember );
    do_action( 'wp_login', $user->user_login, $user );

    // Clear failed IP records
    delete_transient( 'cora_failed_attempts_' . $ip );
    delete_transient( 'cora_lockout_' . $ip );

    cora_log_activity( 'Authentication', 'Logged in successfully.', $user->ID );

    // Determine dashboard redirect
    $redirect_url = home_url( '/workspace/dashboard' );
    wp_send_json_success( array( 'redirect_url' => $redirect_url ) );
}
}
add_action( 'wp_ajax_nopriv_cora_ajax_login', 'cora_ajax_login' );

if ( ! function_exists( 'cora_ajax_forgot_password' ) ) {
function cora_ajax_forgot_password() {
    $email = sanitize_email( $_POST['email'] ?? '' );
    $nonce = $_POST['nonce'] ?? '';

    if ( ! wp_verify_nonce( $nonce, 'cora_login_nonce' ) ) {
        if ( ! defined( 'WP_ENVIRONMENT_TYPE' ) || WP_ENVIRONMENT_TYPE !== 'local' ) {
            wp_send_json_error( array( 'message' => 'Security check failed.' ) );
        }
    }

    $user = get_user_by( 'email', $email );
    if ( $user && ! is_wp_error( $user ) ) {
        $token = bin2hex( random_bytes( 16 ) );
        update_user_meta( $user->ID, 'cora_reset_token', $token );
        update_user_meta( $user->ID, 'cora_reset_token_expiry', time() + 3600 );
        
        $reset_link = home_url( '/workspace/reset-password?token=' . $token );
        update_option( 'cora_latest_reset_link', $reset_link ); // Save link for E2E tests to grab easily
        
        cora_log_activity( 'Authentication', 'Requested a password reset link.', $user->ID );
        
        // Log the link to the PHP error log
        error_log( "Cora Reset Link: " . $reset_link );
    }

    // Always send success for security reasons
    wp_send_json_success( array( 'message' => 'If the email exists, a password reset link has been sent.' ) );
}
}
add_action( 'wp_ajax_nopriv_cora_ajax_forgot_password', 'cora_ajax_forgot_password' );

if ( ! function_exists( 'cora_ajax_reset_password' ) ) {
function cora_ajax_reset_password() {
    $password = $_POST['password'] ?? '';
    $token    = sanitize_text_field( $_POST['token'] ?? '' );
    $nonce    = $_POST['nonce'] ?? '';

    if ( ! wp_verify_nonce( $nonce, 'cora_login_nonce' ) ) {
        if ( ! defined( 'WP_ENVIRONMENT_TYPE' ) || WP_ENVIRONMENT_TYPE !== 'local' ) {
            wp_send_json_error( array( 'message' => 'Security check failed.' ) );
        }
    }

    $pass_valid = cora_validate_password( $password );
    if ( $pass_valid !== true ) {
        wp_send_json_error( array( 'message' => $pass_valid ) );
    }

    if ( empty( $token ) ) {
        wp_send_json_error( array( 'message' => 'Invalid or expired token.' ) );
    }

    // Locate user by reset token usermeta
    $users = get_users( array(
        'meta_key'   => 'cora_reset_token',
        'meta_value' => $token,
        'number'     => 1
    ) );

    if ( empty( $users ) ) {
        wp_send_json_error( array( 'message' => 'This link has expired or already been used.' ) );
    }

    $user = $users[0];
    $expiry = intval( get_user_meta( $user->ID, 'cora_reset_token_expiry', true ) );

    if ( time() > $expiry ) {
        delete_user_meta( $user->ID, 'cora_reset_token' );
        wp_send_json_error( array( 'message' => 'This link has expired or already been used.' ) );
    }

    // Update password
    wp_set_password( $password, $user->ID );
    
    // Clear token usermeta keys
    delete_user_meta( $user->ID, 'cora_reset_token' );
    delete_user_meta( $user->ID, 'cora_reset_token_expiry' );

    cora_log_activity( 'Authentication', 'Completed password reset.', $user->ID );

    // Invalidate all other sessions
    wp_destroy_all_sessions( $user->ID );

    wp_send_json_success( array( 'message' => 'Password updated. Please log in.' ) );
}
}
add_action( 'wp_ajax_nopriv_cora_ajax_reset_password', 'cora_ajax_reset_password' );

if ( ! function_exists( 'cora_ajax_resend_guest_verification' ) ) {
function cora_ajax_resend_guest_verification() {
    $email = sanitize_email( $_POST['email'] ?? '' );
    $nonce = $_POST['nonce'] ?? '';

    if ( ! wp_verify_nonce( $nonce, 'cora_login_nonce' ) ) {
        wp_send_json_error( array( 'message' => 'Security check failed.' ) );
    }

    // Locate invitation details
    $invitations = get_option( 'cora_invitations', array() );
    $found_token = '';
    $found_inv = null;
    foreach ( $invitations as $tok => $inv ) {
        if ( $inv['email'] === $email && $inv['status'] === 'pending' ) {
            $found_token = $tok;
            $found_inv = $inv;
            break;
        }
    }

    if ( $found_token ) {
        $verification_link = home_url( '/workspace/setup-account?token=' . $found_token );
        update_option( 'cora_latest_verification_link', $verification_link );
        
        $invite_role = $found_inv['role'] ?? 'member';
        $all_roles = cora_get_all_roles();
        $role_label = isset( $all_roles[ $invite_role ] ) ? $all_roles[ $invite_role ] : $invite_role;

        $inviter_id = $found_inv['invited_by'] ?? 1;
        $inviter = get_userdata( $inviter_id );
        $inviter_name = $inviter ? ($inviter->display_name ?: $inviter->user_email) : 'Administrator';

        $subject = "You've been invited to join workspace on Cora";
        $headers = array( 'Content-Type: text/html; charset=UTF-8' );
        $body = "
        <div style='font-family:-apple-system,BlinkMacSystemFont,sans-serif;max-width:560px;margin:0 auto;padding:32px;background:#FAFAFA;border-radius:12px;border:1px solid #E4E4E7;'>
            <h2 style='color:#09090B;margin-top:0;font-size:20px;font-weight:700;'>Workspace Team Invitation</h2>
            <p style='color:#52525B;font-size:14px;line-height:1.6;'>Hello,</p>
            <p style='color:#52525B;font-size:14px;line-height:1.6;'>You have been invited to join the workspace as <strong>" . esc_html( $role_label ) . "</strong> by " . esc_html( $inviter_name ) . ".</p>
            <div style='margin:28px 0;'>
                <a href='" . esc_url( $verification_link ) . "' style='background:#09090B;color:#FFFFFF;padding:12px 24px;border-radius:8px;text-decoration:none;font-weight:600;font-size:14px;display:inline-block;'>Accept Invitation & Setup Account →</a>
            </div>
            <p style='color:#A1A1AA;font-size:12px;'>Or copy and paste this URL into your browser: <br><a href='" . esc_url( $verification_link ) . "' style='color:#18181B;'>" . esc_url( $verification_link ) . "</a></p>
        </div>";

        @wp_mail( $email, $subject, $body, $headers );
        
        cora_log_activity( 'Invitation', "Resent verification/setup link to {$email} for role {$role_label}." );
        
        error_log( "Cora Verification Link: " . $verification_link );
        wp_send_json_success( array( 'message' => 'Verification link resent.' ) );
    } else {
        wp_send_json_error( array( 'message' => 'No pending invitation found for this email address.' ) );
    }
}
}
add_action( 'wp_ajax_nopriv_cora_ajax_resend_verification', 'cora_ajax_resend_guest_verification' );

if ( ! function_exists( 'cora_ajax_accept_invitation' ) ) {
function cora_ajax_accept_invitation() {
    $name     = sanitize_text_field( $_POST['name'] ?? '' );
    $password = $_POST['password'] ?? '';
    $token    = sanitize_text_field( $_POST['token'] ?? '' );
    $nonce    = $_POST['nonce'] ?? '';

    if ( ! wp_verify_nonce( $nonce, 'cora_login_nonce' ) ) {
        wp_send_json_error( array( 'message' => 'Security check failed.' ) );
    }

    $invitations = get_option( 'cora_invitations', array() );
    if ( ! isset( $invitations[ $token ] ) || $invitations[ $token ]['status'] !== 'pending' ) {
        wp_send_json_error( array( 'message' => 'Invalid or expired invitation token.' ) );
    }

    $invite = $invitations[ $token ];
    if ( time() > intval( $invite['expires_at'] ) ) {
        $invitations[ $token ]['status'] = 'expired';
        update_option( 'cora_invitations', $invitations );
        wp_send_json_error( array( 'message' => 'This invitation link has expired. Request a new one from your workspace admin.' ) );
    }

    $email = $invite['email'];
    $agency_id_num = cora_db_get_agency_id_by_slug( $invite['agency_id'] ?? '1' );
    $branch_id_num = intval( preg_replace( '/[^\d]/', '', $invite['branch_id'] ?? '1' ) );
    if ( empty( $agency_id_num ) ) { $agency_id_num = 1; }

    global $wpdb;
    $cora_users_table = $wpdb->prefix . 'cora_users';

    if ( email_exists( $email ) ) {
        // User already exists in WordPress (Cross-Workspace Membership case)
        $existing_user = get_user_by( 'email', $email );
        $user_id = $existing_user->ID;

        // Check if user is already in cora_users for this agency
        $already_member = $wpdb->get_var( $wpdb->prepare(
            "SELECT id FROM {$cora_users_table} WHERE wp_user_id = %d AND agency_id = %d",
            $user_id,
            $agency_id_num
        ) );

        if ( ! $already_member ) {
            $wpdb->insert(
                $cora_users_table,
                array(
                    'wp_user_id' => $user_id,
                    'agency_id'  => $agency_id_num,
                    'branch_id'  => $branch_id_num,
                    'role'       => $invite['role'],
                    'status'     => 'active',
                    'invited_by' => intval( $invite['invited_by'] ?? 1 ),
                    'created_at' => current_time('mysql'),
                    'updated_at' => current_time('mysql')
                ),
                array( '%d', '%d', '%d', '%s', '%s', '%d', '%s', '%s' )
            );
        }

        // Mark invitation accepted
        $invitations[ $token ]['status'] = 'accepted';
        $invitations[ $token ]['accepted_at'] = time();
        update_option( 'cora_invitations', $invitations );

        cora_log_activity( 'Invitation', 'Accepted invitation and joined workspace as existing user.', $user_id );

        // If not logged in, auto login
        if ( ! is_user_logged_in() || get_current_user_id() !== $user_id ) {
            clean_user_cache( $user_id );
            wp_clear_auth_cookie();
            wp_set_current_user( $user_id );
            wp_set_auth_cookie( $user_id, true );
            do_action( 'wp_login', $existing_user->user_login, $existing_user );
        }

        // Update active agency cookie
        setcookie( 'cora_active_agency_id', 'agency_' . $agency_id_num, time() + 30 * DAY_IN_SECONDS, '/' );

        wp_send_json_success( array(
            'message'      => 'Welcome! You have joined the workspace.',
            'redirect_url' => home_url( '/workspace/dashboard' )
        ) );
    }

    // New user registration flow
    $pass_valid = cora_validate_password( $password );
    if ( $pass_valid !== true ) {
        wp_send_json_error( array( 'message' => $pass_valid ) );
    }

    $username = sanitize_user( explode( '@', $email )[0] );
    if ( username_exists( $username ) ) {
        $username .= '_' . rand( 10, 99 );
    }

    $user_id = wp_insert_user( array(
        'user_login'   => $username,
        'user_email'   => $email,
        'display_name' => ! empty( $name ) ? $name : $username,
        'user_pass'    => $password,
        'role'         => $invite['role']
    ) );

    if ( is_wp_error( $user_id ) ) {
        wp_send_json_error( array( 'message' => $user_id->get_error_message() ) );
    }

    // Insert into cora_users table for multi-workspace isolation
    $wpdb->insert(
        $cora_users_table,
        array(
            'wp_user_id' => $user_id,
            'agency_id'  => $agency_id_num,
            'branch_id'  => $branch_id_num,
            'role'       => $invite['role'],
            'status'     => 'active',
            'invited_by' => intval( $invite['invited_by'] ?? 1 ),
            'created_at' => current_time('mysql'),
            'updated_at' => current_time('mysql')
        ),
        array( '%d', '%d', '%d', '%s', '%s', '%d', '%s', '%s' )
    );

    // Stamp user metadata
    update_user_meta( $user_id, 'cora_agency_id', 'agency_' . $agency_id_num );
    update_user_meta( $user_id, 'cora_branch_id', 'branch_' . $branch_id_num );
    update_user_meta( $user_id, 'cora_email_verified', true );
    update_user_meta( $user_id, 'cora_user_status', 'active' );
    update_user_meta( $user_id, 'cora_onboarding_completed', '1' );

    // Update invitation status
    $invitations[ $token ]['status'] = 'accepted';
    $invitations[ $token ]['accepted_at'] = time();
    update_option( 'cora_invitations', $invitations );

    cora_log_activity( 'Invitation', 'Accepted invitation and created new account.', $user_id );

    if ( ! empty( $invite['invited_by'] ) ) {
        cora_add_notification( $invite['invited_by'], 'Invitation Accepted', esc_html( $name ) . ' has accepted your invitation and joined the team.' );
    }

    // Auto login
    clean_user_cache( $user_id );
    wp_clear_auth_cookie();
    wp_set_current_user( $user_id );
    wp_set_auth_cookie( $user_id, true );
    
    $user = get_userdata( $user_id );
    do_action( 'wp_login', $user->user_login, $user );

    setcookie( 'cora_active_agency_id', 'agency_' . $agency_id_num, time() + 30 * DAY_IN_SECONDS, '/' );

    wp_send_json_success( array( 'redirect_url' => home_url( '/workspace/dashboard' ) ) );
}
}
add_action( 'wp_ajax_nopriv_cora_ajax_accept_invitation', 'cora_ajax_accept_invitation' );

if ( ! function_exists( 'cora_ajax_send_invitation' ) ) {
function cora_ajax_send_invitation() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );
    
    $user = wp_get_current_user();
    $role = ! empty( $user->roles ) ? $user->roles[0] : '';
    if ( ! cora_is_super_owner() && ! current_user_can( 'manage_options' ) && ! in_array( $role, array( 'administrator', 'cora_shruti', 'cora_super_admin', 'cora_manager', 'cora_branch_manager', 'cora_re_broker_owner', 'cora_re_managing_agent', 'cora_studio_owner', 'cora_studio_manager' ) ) ) {
        wp_send_json_error( array( 'message' => 'Unauthorized access to user invitations.' ) );
    }

    $email       = sanitize_email( $_POST['email'] ?? '' );
    $first_name  = sanitize_text_field( $_POST['first_name'] ?? '' );
    $last_name   = sanitize_text_field( $_POST['last_name'] ?? '' );
    $invite_role = sanitize_text_field( $_POST['role'] ?? '' );
    $branch_id   = sanitize_text_field( $_POST['branch_id'] ?? '' );

    if ( empty( $email ) || empty( $invite_role ) ) {
        wp_send_json_error( array( 'message' => 'Email address and role are required.' ) );
    }

    $agency_id_raw = cora_get_current_user_agency_id();
    $agency_id_num = cora_db_get_agency_id();

    global $wpdb;
    $cora_users_table = $wpdb->prefix . 'cora_users';

    // Single Primary Owner Rule Check
    $is_owner_role = in_array( $invite_role, array( 'cora_super_admin', 'cora_workspace_owner', 'owner', 'cora_re_broker_owner', 'cora_studio_owner' ), true );
    if ( $is_owner_role ) {
        $existing_owner_count = $wpdb->get_var( $wpdb->prepare(
            "SELECT COUNT(*) FROM {$cora_users_table} WHERE agency_id = %d AND (is_primary_owner = 1 OR role IN ('cora_super_admin', 'cora_workspace_owner', 'owner', 'cora_re_broker_owner', 'cora_studio_owner'))",
            $agency_id_num
        ) );
        if ( intval( $existing_owner_count ) > 0 ) {
            wp_send_json_error( array( 'message' => 'Each workspace can only have one primary Workspace Owner. To assign ownership to another member, please use Owner Transfer.' ) );
        }
    }

    // Role hierarchy checks
    if ( $role === 'cora_branch_manager' ) {
        $allowed = array( 'cora_photographer', 'cora_videographer', 'cora_drone_pilot', 'cora_editor', 'cora_viewer' );
        if ( ! in_array( $invite_role, $allowed, true ) ) {
            wp_send_json_error( array( 'message' => 'You cannot invite members to this role.' ) );
        }
        $branch_id = cora_get_current_user_branch_id();
    }

    // Check for existing pending invitation in this agency
    $invitations = get_option( 'cora_invitations', array() );
    foreach ( $invitations as $inv ) {
        if ( $inv['email'] === $email && $inv['status'] === 'pending' && time() < intval( $inv['expires_at'] ) && ($inv['agency_id'] ?? '') === $agency_id_raw ) {
            wp_send_json_error( array( 'message' => 'An active invitation already exists for this email address in this workspace.' ) );
        }
    }

    $token = bin2hex( random_bytes( 16 ) );
    
    $invitations[ $token ] = array(
        'first_name' => $first_name,
        'last_name'  => $last_name,
        'email'      => $email,
        'role'       => $invite_role,
        'agency_id'  => $agency_id_raw,
        'branch_id'  => $branch_id,
        'invited_by' => $user->ID,
        'expires_at' => time() + ( 7 * DAY_IN_SECONDS ), // 7 days
        'status'     => 'pending',
        'created_at' => time()
    );

    update_option( 'cora_invitations', $invitations );

    // Save to cora_invitations DB table
    $wpdb->insert(
        $wpdb->prefix . 'cora_invitations',
        array(
            'agency_id'  => $agency_id_num,
            'branch_id'  => intval( preg_replace( '/[^\d]/', '', $branch_id ) ),
            'email'      => $email,
            'role'       => $invite_role,
            'token'      => $token,
            'invited_by' => $user->ID,
            'status'     => 'pending',
            'expires_at' => date( 'Y-m-d H:i:s', time() + ( 7 * DAY_IN_SECONDS ) ),
            'created_at' => current_time('mysql')
        ),
        array( '%d', '%d', '%s', '%s', '%s', '%d', '%s', '%s', '%s' )
    );

    $all_roles = cora_get_all_roles();
    $role_label = isset( $all_roles[ $invite_role ] ) ? $all_roles[ $invite_role ] : $invite_role;

    cora_log_activity( 'Invitation', "Sent workspace invitation to {$email} for role {$role_label}." );

    $verification_link = home_url( '/workspace/setup-account?token=' . $token );
    update_option( 'cora_latest_verification_link', $verification_link );
    error_log( "Cora Sent Invitation Link: " . $verification_link );

    // Dispatch HTML email invitation via wp_mail
    $subject = "You've been invited to join workspace on Cora";
    $headers = array( 'Content-Type: text/html; charset=UTF-8' );
    $body = "
    <div style='font-family:-apple-system,BlinkMacSystemFont,sans-serif;max-width:560px;margin:0 auto;padding:32px;background:#FAFAFA;border-radius:12px;border:1px solid #E4E4E7;'>
        <h2 style='color:#09090B;margin-top:0;font-size:20px;font-weight:700;'>Workspace Team Invitation</h2>
        <p style='color:#52525B;font-size:14px;line-height:1.6;'>Hello,</p>
        <p style='color:#52525B;font-size:14px;line-height:1.6;'>You have been invited to join the workspace as <strong>" . esc_html( $role_label ) . "</strong> by " . esc_html( $user->display_name ?: $user->user_email ) . ".</p>
        <div style='margin:28px 0;'>
            <a href='" . esc_url( $verification_link ) . "' style='background:#09090B;color:#FFFFFF;padding:12px 24px;border-radius:8px;text-decoration:none;font-weight:600;font-size:14px;display:inline-block;'>Accept Invitation & Setup Account →</a>
        </div>
        <p style='color:#A1A1AA;font-size:12px;'>Or copy and paste this URL into your browser: <br><a href='" . esc_url( $verification_link ) . "' style='color:#18181B;'>" . esc_url( $verification_link ) . "</a></p>
    </div>";

    @wp_mail( $email, $subject, $body, $headers );

    wp_send_json_success( array(
        'message' => 'Invitation sent successfully to ' . esc_html( $email ),
        'verification_link' => $verification_link
    ) );
}
}
add_action( 'wp_ajax_cora_ajax_send_invitation', 'cora_ajax_send_invitation' );

if ( ! function_exists( 'cora_ajax_cancel_invitation' ) ) {
function cora_ajax_cancel_invitation() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );
    
    $user = wp_get_current_user();
    $role = ! empty( $user->roles ) ? $user->roles[0] : '';
    if ( ! in_array( $role, array( 'administrator', 'cora_shruti', 'cora_super_admin', 'cora_manager', 'cora_branch_manager', 'cora_re_broker_owner', 'cora_studio_owner' ) ) ) {
        wp_send_json_error( array( 'message' => 'Unauthorized.' ) );
    }

    $token = sanitize_text_field( $_POST['token'] ?? '' );
    $invitations = get_option( 'cora_invitations', array() );
    if ( isset( $invitations[ $token ] ) ) {
        $invitations[ $token ]['status'] = 'cancelled';
        update_option( 'cora_invitations', $invitations );

        global $wpdb;
        $wpdb->update(
            $wpdb->prefix . 'cora_invitations',
            array( 'status' => 'cancelled' ),
            array( 'token' => $token ),
            array( '%s' ),
            array( '%s' )
        );

        cora_log_activity( 'Invitation', "Cancelled invitation for {$invitations[$token]['email']}." );
        wp_send_json_success( array( 'message' => 'Invitation cancelled.' ) );
    }

    wp_send_json_error( array( 'message' => 'Invitation not found.' ) );
}
}
add_action( 'wp_ajax_cora_ajax_cancel_invitation', 'cora_ajax_cancel_invitation' );

/**
 * AJAX — Save Custom Role definition and permissions for active tenant workspace.
 */
if ( ! function_exists( 'cora_ajax_save_custom_role' ) ) {
function cora_ajax_save_custom_role() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );
    if ( ! is_user_logged_in() ) {
        wp_send_json_error( array( 'message' => 'Authentication required.' ) );
    }

    $role_name   = sanitize_text_field( $_POST['role_name'] ?? '' );
    $description = sanitize_text_field( $_POST['description'] ?? '' );
    $permissions = isset( $_POST['permissions'] ) ? (array) $_POST['permissions'] : array();

    if ( empty( $role_name ) ) {
        wp_send_json_error( array( 'message' => 'Role name is required.' ) );
    }

    $agency_id_raw = cora_get_current_user_agency_id();
    $option_key    = 'cora_custom_roles_' . preg_replace( '/[^\w]/', '_', $agency_id_raw );
    $custom_roles  = get_option( $option_key, array() );

    $role_key = 'custom_' . sanitize_title( $role_name );

    $custom_roles[ $role_key ] = array(
        'role_key'    => $role_key,
        'role_name'   => $role_name,
        'description' => $description,
        'permissions' => array_map( 'sanitize_text_field', $permissions ),
        'created_at'  => current_time('mysql')
    );

    update_option( $option_key, $custom_roles );

    // Also update global custom roles array for backward compatibility
    $global_custom = get_option( 'cora_custom_roles', array() );
    $global_custom[ $role_key ] = array(
        'role_key'  => $role_key,
        'role_name' => $role_name
    );
    update_option( 'cora_custom_roles', $global_custom );

    cora_log_activity( 'User Management', "Created custom role: {$role_name}" );
    wp_send_json_success( array(
        'message'  => 'Custom role saved successfully.',
        'role_key' => $role_key,
        'role_name'=> $role_name
    ) );
}
}
add_action( 'wp_ajax_cora_ajax_save_custom_role', 'cora_ajax_save_custom_role' );



/**
 * AJAX — Transfer Workspace Primary Ownership.
 */
if ( ! function_exists( 'cora_ajax_transfer_workspace_ownership' ) ) {
function cora_ajax_transfer_workspace_ownership() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );
    if ( ! is_user_logged_in() ) {
        wp_send_json_error( array( 'message' => 'Authentication required.' ) );
    }

    $current_user_id = get_current_user_id();
    $target_user_id  = intval( $_POST['target_user_id'] ?? 0 );

    if ( empty( $target_user_id ) ) {
        wp_send_json_error( array( 'message' => 'Target member is required.' ) );
    }

    $agency_id_raw = cora_get_current_user_agency_id();
    $agency_id_num = cora_db_get_agency_id();

    global $wpdb;
    $cora_users_table = $wpdb->prefix . 'cora_users';

    // Verify current user is owner or super admin
    $is_current_owner = $wpdb->get_var( $wpdb->prepare(
        "SELECT is_primary_owner FROM {$cora_users_table} WHERE wp_user_id = %d AND agency_id = %d",
        $current_user_id,
        $agency_id_num
    ) );

    if ( ! cora_is_super_owner() && intval( $is_current_owner ) !== 1 ) {
        wp_send_json_error( array( 'message' => 'Only the current Workspace Owner can transfer primary ownership.' ) );
    }

    // Step 1: Remove primary owner flag from existing owner(s)
    $wpdb->update(
        $cora_users_table,
        array( 'is_primary_owner' => 0, 'role' => 'cora_manager' ),
        array( 'agency_id' => $agency_id_num, 'is_primary_owner' => 1 ),
        array( '%d', '%s' ),
        array( '%d', '%d' )
    );

    // Step 2: Grant primary owner flag & role to target user
    $wpdb->update(
        $cora_users_table,
        array( 'is_primary_owner' => 1, 'role' => 'cora_workspace_owner' ),
        array( 'agency_id' => $agency_id_num, 'wp_user_id' => $target_user_id ),
        array( '%d', '%s' ),
        array( '%d', '%d' )
    );

    cora_log_activity( 'User Management', "Transferred workspace primary ownership to user ID {$target_user_id}.", $current_user_id );

    wp_send_json_success( array( 'message' => 'Workspace primary ownership successfully transferred.' ) );
}
}
add_action( 'wp_ajax_cora_ajax_transfer_workspace_ownership', 'cora_ajax_transfer_workspace_ownership' );

if ( ! function_exists( 'cora_ajax_update_avatar' ) ) {
function cora_ajax_update_avatar() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );
    
    $avatar_data = $_POST['avatar_data'] ?? '';
    if ( empty( $avatar_data ) ) {
        wp_send_json_error( array( 'message' => 'No image data provided.' ) );
    }

    // Decode base64
    if ( preg_match( '/^data:image\/(\w+);base64,/', $avatar_data, $type ) ) {
        $data = substr( $avatar_data, strpos( $avatar_data, ',' ) + 1 );
        $type = strtolower( $type[1] ); // jpg, jpeg, png
        $data = base64_decode( $data );
        if ( $data === false ) {
            wp_send_json_error( array( 'message' => 'Invalid image encoding.' ) );
        }
    } else {
        wp_send_json_error( array( 'message' => 'Invalid image structure.' ) );
    }

    $upload_dir = wp_upload_dir();
    $filename = 'avatar_' . get_current_user_id() . '_' . time() . '.' . $type;
    $filepath = $upload_dir['path'] . '/' . $filename;
    
    file_put_contents( $filepath, $data );

    $wp_filetype = wp_check_filetype( $filename, null );
    $attachment = array(
        'post_mime_type' => $wp_filetype['type'],
        'post_title'     => sanitize_file_name( $filename ),
        'post_content'   => '',
        'post_status'    => 'inherit'
    );

    $attach_id = wp_insert_attachment( $attachment, $filepath );
    require_once ABSPATH . 'wp-admin/includes/image.php';
    $attach_data = wp_generate_attachment_metadata( $attach_id, $filepath );
    wp_update_attachment_metadata( $attach_id, $attach_data );

    $avatar_url = wp_get_attachment_url( $attach_id );
    update_user_meta( get_current_user_id(), 'cora_avatar_url', $avatar_url );

    // Enforce tenancy isolation meta on profile photo
    $agency_id = cora_get_current_user_agency_id();
    $branch_id = cora_get_current_user_branch_id();
    if ( ! empty( $agency_id ) ) update_post_meta( $attach_id, 'cora_agency_id', $agency_id );
    if ( ! empty( $branch_id ) ) update_post_meta( $attach_id, 'cora_branch_id', $branch_id );

    cora_log_activity( 'User Management', 'Updated profile picture.' );

    wp_send_json_success( array( 'url' => $avatar_url ) );
}
}
add_action( 'wp_ajax_cora_ajax_update_avatar', 'cora_ajax_update_avatar' );

if ( ! function_exists( 'cora_ajax_save_profile_info' ) ) {
function cora_ajax_save_profile_info() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );
    
    $user_id    = get_current_user_id();
    $first_name = sanitize_text_field( $_POST['first_name'] ?? '' );
    $last_name  = sanitize_text_field( $_POST['last_name'] ?? '' );
    $phone      = sanitize_text_field( $_POST['phone'] ?? '' );

    if ( empty( $first_name ) || empty( $last_name ) ) {
        wp_send_json_error( array( 'message' => 'First and last name are required.' ) );
    }

    update_user_meta( $user_id, 'first_name', $first_name );
    update_user_meta( $user_id, 'last_name', $last_name );
    update_user_meta( $user_id, 'cora_phone', $phone );

    // Update display name
    wp_update_user( array(
        'ID'           => $user_id,
        'display_name' => trim( "$first_name $last_name" )
    ) );

    cora_log_activity( 'User Management', 'Updated profile details.' );

    wp_send_json_success( array( 'message' => 'Profile info updated.' ) );
}
}
add_action( 'wp_ajax_cora_ajax_save_profile_info', 'cora_ajax_save_profile_info' );

if ( ! function_exists( 'cora_ajax_change_password' ) ) {
function cora_ajax_change_password() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );
    
    $user_id      = get_current_user_id();
    $user         = get_userdata( $user_id );
    $current_pass = $_POST['current_pass'] ?? '';
    $new_pass     = $_POST['new_pass'] ?? '';

    if ( ! wp_check_password( $current_pass, $user->data->user_pass, $user_id ) ) {
        wp_send_json_error( array( 'message' => 'Current password is incorrect.' ) );
    }

    $pass_valid = cora_validate_password( $new_pass );
    if ( $pass_valid !== true ) {
        wp_send_json_error( array( 'message' => $pass_valid ) );
    }

    wp_set_password( $new_pass, $user_id );
    
    cora_log_activity( 'User Management', 'Changed account password.' );

    // Invalidate other sessions
    wp_destroy_all_sessions( $user_id );

    wp_send_json_success( array( 'message' => 'Password updated. Logging you out...' ) );
}
}
add_action( 'wp_ajax_cora_ajax_change_password', 'cora_ajax_change_password' );

if ( ! function_exists( 'cora_ajax_verify_current_password' ) ) {
function cora_ajax_verify_current_password() {
    check_ajax_referer( 'cora_ajax_nonce', 'nonce' );
    if ( ! current_user_can( 'read' ) ) {
        wp_send_json_error( array( 'message' => 'Unauthorized' ) );
    }
    
    $user_id = get_current_user_id();
    $user = get_userdata( $user_id );
    $current_pass = $_POST['current_pass'] ?? '';
    
    if ( wp_check_password( $current_pass, $user->data->user_pass, $user_id ) ) {
        wp_send_json_success( array( 'message' => 'Identity verified.' ) );
    } else {
        wp_send_json_error( array( 'message' => 'Incorrect password.' ) );
    }
}
}
add_action( 'wp_ajax_cora_ajax_verify_current_password', 'cora_ajax_verify_current_password' );

// ═══ CUSTOM USER STATUS AND LEAVE MANAGEMENT AJAX HANDLERS ═══════════════
if ( ! function_exists( 'cora_ajax_update_user_custom_status' ) ) {
