// ── Forms Module REST API Handlers ──────────────────────────────────────────

if ( ! function_exists( 'cora_rest_get_forms' ) ) {
function cora_rest_get_forms( $request ) {
    nocache_headers();
    if ( ! headers_sent() ) {
        header( 'X-LiteSpeed-Cache-Control: no-cache' );
    }
    global $wpdb;
    $user_agency = cora_get_current_user_agency_id();
    
    // TEMPORARY LOGGING FOR DEBUGGING
    $log_data = "--- REST REQUEST TO GET FORMS ---\n";
    $log_data .= "Time: " . date('Y-m-d H:i:s') . "\n";
    $log_data .= "User ID from get_current_user_id(): " . get_current_user_id() . "\n";
    $log_data .= "User Agency: " . $user_agency . "\n";
    $log_data .= "Agency ID resolved: " . cora_db_get_agency_id() . "\n";
    $log_data .= "Cookies: " . print_r($_COOKIE, true) . "\n";
    $log_data .= "Headers: " . print_r($request->get_headers(), true) . "\n";
    file_put_contents( '/tmp/cora_rest_log.txt', $log_data );

    if ( $user_agency === 'super' ) {
        $forms = $wpdb->get_results( "SELECT * FROM {$wpdb->prefix}cora_forms ORDER BY id DESC", ARRAY_A );
    } else {
        $agency_id = cora_db_get_agency_id();
        $forms = $wpdb->get_results( $wpdb->prepare(
            "SELECT * FROM {$wpdb->prefix}cora_forms WHERE agency_id = %d ORDER BY id DESC",
            $agency_id
        ), ARRAY_A );
    }
    if ( is_array( $forms ) ) {
        foreach ( $forms as &$form ) {
            if ( empty( $form['form_key'] ) ) {
                $form['form_key'] = 'frm_' . substr( md5( $form['id'] . $form['title'] ), 0, 8 );
                $wpdb->update( $wpdb->prefix . 'cora_forms', array( 'form_key' => $form['form_key'] ), array( 'id' => $form['id'] ) );
            }
            $form['styling'] = json_decode( $form['styling'], true ) ?: array();
            $form['settings'] = json_decode( $form['settings'], true ) ?: array();
            
            // Fetch blocks
            $blocks_row = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$wpdb->prefix}cora_form_blocks WHERE form_id = %d", $form['id'] ), ARRAY_A );
            $form['blocks'] = $blocks_row ? (json_decode( $blocks_row['blocks_json'], true ) ?: array()) : array();
            $form['logic'] = $blocks_row ? (json_decode( $blocks_row['logic_json'], true ) ?: array()) : array();

            // Fetch completed submission count
            $sub_count = $wpdb->get_var( $wpdb->prepare(
                "SELECT COUNT(*) FROM {$wpdb->prefix}cora_form_submissions WHERE form_id = %d AND is_partial = 0",
                $form['id']
            ) );
            $form['submission_count'] = intval( $sub_count );
        }
    } else {
        $forms = array();
    }
    return rest_ensure_response( $forms );
}
}

if ( ! function_exists( 'cora_rest_save_form' ) ) {
function cora_rest_save_form( $request ) {
    global $wpdb;
    $params = $request->get_json_params();
    if ( empty( $params ) ) {
        $params = $request->get_params();
    }
    if ( empty( $params ) ) {
        $body = $request->get_body();
        if ( ! empty( $body ) ) {
            $params = json_decode( $body, true );
        }
    }
    if ( empty( $params ) ) {
        return new WP_Error( 'bad_request', 'Missing form body', array( 'status' => 400 ) );
    }

    $id = isset( $params['id'] ) ? intval( $params['id'] ) : 0;
    $title = isset( $params['title'] ) ? sanitize_text_field( $params['title'] ) : 'Untitled Form';
    $status = isset( $params['status'] ) ? sanitize_text_field( $params['status'] ) : 'draft';
    $form_key = isset( $params['form_key'] ) ? sanitize_text_field( $params['form_key'] ) : '';
    if ( empty( $form_key ) ) {
        $form_key = 'frm_' . substr( md5( uniqid( $title . time(), true ) ), 0, 8 );
    }
    $styling = isset( $params['styling'] ) ? ( is_string( $params['styling'] ) ? $params['styling'] : json_encode( $params['styling'] ) ) : '{}';
    $settings = isset( $params['settings'] ) ? ( is_string( $params['settings'] ) ? $params['settings'] : json_encode( $params['settings'] ) ) : '{}';
    $blocks = isset( $params['blocks'] ) ? $params['blocks'] : array();
    $logic = isset( $params['logic'] ) ? $params['logic'] : array();

    if ( $id > 0 ) {
        // check ownership
        $user_agency = cora_get_current_user_agency_id();
        if ( $user_agency !== 'super' ) {
            $agency_db_id = cora_db_get_agency_id();
            $form_owner = $wpdb->get_var( $wpdb->prepare( "SELECT agency_id FROM {$wpdb->prefix}cora_forms WHERE id = %d", $id ) );
            if ( ! $form_owner || intval( $form_owner ) !== $agency_db_id ) {
                return new WP_Error( 'forbidden', 'You do not have permission to modify this form.', array( 'status' => 403 ) );
            }
        }
        // Update
        $wpdb->update(
            $wpdb->prefix . 'cora_forms',
            array(
                'title'      => $title,
                'form_key'   => $form_key,
                'status'     => $status,
                'styling'    => $styling,
                'settings'   => $settings,
                'updated_at' => current_time('mysql')
            ),
            array( 'id' => $id )
        );
    } else {
        // Insert
        $agency_db_id = cora_db_get_agency_id();
        $wpdb->insert(
            $wpdb->prefix . 'cora_forms',
            array(
                'agency_id'  => $agency_db_id,
                'form_key'   => $form_key,
                'title'      => $title,
                'status'     => $status,
                'styling'    => $styling,
                'settings'   => $settings,
                'created_at' => current_time('mysql'),
                'updated_at' => current_time('mysql')
            )
        );
        $id = $wpdb->insert_id;
    }

    if ( ! $id ) {
        return new WP_Error( 'db_error', 'Failed to save form to database: ' . $wpdb->last_error, array( 'status' => 500 ) );
    }

    // Update or insert blocks
    $blocks_row = $wpdb->get_row( $wpdb->prepare( "SELECT id FROM {$wpdb->prefix}cora_form_blocks WHERE form_id = %d", $id ) );
    if ( $blocks_row ) {
        $wpdb->update(
            $wpdb->prefix . 'cora_form_blocks',
            array(
                'blocks_json' => json_encode( $blocks ),
                'logic_json'  => json_encode( $logic ),
                'updated_at'  => current_time('mysql')
            ),
            array( 'form_id' => $id )
        );
    } else {
        $wpdb->insert(
            $wpdb->prefix . 'cora_form_blocks',
            array(
                'form_id'     => $id,
                'blocks_json' => json_encode( $blocks ),
                'logic_json'  => json_encode( $logic ),
                'created_at'  => current_time('mysql'),
                'updated_at'  => current_time('mysql')
            )
        );
    }

    // Add audit log entry
    $wpdb->insert(
        $wpdb->prefix . 'cora_form_audit_log',
        array(
            'form_id'      => $id,
            'action_type'  => 'form_saved',
            'details'      => 'Form saved: ' . $title,
            'performed_by' => get_current_user_id(),
            'ip_address'   => $_SERVER['REMOTE_ADDR'] ?? '',
            'created_at'   => current_time('mysql')
        )
    );

    $form = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$wpdb->prefix}cora_forms WHERE id = %d", $id ), ARRAY_A );
    if ( ! $form ) {
        return new WP_Error( 'not_found', 'Saved form record not found', array( 'status' => 404 ) );
    }
    $form['styling'] = json_decode( $form['styling'], true ) ?: array();
    $form['settings'] = json_decode( $form['settings'], true ) ?: array();
    $form['blocks'] = $blocks;
    $form['logic'] = $logic;

    return rest_ensure_response( $form );
}
}

if ( ! function_exists( 'cora_rest_get_form' ) ) {
function cora_rest_get_form( $request ) {
    nocache_headers();
    if ( ! headers_sent() ) {
        header( 'X-LiteSpeed-Cache-Control: no-cache' );
    }
    global $wpdb;
    $id = intval( $request->get_param('id') );
    $form = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$wpdb->prefix}cora_forms WHERE id = %d", $id ), ARRAY_A );
    if ( ! $form ) {
        return new WP_Error( 'not_found', 'Form not found', array( 'status' => 404 ) );
    }
    
    // Tenancy Check
    $user_agency = cora_get_current_user_agency_id();
    if ( $user_agency !== 'super' ) {
        $agency_id = cora_db_get_agency_id();
        if ( intval( $form['agency_id'] ) !== $agency_id ) {
            return new WP_Error( 'forbidden', 'You do not have permission to access this form.', array( 'status' => 403 ) );
        }
    }

    $form['styling'] = json_decode( $form['styling'], true ) ?: array();
    $form['settings'] = json_decode( $form['settings'], true ) ?: array();

    $blocks_row = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$wpdb->prefix}cora_form_blocks WHERE form_id = %d", $id ), ARRAY_A );
    $form['blocks'] = $blocks_row ? (json_decode( $blocks_row['blocks_json'], true ) ?: array()) : array();
    $form['logic'] = $blocks_row ? (json_decode( $blocks_row['logic_json'], true ) ?: array()) : array();

    return rest_ensure_response( $form );
}
}

if ( ! function_exists( 'cora_rest_delete_form' ) ) {
function cora_rest_delete_form( $request ) {
    global $wpdb;
    $id = intval( $request->get_param('id') );

    // Tenancy Check
    $user_agency = cora_get_current_user_agency_id();
    if ( $user_agency !== 'super' ) {
