/**
 * Check if the logged-in user is a workspace owner or administrator.
 */
if ( ! function_exists( 'cora_is_workspace_owner' ) ) {
function cora_is_workspace_owner( $user = null ) {
    if ( ! $user ) {
        $user = wp_get_current_user();
    }
    if ( ! $user || ! $user->ID ) {
        return false;
    }

    // Check if user is the owner of their agency
    $user_agency = get_user_meta( $user->ID, 'cora_agency_id', true );
    if ( ! empty( $user_agency ) ) {
        global $wpdb;
        $owner_id = null;
        $table_exists = cora_table_exists( $wpdb->prefix . 'cora_agencies' );
        if ( $table_exists ) {
            if ( is_numeric( $user_agency ) ) {
                $owner_id = $wpdb->get_var( $wpdb->prepare( "SELECT owner_user_id FROM {$wpdb->prefix}cora_agencies WHERE id = %d", intval( $user_agency ) ) );
            } elseif ( strpos( $user_agency, 'agency_' ) === 0 ) {
                $db_id = intval( substr( $user_agency, 7 ) );
                $owner_id = $wpdb->get_var( $wpdb->prepare( "SELECT owner_user_id FROM {$wpdb->prefix}cora_agencies WHERE id = %d", $db_id ) );
            } else {
                $owner_id = $wpdb->get_var( $wpdb->prepare( "SELECT owner_user_id FROM {$wpdb->prefix}cora_agencies WHERE slug = %s", $user_agency ) );
            }
            if ( $owner_id && intval( $owner_id ) === intval( $user->ID ) ) {
                return true;
            }
        }
    }

    $roles = (array) $user->roles;
    $main_role = ! empty( $roles[0] ) ? $roles[0] : '';
    $owner_roles = array( 'administrator', 'cora_shruti', 'cora_super_admin', 'cora_manager', 'cora_re_broker_owner', 'cora_studio_owner', 'owner', 'cora_workspace_owner' );
    if ( in_array( $main_role, $owner_roles, true ) ) {
        return true;
    }
    return false;
}
}

/**
 * Ensure industry column exists in cora_agencies table.
 */
if ( ! function_exists( 'cora_ensure_agencies_industry_column' ) ) {
function cora_ensure_agencies_industry_column() {
    global $wpdb;
    $agencies_table = $wpdb->prefix . 'cora_agencies';
    $table_exists = $wpdb->get_var( $wpdb->prepare( "SHOW TABLES LIKE %s", $agencies_table ) );
    if ( $table_exists ) {
        $column_exists = $wpdb->get_results( "SHOW COLUMNS FROM {$agencies_table} LIKE 'industry'" );
        if ( empty( $column_exists ) ) {
            $wpdb->query( "ALTER TABLE {$agencies_table} ADD COLUMN industry varchar(50) NOT NULL DEFAULT 'real_estate'" );
        }
    }
}
}

/**
 * AJAX Callback: Get all workspaces.
 */
if ( ! function_exists( 'cora_ajax_super_get_workspaces' ) ) {
function cora_ajax_super_get_workspaces() {
    if ( isset( $_POST['security'] ) ) {
        check_ajax_referer( 'cora_ajax_nonce', 'security', false );
    }
    if ( ! cora_is_super_owner() ) {
        wp_send_json_error( 'Unauthorized access.' );
    }

    cora_ensure_agencies_industry_column();

    global $wpdb;
    $agencies_table = $wpdb->prefix . 'cora_agencies';
    $users_table = $wpdb->users;

    $table_exists = $wpdb->get_var( $wpdb->prepare( "SHOW TABLES LIKE %s", $agencies_table ) );
    $results = array();

    if ( $table_exists ) {
        $query = "SELECT a.*, u.user_email as owner_email, u.display_name as owner_name 
                  FROM {$agencies_table} a 
                  LEFT JOIN {$users_table} u ON a.owner_user_id = u.ID 
                  ORDER BY a.id DESC";
        $raw_results = $wpdb->get_results( $query, ARRAY_A );
        if ( is_array( $raw_results ) ) {
            foreach ( $raw_results as $row ) {
                $ind = ! empty( $row['industry'] ) ? $row['industry'] : '';
                if ( ! $ind && ! empty( $row['owner_user_id'] ) ) {
                    $ind = get_user_meta( $row['owner_user_id'], 'cora_workspace_industry', true );
                }
                if ( ! $ind ) {
                    $ind = 'real_estate';
                }
                $row['industry'] = $ind;
                $results[] = $row;
            }
        }
    }

    if ( empty( $results ) ) {
        $agencies = get_option( 'cora_agencies', array() );
        if ( is_array( $agencies ) && ! empty( $agencies ) ) {
            foreach ( $agencies as $k => $ag ) {
                if ( empty( $ag['industry'] ) ) {
                    $ag['industry'] = 'real_estate';
                }
                $results[] = $ag;
            }
        } else {
            $results = array(
                array(
                    'id' => 1,
                    'name' => 'Apex Realty Group',
                    'slug' => 'apex-realty',
                    'plan' => 'enterprise',
                    'status' => 'active',
                    'industry' => 'real_estate',
                    'owner_email' => 'shruti@heycora.in',
                    'created_at' => current_time( 'mysql' )
                )
            );
        }
    }

    wp_send_json_success( array( 'workspaces' => $results ) );
}
}
add_action( 'wp_ajax_cora_super_get_workspaces', 'cora_ajax_super_get_workspaces' );

/**
 * AJAX Callback: Get all users.
 */
if ( ! function_exists( 'cora_ajax_super_get_users' ) ) {
function cora_ajax_super_get_users() {
    if ( isset( $_POST['security'] ) ) {
        check_ajax_referer( 'cora_ajax_nonce', 'security', false );
    }
    if ( ! cora_is_super_owner() ) {
        wp_send_json_error( 'Unauthorized access.' );
    }

    global $wpdb;
    $cora_users_table = $wpdb->prefix . 'cora_users';
    $wp_users_table = $wpdb->users;
    $agencies_table = $wpdb->prefix . 'cora_agencies';

    $table_exists = $wpdb->get_var( $wpdb->prepare( "SHOW TABLES LIKE %s", $cora_users_table ) );
    $results = array();

    if ( $table_exists ) {
        $query = "SELECT cu.*, u.user_login, u.user_email, u.display_name, a.name as agency_name, a.plan as agency_plan 
                  FROM {$cora_users_table} cu 
                  INNER JOIN {$wp_users_table} u ON cu.wp_user_id = u.ID 
                  LEFT JOIN {$agencies_table} a ON cu.agency_id = a.id 
                  ORDER BY cu.id DESC";
        $results = $wpdb->get_results( $query, ARRAY_A );
    }

    if ( empty( $results ) ) {
        $wp_users = get_users( array( 'number' => 50 ) );
        foreach ( $wp_users as $u ) {
            $user_roles = (array) $u->roles;
            $results[] = array(
                'id' => $u->ID,
                'wp_user_id' => $u->ID,
                'user_login' => $u->user_login,
                'user_email' => $u->user_email,
                'display_name' => $u->display_name ?: $u->user_login,
                'agency_name' => 'Apex Realty Group',
                'agency_plan' => 'enterprise',
                'role' => ! empty( $user_roles[0] ) ? $user_roles[0] : 'administrator',
                'status' => 'active'
            );
        }
    }

    wp_send_json_success( array( 'users' => $results ) );
}
}
add_action( 'wp_ajax_cora_super_get_users', 'cora_ajax_super_get_users' );

/**
 * AJAX — Switch Active Industry Mode (Shruti & Super Admin only).
 */
if ( ! function_exists( 'cora_ajax_switch_industry_mode' ) ) {
function cora_ajax_switch_industry_mode() {
    $industry = isset( $_POST['industry'] ) ? sanitize_text_field( $_POST['industry'] ) : 'photography_studio';
    if ( in_array( $industry, array( 'real_estate', 'photography', 'photography_studio' ), true ) ) {
        if ( $industry === 'photography' ) {
            $industry = 'photography_studio';
        }
        update_option( 'cora_workspace_industry', $industry );
        setcookie( 'cora_workspace_industry', $industry, time() + 86400 * 365, '/' );
        if ( isset( $_COOKIE['cora_workspace_industry'] ) ) {
            $_COOKIE['cora_workspace_industry'] = $industry;
        }
        cora_log_activity( 'Platform Management', "Industry mode switched to: {$industry}" );
        wp_send_json_success( array(
            'message' => 'Industry mode updated successfully!',
            'industry' => $industry
        ) );
    }

    wp_send_json_error( array( 'message' => 'Invalid industry mode.' ) );
}
}
add_action( 'wp_ajax_cora_switch_industry_mode', 'cora_ajax_switch_industry_mode' );
add_action( 'wp_ajax_nopriv_cora_switch_industry_mode', 'cora_ajax_switch_industry_mode' );

/**
 * AJAX Callback: Update workspace status, plan, or industry.
 */
if ( ! function_exists( 'cora_ajax_super_update_workspace' ) ) {
function cora_ajax_super_update_workspace() {
    check_ajax_referer( 'cora_ajax_nonce', 'security' );
    if ( ! cora_is_super_owner() ) {
        wp_send_json_error( 'Unauthorized access.' );
    }

    cora_ensure_agencies_industry_column();

    global $wpdb;
    $workspace_id = isset( $_POST['workspace_id'] ) ? intval( $_POST['workspace_id'] ) : 0;
    if ( $workspace_id <= 0 ) {
        wp_send_json_error( 'Invalid workspace ID.' );
    }

    $table_name = $wpdb->prefix . 'cora_agencies';

    // Verify workspace exists
    $workspace = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$table_name} WHERE id = %d", $workspace_id ), ARRAY_A );
    if ( ! $workspace ) {
        wp_send_json_error( 'Workspace not found.' );
    }

    $name = isset( $_POST['name'] ) ? sanitize_text_field( $_POST['name'] ) : $workspace['name'];
    $slug = isset( $_POST['slug'] ) ? sanitize_title( $_POST['slug'] ) : $workspace['slug'];
    $status = isset( $_POST['status'] ) ? sanitize_text_field( $_POST['status'] ) : $workspace['status'];
    $plan = isset( $_POST['plan'] ) ? sanitize_text_field( $_POST['plan'] ) : $workspace['plan'];

    $raw_ind = isset( $_POST['industry'] ) ? sanitize_text_field( $_POST['industry'] ) : ( ! empty( $workspace['industry'] ) ? $workspace['industry'] : 'real_estate' );
    if ( $raw_ind === 'photography' ) {
        $raw_ind = 'photography_studio';
    }
    $industry = in_array( $raw_ind, array( 'real_estate', 'photography_studio' ), true ) ? $raw_ind : 'real_estate';

    $owner_email = isset( $_POST['owner_email'] ) ? sanitize_email( $_POST['owner_email'] ) : '';

    $owner_id = $workspace['owner_user_id'];
    if ( ! empty( $owner_email ) ) {
        $owner_user = get_user_by( 'email', $owner_email );
        if ( $owner_user ) {
            $owner_id = $owner_user->ID;
        }
    }

    if ( empty( $name ) || empty( $slug ) ) {
        wp_send_json_error( 'Workspace name and slug are required.' );
    }

    // Verify slug uniqueness if slug changed
    if ( $slug !== $workspace['slug'] ) {
        $existing = $wpdb->get_var( $wpdb->prepare( "SELECT id FROM {$table_name} WHERE slug = %s AND id != %d", $slug, $workspace_id ) );
        if ( $existing ) {
            wp_send_json_error( 'Workspace slug already exists. Please choose a unique slug.' );
        }
    }

    // Update table
    $updated = $wpdb->update(
        $table_name,
        array(
            'name' => $name,
            'slug' => $slug,
            'status' => $status,
            'plan' => $plan,
            'industry' => $industry,
            'owner_user_id' => $owner_id,
            'updated_at' => current_time( 'mysql' )
        ),
        array( 'id' => $workspace_id ),
        array( '%s', '%s', '%s', '%s', '%s', '%d', '%s' ),
        array( '%d' )
    );

    if ( $updated === false ) {
        wp_send_json_error( 'Failed to update workspace in database.' );
    }

    if ( $owner_id ) {
        update_user_meta( $owner_id, 'cora_workspace_industry', $industry );
        update_user_meta( $owner_id, 'cora_workspace_status', $status );
        update_user_meta( $owner_id, 'cora_agency_status', $status );
        update_user_meta( $owner_id, 'cora_workspace_plan', $plan );
        update_user_meta( $owner_id, 'cora_agency_plan', $plan );
        update_user_meta( $owner_id, 'cora_agency_id', $slug );
    }

    // Update cora_users table status if exists
    $cora_users_table = $wpdb->prefix . 'cora_users';
    if ( cora_table_exists( $cora_users_table ) ) {
        $wpdb->update(
            $cora_users_table,
            array( 'status' => $status ),
            array( 'agency_id' => $workspace_id ),
            array( '%s' ),
            array( '%d' )
        );
    }

    // Sync to options array cora_agencies under all lookup keys
    $agencies = get_option( 'cora_agencies', array() );
    if ( ! is_array( $agencies ) ) {
        $agencies = array();
    }

    $agency_entry = array(
        'id'            => $workspace_id,
        'name'          => $name,
        'slug'          => $slug,
        'subdomain'     => $slug,
        'status'        => $status,
        'plan'          => $plan,
        'industry'      => $industry,
        'owner_user_id' => $owner_id,
        'updated_at'    => current_time( 'mysql' )
    );

    $agencies[$workspace_id]             = $agency_entry;
    $agencies['agency_' . $workspace_id] = $agency_entry;
    $agencies[$slug]                     = $agency_entry;

    update_option( 'cora_agencies', $agencies );

    cora_log_activity( 'Platform Management', "Workspace ID {$workspace_id} ({$name}) updated: status={$status}, plan={$plan}, industry={$industry}" );

    wp_send_json_success( array(
        'message'  => "Workspace '{$name}' updated successfully: Status: " . ucfirst( $status ) . ", Plan: " . ucfirst( $plan ) . ".",
        'status'   => $status,
        'plan'     => $plan,
        'industry' => $industry
    ) );
}
}
add_action( 'wp_ajax_cora_super_update_workspace', 'cora_ajax_super_update_workspace' );

/**
 * AJAX Callback: Submit suspension reactivation appeal (Public & Logged In).
 */
if ( ! function_exists( 'cora_ajax_submit_suspension_appeal' ) ) {
function cora_ajax_submit_suspension_appeal() {
    $email          = isset( $_POST['email'] ) ? sanitize_email( $_POST['email'] ) : '';
    $workspace_name = isset( $_POST['workspace_name'] ) ? sanitize_text_field( $_POST['workspace_name'] ) : '';
    $reason         = isset( $_POST['reason'] ) ? sanitize_textarea_field( $_POST['reason'] ) : '';
    $phone          = isset( $_POST['phone'] ) ? sanitize_text_field( $_POST['phone'] ) : '';

    if ( empty( $email ) || ! is_email( $email ) ) {
        wp_send_json_error( array( 'message' => 'Please provide a valid account email address.' ) );
    }

    if ( empty( $reason ) ) {
        wp_send_json_error( array( 'message' => 'Please provide a reason for your reactivation appeal.' ) );
    }

    $appeals = get_option( 'cora_suspension_appeals', array() );
    if ( ! is_array( $appeals ) ) {
        $appeals = array();
    }

    $appeal_id = 'appeal_' . uniqid() . '_' . time();
    $new_appeal = array(
        'id'             => $appeal_id,
        'email'          => $email,
        'workspace_name' => $workspace_name,
        'reason'         => $reason,
        'phone'          => $phone,
        'status'         => 'pending',
        'created_at'     => current_time( 'mysql' ),
        'user_ip'        => isset($_SERVER['REMOTE_ADDR']) ? sanitize_text_field($_SERVER['REMOTE_ADDR']) : ''
    );

    $appeals[$appeal_id] = $new_appeal;
    update_option( 'cora_suspension_appeals', $appeals );

    if ( function_exists( 'cora_log_activity' ) ) {
        cora_log_activity( 'Governance', "Suspension reactivation appeal submitted by {$email} for workspace '{$workspace_name}'." );
    }

    $admin_email = get_option( 'admin_email' );
    $subject     = "[Cora Platform] Workspace Reactivation Appeal: {$workspace_name}";
    $body        = "A workspace reactivation appeal has been submitted.\n\n"
                 . "Account Email: {$email}\n"
                 . "Workspace Name: {$workspace_name}\n"
                 . "Phone/Contact: {$phone}\n"
                 . "Submitted At: " . current_time( 'mysql' ) . "\n\n"
                 . "Reason:\n{$reason}\n\n"
                 . "Log into the Cora Super Admin Control Centre to review and process this appeal.";

    @wp_mail( $admin_email, $subject, $body );

    wp_send_json_success( array(
        'message' => 'Your reactivation appeal has been submitted successfully. The platform administrator will review your request shortly.',
        'appeal_id' => $appeal_id
    ) );
}
}
add_action( 'wp_ajax_cora_submit_suspension_appeal', 'cora_ajax_submit_suspension_appeal' );
add_action( 'wp_ajax_nopriv_cora_submit_suspension_appeal', 'cora_ajax_submit_suspension_appeal' );

/**
 * AJAX Callback: Fetch suspension reactivation appeals (Super Admin only).
 */
if ( ! function_exists( 'cora_ajax_super_get_appeals' ) ) {
function cora_ajax_super_get_appeals() {
    check_ajax_referer( 'cora_ajax_nonce', 'security' );
    if ( ! cora_is_super_owner() ) {
        wp_send_json_error( 'Unauthorized access.' );
    }

    $appeals = get_option( 'cora_suspension_appeals', array() );
    if ( ! is_array( $appeals ) ) {
        $appeals = array();
    }

    $appeal_list = array_values( $appeals );
    usort( $appeal_list, function( $a, $b ) {
        return strtotime( $b['created_at'] ?? 0 ) - strtotime( $a['created_at'] ?? 0 );
    });

    wp_send_json_success( array(
        'appeals' => $appeal_list
    ) );
}
}
add_action( 'wp_ajax_cora_super_get_appeals', 'cora_ajax_super_get_appeals' );

/**
 * AJAX Callback: Handle reactivation appeal approval or decline (Super Admin only).
 */
if ( ! function_exists( 'cora_ajax_super_handle_appeal' ) ) {
function cora_ajax_super_handle_appeal() {
    check_ajax_referer( 'cora_ajax_nonce', 'security' );
    if ( ! cora_is_super_owner() ) {
        wp_send_json_error( 'Unauthorized access.' );
    }

    $appeal_id     = isset( $_POST['appeal_id'] ) ? sanitize_text_field( $_POST['appeal_id'] ) : '';
    $appeal_action = isset( $_POST['appeal_action'] ) ? sanitize_text_field( $_POST['appeal_action'] ) : '';
    $notes         = isset( $_POST['notes'] ) ? sanitize_textarea_field( $_POST['notes'] ) : '';

    if ( empty( $appeal_id ) || ! in_array( $appeal_action, array( 'approve', 'decline' ), true ) ) {
        wp_send_json_error( 'Invalid appeal request or action.' );
    }

    $appeals = get_option( 'cora_suspension_appeals', array() );
    if ( ! is_array( $appeals ) || ! isset( $appeals[$appeal_id] ) ) {
        wp_send_json_error( 'Appeal record not found.' );
    }

    $appeal = $appeals[$appeal_id];
    $email  = $appeal['email'];

    if ( $appeal_action === 'approve' ) {
        $appeals[$appeal_id]['status']       = 'approved';
        $appeals[$appeal_id]['processed_at'] = current_time( 'mysql' );
        $appeals[$appeal_id]['notes']        = $notes;
        update_option( 'cora_suspension_appeals', $appeals );

        global $wpdb;
        $user = get_user_by( 'email', $email );
        if ( $user ) {
            $user_id = $user->ID;
            update_user_meta( $user_id, 'cora_workspace_status', 'active' );
            update_user_meta( $user_id, 'cora_agency_status', 'active' );

            $agencies_table = $wpdb->prefix . 'cora_agencies';
            if ( cora_table_exists( $agencies_table ) ) {
                $wpdb->update(
                    $agencies_table,
                    array( 'status' => 'active', 'updated_at' => current_time( 'mysql' ) ),
                    array( 'owner_user_id' => $user_id ),
                    array( '%s', '%s' ),
                    array( '%d' )
                );
            }

            $agencies = get_option( 'cora_agencies', array() );
            if ( is_array( $agencies ) ) {
                foreach ( $agencies as $k => $ag ) {
                    if ( isset( $ag['owner_user_id'] ) && intval( $ag['owner_user_id'] ) === $user_id ) {
                        $agencies[$k]['status'] = 'active';
                    }
                }
                update_option( 'cora_agencies', $agencies );
            }
        }

        $subject = "[Cora Platform] Workspace Reactivated Successfully";
        $body    = "Hello,\n\n"
                 . "Good news! Your workspace reactivation appeal has been approved by the platform administrator.\n\n"
                 . "Your account and workspace access have been restored. You can now log back in at:\n"
                 . home_url( '/workspace/login' ) . "\n\n"
                 . "Administrator Notes:\n" . ( $notes ?: "None" ) . "\n\n"
                 . "Best regards,\nCora Platform Support";
        @wp_mail( $email, $subject, $body );

        if ( function_exists( 'cora_log_activity' ) ) {
            cora_log_activity( 'Governance', "Reactivation appeal {$appeal_id} approved for {$email}." );
        }

        wp_send_json_success( array(
            'message' => "Reactivation appeal approved! Workspace for {$email} is now ACTIVE."
        ) );
    } else {
        $appeals[$appeal_id]['status']       = 'declined';
        $appeals[$appeal_id]['processed_at'] = current_time( 'mysql' );
        $appeals[$appeal_id]['notes']        = $notes;
        update_option( 'cora_suspension_appeals', $appeals );

        $subject = "[Cora Platform] Update regarding your workspace reactivation appeal";
        $body    = "Hello,\n\n"
                 . "Your workspace reactivation appeal has been reviewed by the platform administrator.\n\n"
                 . "Status: Declined\n"
                 . "Administrator Notes:\n" . ( $notes ?: "Please contact support for further details." ) . "\n\n"
                 . "Best regards,\nCora Platform Support";
        @wp_mail( $email, $subject, $body );

        if ( function_exists( 'cora_log_activity' ) ) {
            cora_log_activity( 'Governance', "Reactivation appeal {$appeal_id} declined for {$email}." );
        }

        wp_send_json_success( array(
            'message' => "Reactivation appeal declined for {$email}."
        ) );
    }
}
}
add_action( 'wp_ajax_cora_super_handle_appeal', 'cora_ajax_super_handle_appeal' );

/**
 * AJAX Callback: Delete workspace.
 */
if ( ! function_exists( 'cora_ajax_super_delete_workspace' ) ) {
function cora_ajax_super_delete_workspace() {
    check_ajax_referer( 'cora_ajax_nonce', 'security' );
    if ( ! cora_is_super_owner() ) {
        wp_send_json_error( 'Unauthorized access.' );
    }

    global $wpdb;
    $workspace_id = isset( $_POST['workspace_id'] ) ? intval( $_POST['workspace_id'] ) : 0;
    if ( $workspace_id <= 0 ) {
        wp_send_json_error( 'Invalid workspace ID.' );
    }

    $table_name = $wpdb->prefix . 'cora_agencies';

    // Verify workspace exists
    $workspace = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$table_name} WHERE id = %d", $workspace_id ), ARRAY_A );
    if ( ! $workspace ) {
        wp_send_json_error( 'Workspace not found.' );
    }

    // Do not delete protected/super admin view
    if ( $workspace['slug'] === 'super' || $workspace['slug'] === 'default' ) {
        wp_send_json_error( 'Protected workspace cannot be deleted.' );
    }

    $deleted = $wpdb->delete( $table_name, array( 'id' => $workspace_id ), array( '%d' ) );
    if ( $deleted ) {
        $agencies = get_option( 'cora_agencies', array() );
        $key = 'agency_' . $workspace_id;
        if ( ! isset( $agencies[$key] ) ) {
            foreach ( $agencies as $k => $agency_data ) {
                if ( isset( $agency_data['id'] ) && ( intval( $agency_data['id'] ) === $workspace_id || $agency_data['id'] === $key ) ) {
                    $key = $k;
                    break;
                }
            }
        }
        if ( isset( $agencies[$key] ) ) {
            unset( $agencies[$key] );
            update_option( 'cora_agencies', $agencies );
        }
        wp_send_json_success( array( 'message' => 'Workspace deleted successfully!' ) );
    }

    wp_send_json_error( 'Failed to delete workspace from database.' );
}
}
add_action( 'wp_ajax_cora_super_delete_workspace', 'cora_ajax_super_delete_workspace' );

/**
 * AJAX Callback: Create new workspace.
 */
if ( ! function_exists( 'cora_ajax_super_create_workspace' ) ) {
function cora_ajax_super_create_workspace() {
    check_ajax_referer( 'cora_ajax_nonce', 'security' );
    if ( ! cora_is_super_owner() ) {
        wp_send_json_error( array( 'message' => 'Unauthorized access.' ) );
    }

    cora_ensure_agencies_industry_column();

    $name = isset( $_POST['name'] ) ? sanitize_text_field( $_POST['name'] ) : '';
    $slug = isset( $_POST['slug'] ) ? sanitize_title( $_POST['slug'] ) : '';
    $plan = isset( $_POST['plan'] ) ? sanitize_text_field( $_POST['plan'] ) : 'starter';
    $raw_ind = isset( $_POST['industry'] ) ? sanitize_text_field( $_POST['industry'] ) : 'real_estate';
    if ( $raw_ind === 'photography' ) {
        $raw_ind = 'photography_studio';
    }
    $industry = in_array( $raw_ind, array( 'real_estate', 'photography_studio' ), true ) ? $raw_ind : 'real_estate';
    $owner_email = isset( $_POST['owner_email'] ) ? sanitize_email( $_POST['owner_email'] ) : '';

    if ( empty( $name ) || empty( $slug ) ) {
        wp_send_json_error( array( 'message' => 'Workspace name and slug are required.' ) );
    }

    $owner_id = get_current_user_id();
    if ( ! empty( $owner_email ) ) {
        $owner_user = get_user_by( 'email', $owner_email );
        if ( $owner_user ) {
            $owner_id = $owner_user->ID;
        }
    }

    global $wpdb;
    $table_name = $wpdb->prefix . 'cora_agencies';
    
    $table_exists = $wpdb->get_var( $wpdb->prepare( "SHOW TABLES LIKE %s", $table_name ) );
    if ( $table_exists ) {
        $existing = $wpdb->get_var( $wpdb->prepare( "SELECT id FROM {$table_name} WHERE slug = %s", $slug ) );
        if ( $existing ) {
            wp_send_json_error( array( 'message' => 'Workspace slug already exists. Please choose a unique slug.' ) );
        }

        $now = current_time( 'mysql' );
        $inserted = $wpdb->insert(
            $table_name,
            array(
                'name' => $name,
                'slug' => $slug,
                'owner_user_id' => $owner_id,
                'plan' => $plan,
                'status' => 'active',
                'industry' => $industry,
                'created_at' => $now,
                'updated_at' => $now
            ),
            array( '%s', '%s', '%d', '%s', '%s', '%s', '%s', '%s' )
        );

        if ( $inserted ) {
            $workspace_id = $wpdb->insert_id;
            
            if ( $owner_id ) {
                update_user_meta( $owner_id, 'cora_workspace_industry', $industry );
            }

            $agencies = get_option( 'cora_agencies', array() );
            $agencies[$workspace_id] = array(
                'id' => $workspace_id,
                'name' => $name,
                'slug' => $slug,
                'plan' => $plan,
                'status' => 'active',
                'industry' => $industry,
                'owner_user_id' => $owner_id
            );
            update_option( 'cora_agencies', $agencies );

            wp_send_json_success( array(
                'message' => 'Workspace created successfully!',
                'workspace' => array(
                    'id' => $workspace_id,
                    'name' => $name,
                    'slug' => $slug,
                    'plan' => $plan,
                    'status' => 'active',
                    'industry' => $industry
                )
            ) );
        }
    }

    wp_send_json_error( array( 'message' => 'Failed to create workspace in database.' ) );
}
}
add_action( 'wp_ajax_cora_super_create_workspace', 'cora_ajax_super_create_workspace' );

/**
 * AJAX Callback: Update user status or role.
 */
if ( ! function_exists( 'cora_ajax_super_update_user' ) ) {
function cora_ajax_super_update_user() {
    check_ajax_referer( 'cora_ajax_nonce', 'security' );
    if ( ! cora_is_super_owner() ) {
        wp_send_json_error( 'Unauthorized access.' );
    }

    global $wpdb;
    $cora_user_id = isset( $_POST['user_id'] ) ? intval( $_POST['user_id'] ) : 0;
    if ( $cora_user_id <= 0 ) {
        wp_send_json_error( 'Invalid user ID.' );
    }

    $status = isset( $_POST['status'] ) ? sanitize_text_field( $_POST['status'] ) : '';
    $role = isset( $_POST['role'] ) ? sanitize_text_field( $_POST['role'] ) : '';

    if ( empty( $status ) || empty( $role ) ) {
        wp_send_json_error( 'Status and role are required.' );
    }

    $cora_users_table = $wpdb->prefix . 'cora_users';

    // Verify user exists
    $cora_user = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$cora_users_table} WHERE id = %d", $cora_user_id ), ARRAY_A );
    if ( ! $cora_user ) {
        wp_send_json_error( 'User not found.' );
    }

    $wp_user_id = intval( $cora_user['wp_user_id'] );

    // Update table
    $updated = $wpdb->update(
        $cora_users_table,
        array(
            'status' => $status,
            'role' => $role,
            'updated_at' => current_time( 'mysql' )
        ),
        array( 'id' => $cora_user_id ),
        array( '%s', '%s', '%s' ),
        array( '%d' )
    );

    if ( $updated === false ) {
        wp_send_json_error( 'Failed to update user in database.' );
    }

    // Sync to user meta
    update_user_meta( $wp_user_id, 'cora_user_status', $status );

    // Sync to wp_users role
    $wp_user = new WP_User( $wp_user_id );
    if ( $wp_user->exists() ) {
        $wp_user->set_role( $role );
    }

    wp_send_json_success( array( 'message' => 'User updated successfully.' ) );
}
}
add_action( 'wp_ajax_cora_super_update_user', 'cora_ajax_super_update_user' );

