/**
 * AJAX Endpoint: cora_ajax_save_lead_stages
 */
if ( ! function_exists( 'cora_ajax_save_lead_stages' ) ) {
    function cora_ajax_save_lead_stages() {
        $nonce = '';
        if ( isset( $_REQUEST['security'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['security'] );
        } elseif ( isset( $_REQUEST['nonce'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['nonce'] );
        } elseif ( isset( $_REQUEST['_wpnonce'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['_wpnonce'] );
        }
        if ( ! empty( $nonce ) && ! wp_verify_nonce( $nonce, 'cora_ajax_nonce' ) ) {
            wp_send_json_error( array( 'message' => 'Security check failed.' ), 403 );
        }

        $reset = isset( $_POST['reset'] ) ? sanitize_text_field( $_POST['reset'] ) : '';
        if ( $reset === 'true' ) {
            delete_option( 'cora_workspace_lead_stages' );
            wp_send_json_success( array( 'message' => 'Reset lead pipeline stages to default.' ) );
        }

        $stages_json = isset( $_POST['stages'] ) ? wp_unslash( $_POST['stages'] ) : '';
        $stages = json_decode( $stages_json, true );

        if ( is_array( $stages ) && ! empty( $stages ) ) {
            update_option( 'cora_workspace_lead_stages', $stages );
            wp_send_json_success( array( 'message' => 'Pipeline stages updated successfully.' ) );
        } else {
            wp_send_json_error( array( 'message' => 'Invalid stage configurations received.' ) );
        }
    }
    add_action( 'wp_ajax_cora_ajax_save_lead_stages', 'cora_ajax_save_lead_stages' );
    add_action( 'wp_ajax_cora_save_lead_stages', 'cora_ajax_save_lead_stages' );
}

/**
 * AJAX Endpoint: cora_ajax_get_leads / cora_ajax_get_leads_data
 */
if ( ! function_exists( 'cora_ajax_get_leads' ) ) {
    function cora_ajax_get_leads() {
        $nonce = '';
        if ( isset( $_REQUEST['security'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['security'] );
        } elseif ( isset( $_REQUEST['nonce'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['nonce'] );
        } elseif ( isset( $_REQUEST['_wpnonce'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['_wpnonce'] );
        }
        if ( ! empty( $nonce ) && ! wp_verify_nonce( $nonce, 'cora_ajax_nonce' ) ) {
            wp_send_json_error( array( 'message' => 'Security check failed.' ), 403 );
        }

        $search = isset( $_REQUEST['search'] ) ? sanitize_text_field( $_REQUEST['search'] ) : '';
        $stage  = isset( $_REQUEST['stage'] ) ? sanitize_text_field( $_REQUEST['stage'] ) : 'all';

        $leads = cora_db_get_leads();
        $filtered = array();

        foreach ( $leads as $l ) {
            if ( ! isset( $l['assigned_to'] ) ) {
                $l['assigned_to'] = 0;
            } else {
                $l['assigned_to'] = intval( $l['assigned_to'] );
            }

            if ( $stage !== 'all' && isset( $l['status'] ) && strtolower( $l['status'] ) !== strtolower( $stage ) ) {
                continue;
            }

            if ( ! empty( $search ) ) {
                $s = strtolower( $search );
                $name  = strtolower( $l['names'] ?? '' );
                $email = strtolower( $l['email'] ?? '' );
                $city  = strtolower( $l['city'] ?? '' );
                if ( strpos( $name, $s ) === false && strpos( $email, $s ) === false && strpos( $city, $s ) === false ) {
                    continue;
                }
            }

            $filtered[] = $l;
        }

        $paged    = isset( $_REQUEST['page'] ) ? max( 1, intval( $_REQUEST['page'] ) ) : ( isset( $_REQUEST['paged'] ) ? max( 1, intval( $_REQUEST['paged'] ) ) : 1 );
        $per_page = isset( $_REQUEST['per_page'] ) ? intval( $_REQUEST['per_page'] ) : 25;
        if ( $per_page <= 0 ) {
            $per_page = 25;
        }

        $total_leads = count( $filtered );
        $total_pages = max( 1, ceil( $total_leads / $per_page ) );
        if ( $paged > $total_pages && $total_pages > 0 ) {
            $paged = $total_pages;
        }
        $offset = ( $paged - 1 ) * $per_page;
        $page_items = array_slice( $filtered, $offset, $per_page );

        $team_members = cora_get_workspace_team_members();

        wp_send_json_success( array(
            'leads'        => $page_items,
            'all_leads'    => $filtered,
            'count'        => count( $page_items ),
            'total_leads'  => $total_leads,
            'total_pages'  => $total_pages,
            'current_page' => $paged,
            'per_page'     => $per_page,
            'team_members' => $team_members,
        ) );
    }
    add_action( 'wp_ajax_cora_ajax_get_leads', 'cora_ajax_get_leads' );
    add_action( 'wp_ajax_cora_get_leads', 'cora_ajax_get_leads' );
    add_action( 'wp_ajax_cora_ajax_get_leads_data', 'cora_ajax_get_leads' );
    add_action( 'wp_ajax_cora_get_leads_data', 'cora_ajax_get_leads' );
}

if ( ! function_exists( 'cora_ajax_get_leads_data' ) ) {
    function cora_ajax_get_leads_data() {
        cora_ajax_get_leads();
    }
}

/**
 * AJAX Endpoint: cora_ajax_save_lead
 */
if ( ! function_exists( 'cora_ajax_save_lead' ) ) {
    function cora_ajax_save_lead() {
        $nonce = '';
        if ( isset( $_REQUEST['security'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['security'] );
        } elseif ( isset( $_REQUEST['nonce'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['nonce'] );
        } elseif ( isset( $_REQUEST['_wpnonce'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['_wpnonce'] );
        }

        $verified = false;
        if ( ! empty( $nonce ) && wp_verify_nonce( $nonce, 'cora_ajax_nonce' ) ) {
            $verified = true;
        } elseif ( current_user_can( 'manage_options' ) ) {
            $verified = true;
        }

        if ( ! $verified ) {
            wp_send_json_error( array( 'message' => 'Security check failed.' ), 403 );
        }

        global $wpdb;
        $lead_id           = isset( $_POST['lead_id'] ) ? sanitize_text_field( $_POST['lead_id'] ) : '';
        $names             = isset( $_POST['names'] ) ? sanitize_text_field( $_POST['names'] ) : '';
        $email             = isset( $_POST['email'] ) ? sanitize_email( $_POST['email'] ) : '';
        $phone             = isset( $_POST['phone'] ) ? sanitize_text_field( $_POST['phone'] ) : '';
        $price             = isset( $_POST['price'] ) ? sanitize_text_field( $_POST['price'] ) : '';
        $scale             = isset( $_POST['scale'] ) ? sanitize_text_field( $_POST['scale'] ) : 'Standard Shoot';
        $city              = isset( $_POST['city'] ) ? sanitize_text_field( $_POST['city'] ) : 'Mumbai';
        $status            = isset( $_POST['status'] ) ? sanitize_text_field( $_POST['status'] ) : 'New Lead';
        $score             = isset( $_POST['score'] ) ? sanitize_text_field( $_POST['score'] ) : 'warm';
        $notes             = isset( $_POST['notes'] ) ? sanitize_textarea_field( $_POST['notes'] ) : '';
        $assigned_to_param = isset( $_POST['assigned_to'] ) ? intval( $_POST['assigned_to'] ) : null;

        if ( empty( $names ) || empty( $email ) ) {
            wp_send_json_error( array( 'message' => 'Client Name and Email are required fields.' ) );
        }

        $db_status_slug = 'new';
        $st_lower = strtolower( trim( $status ) );
        if ( $st_lower === 'new lead' || $st_lower === 'new inquiries' || $st_lower === 'new' ) {
            $db_status_slug = 'new';
        } elseif ( $st_lower === 'contacted' || $st_lower === 'proposal sent' ) {
            $db_status_slug = 'contacted';
        } elseif ( $st_lower === 'site visit' || $st_lower === 'site_visit' || $st_lower === 'site visit / viewing' ) {
            $db_status_slug = 'site_visit';
        } elseif ( $st_lower === 'negotiation' || $st_lower === 'negotiat' ) {
            $db_status_slug = 'negotiation';
        } elseif ( $st_lower === 'converted' || $st_lower === 'closed' || $st_lower === 'won' ) {
            $db_status_slug = 'closed';
        } elseif ( $st_lower === 'lost' ) {
            $db_status_slug = 'lost';
        }

        $price_clean = preg_replace( '/[^\d]/', '', $price );
        $budget_max = intval( $price_clean );

        $is_new = empty( $lead_id ) || ! is_numeric( $lead_id );
        
        $old_assigned_to = 0;
        if ( ! $is_new ) {
            $old_val = $wpdb->get_var( $wpdb->prepare(
                "SELECT assigned_to FROM {$wpdb->prefix}cora_leads WHERE id = %d",
                intval( $lead_id )
            ) );
            if ( null !== $old_val ) {
                $old_assigned_to = intval( $old_val );
            }
        }

        $assigned_to_val = null;
        if ( null !== $assigned_to_param ) {
            $assigned_to_val = $assigned_to_param;
        } elseif ( ! $is_new ) {
            $assigned_to_val = $old_assigned_to;
        } else {
            $assigned_to_val = 0;
        }

        $db_data = array(
            'agency_id'           => 1,
            'branch_id'           => 1,
            'assigned_to'         => $assigned_to_val ? $assigned_to_val : null,
            'first_name'          => $names,
            'last_name'           => '',
            'email'               => $email,
            'phone'               => $phone,
            'source'              => 'Direct',
            'status'              => $db_status_slug,
            'budget_min'          => 0,
            'budget_max'          => $budget_max,
            'preferred_locations' => $city,
            'property_type'       => $scale,
            'notes'               => $notes,
            'converted_to_client' => ( $db_status_slug === 'closed' ) ? 1 : 0,
            'updated_at'          => current_time( 'mysql' )
        );

        if ( $is_new ) {
            $db_data['created_at'] = current_time( 'mysql' );
            $wpdb->insert(
                $wpdb->prefix . 'cora_leads',
                $db_data,
                array( '%d', '%d', '%d', '%s', '%s', '%s', '%s', '%s', '%s', '%d', '%d', '%s', '%s', '%s', '%d', '%s', '%s' )
            );
            $lead_id = $wpdb->insert_id;
        } else {
            $wpdb->update(
                $wpdb->prefix . 'cora_leads',
                $db_data,
                array( 'id' => intval( $lead_id ) ),
                array( '%d', '%d', '%d', '%s', '%s', '%s', '%s', '%s', '%s', '%d', '%d', '%s', '%s', '%s', '%d', '%s' ),
                array( '%d' )
            );
        }

        $existing_leads = get_option( 'cora_workspace_leads', array() );
        if ( ! is_array( $existing_leads ) ) {
            $existing_leads = array();
        }

        $found = false;
        foreach ( $existing_leads as &$el ) {
            if ( (string) $el['id'] === (string) $lead_id ) {
                $el['names']       = $names;
                $el['email']       = $email;
                $el['phone']       = $phone;
                $el['price']       = $price;
                $el['scale']       = $scale;
                $el['city']        = $city;
                $el['status']      = $status;
                $el['score']       = $score;
                $el['notes']       = $notes;
                $el['assigned_to'] = $assigned_to_val ? $assigned_to_val : 0;
                $found = true;
                break;
            }
        }
        if ( ! $found ) {
            $new_lead = array(
                'id'          => $lead_id,
                'names'       => $names,
                'email'       => $email,
                'phone'       => $phone,
                'price'       => $price,
                'scale'       => $scale,
                'city'        => $city,
                'status'      => $status,
                'score'       => $score,
                'notes'       => $notes,
                'assigned_to' => $assigned_to_val ? $assigned_to_val : 0,
                'created_at'  => time(),
            );
            array_unshift( $existing_leads, $new_lead );
        }

        update_option( 'cora_workspace_leads', $existing_leads );

        if ( null !== $assigned_to_param && ( $is_new || $old_assigned_to !== $assigned_to_param ) && function_exists( 'cora_log_lead_assignment_change' ) ) {
            cora_log_lead_assignment_change( $lead_id, $assigned_to_param );
        }

        wp_send_json_success( array(
            'message' => 'Lead deal saved successfully.',
            'lead_id' => $lead_id,
        ) );
    }
    add_action( 'wp_ajax_cora_ajax_save_lead', 'cora_ajax_save_lead' );
    add_action( 'wp_ajax_cora_save_lead', 'cora_ajax_save_lead' );
}

/**
 * AJAX Endpoint: cora_ajax_update_lead_assignee
 */
if ( ! function_exists( 'cora_ajax_update_lead_assignee' ) ) {
    function cora_ajax_update_lead_assignee() {
        $lead_id = isset( $_POST['lead_id'] ) ? sanitize_text_field( $_POST['lead_id'] ) : '';
        $assigned_to = isset( $_POST['assigned_to'] ) ? sanitize_text_field( $_POST['assigned_to'] ) : '';
        
        if ( ! empty( $lead_id ) ) {
            global $wpdb;
            $wpdb->update(
                $wpdb->prefix . 'cora_leads',
                array( 'assigned_to' => intval( $assigned_to ), 'updated_at' => current_time( 'mysql' ) ),
                array( 'id' => intval( $lead_id ) ),
                array( '%d', '%s' ),
                array( '%d' )
            );

            $existing_leads = get_option( 'cora_workspace_leads', array() );
            if ( is_array( $existing_leads ) ) {
                foreach ( $existing_leads as &$el ) {
                    if ( (string) ($el['id'] ?? '') === (string) $lead_id ) {
                        $el['assigned_to'] = intval( $assigned_to );
                        break;
                    }
                }
                update_option( 'cora_workspace_leads', $existing_leads );
            }
        }
        wp_send_json_success( array( 'message' => 'Assigned team member updated successfully.' ) );
    }
    add_action( 'wp_ajax_cora_ajax_update_lead_assignee', 'cora_ajax_update_lead_assignee' );
    add_action( 'wp_ajax_cora_update_lead_assignee', 'cora_ajax_update_lead_assignee' );
}

/**
 * AJAX Endpoint: cora_ajax_update_lead_stage
 */
if ( ! function_exists( 'cora_ajax_update_lead_stage' ) ) {
    function cora_ajax_update_lead_stage() {
        $nonce = '';
        if ( isset( $_REQUEST['security'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['security'] );
        } elseif ( isset( $_REQUEST['nonce'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['nonce'] );
        } elseif ( isset( $_REQUEST['_wpnonce'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['_wpnonce'] );
        }

        $verified = false;
        if ( ! empty( $nonce ) && wp_verify_nonce( $nonce, 'cora_ajax_nonce' ) ) {
            $verified = true;
        } elseif ( current_user_can( 'manage_options' ) ) {
            $verified = true;
        }

        if ( ! $verified ) {
            wp_send_json_error( array( 'message' => 'Security check failed.' ), 403 );
        }

        global $wpdb;
        $lead_id           = isset( $_POST['lead_id'] ) ? sanitize_text_field( $_POST['lead_id'] ) : '';
        $raw_stage         = isset( $_POST['new_stage'] ) ? sanitize_text_field( $_POST['new_stage'] ) : '';
        $assigned_to_param = isset( $_POST['assigned_to'] ) ? intval( $_POST['assigned_to'] ) : null;

        if ( empty( $lead_id ) && empty( $raw_stage ) && null === $assigned_to_param ) {
            wp_send_json_error( array( 'message' => 'Lead ID is required.' ) );
        }

        $old_assigned_to = 0;
        if ( null !== $assigned_to_param ) {
            $old_val = $wpdb->get_var( $wpdb->prepare(
                "SELECT assigned_to FROM {$wpdb->prefix}cora_leads WHERE id = %s OR id = %d",
                $lead_id, intval( $lead_id )
            ) );
            if ( null !== $old_val ) {
                $old_assigned_to = intval( $old_val );
            }
        }

        $new_stage = ! empty( $raw_stage ) ? ( function_exists('cora_normalize_lead_stage') ? cora_normalize_lead_stage($raw_stage) : $raw_stage ) : '';

        if ( ! empty( $new_stage ) ) {
            // Map stage to DB status slug
            $db_status_slug = 'new';
            $st_lower = strtolower($new_stage);
            if (strpos($st_lower, 'contact') !== false || strpos($st_lower, 'proposal') !== false) {
                $db_status_slug = 'contacted';
            } elseif (strpos($st_lower, 'visit') !== false || strpos($st_lower, 'viewing') !== false) {
                $db_status_slug = 'site_visit';
            } elseif (strpos($st_lower, 'negotiat') !== false) {
                $db_status_slug = 'negotiation';
            } elseif (strpos($st_lower, 'convert') !== false) {
                $db_status_slug = 'closed';
            } elseif (strpos($st_lower, 'lost') !== false || strpos($st_lower, 'hold') !== false) {
                $db_status_slug = 'lost';
            }

            $converted_val = ( $db_status_slug === 'closed' ) ? 1 : 0;

            if ( null !== $assigned_to_param ) {
                $wpdb->query( $wpdb->prepare(
                    "UPDATE {$wpdb->prefix}cora_leads SET status = %s, converted_to_client = %d, assigned_to = %d, updated_at = %s WHERE id = %s OR id = %d",
                    $db_status_slug, $converted_val, $assigned_to_param ? $assigned_to_param : null, current_time( 'mysql' ), $lead_id, intval( $lead_id )
                ) );
            } else {
                $wpdb->query( $wpdb->prepare(
                    "UPDATE {$wpdb->prefix}cora_leads SET status = %s, converted_to_client = %d, updated_at = %s WHERE id = %s OR id = %d",
                    $db_status_slug, $converted_val, current_time( 'mysql' ), $lead_id, intval( $lead_id )
                ) );
            }
        } elseif ( null !== $assigned_to_param ) {
            $wpdb->query( $wpdb->prepare(
                "UPDATE {$wpdb->prefix}cora_leads SET assigned_to = %d, updated_at = %s WHERE id = %s OR id = %d",
                $assigned_to_param ? $assigned_to_param : null, current_time( 'mysql' ), $lead_id, intval( $lead_id )
            ) );
        }

        $all_leads = cora_db_get_leads();
        $raw_opt_val = $wpdb->get_var( $wpdb->prepare(
            "SELECT option_value FROM {$wpdb->options} WHERE option_name = %s",
            'cora_workspace_leads'
        ) );
        $existing_leads = ! empty( $raw_opt_val ) ? maybe_unserialize( $raw_opt_val ) : array();
        if ( ! is_array( $existing_leads ) || empty( $existing_leads ) ) {
            $existing_leads = $all_leads;
        }

        $updated = false;
        $matched_lead = null;
        $agency_id_slug = cora_get_current_user_agency_id();
        $assigned_agency_id = ( $agency_id_slug === 'super' || empty( $agency_id_slug ) ) ? 'default' : $agency_id_slug;

        foreach ( $existing_leads as &$el ) {
            if ( (string) $el['id'] === (string) $lead_id ) {
                if ( ! empty( $new_stage ) ) {
                    $el['status'] = $new_stage;
                }
                if ( null !== $assigned_to_param ) {
                    $el['assigned_to'] = $assigned_to_param;
                }
                if ( ! isset( $el['agency_id'] ) ) {
                    $el['agency_id'] = $assigned_agency_id;
                }
                $updated = true;
                $matched_lead = $el;
                break;
            }
        }

        if ( ! $updated ) {
            $full_meta = null;
            foreach ( $all_leads as $al ) {
                if ( (string) $al['id'] === (string) $lead_id ) {
                    $full_meta = $al;
                    break;
                }
            }
            if ( $full_meta ) {
                $matched_lead = $full_meta;
                if ( ! empty( $new_stage ) ) {
                    $matched_lead['status'] = $new_stage;
                }
                if ( null !== $assigned_to_param ) {
                    $matched_lead['assigned_to'] = $assigned_to_param;
                }
                if ( ! isset( $matched_lead['agency_id'] ) ) {
                    $matched_lead['agency_id'] = $assigned_agency_id;
                }
            } else {
                $matched_lead = array(
                    'id'          => $lead_id,
                    'names'       => 'Client Inquiry',
                    'status'      => $new_stage ?: 'New Lead',
                    'price'       => '₹0',
                    'assigned_to' => $assigned_to_param ?: 0,
                    'created_at'  => time(),
                    'agency_id'   => $assigned_agency_id
                );
            }
            $existing_leads[] = $matched_lead;
            $updated = true;
        }

        remove_filter( 'pre_update_option_cora_workspace_leads', 'cora_pre_update_tenancy_data', 10 );
        update_option( 'cora_workspace_leads', $existing_leads );
        add_filter( 'pre_update_option_cora_workspace_leads', 'cora_pre_update_tenancy_data', 10, 3 );

        if ( $new_stage === 'Converted' && $matched_lead ) {
            cora_copy_lead_to_clients( $matched_lead );
        }

        if ( null !== $assigned_to_param && $old_assigned_to !== $assigned_to_param && function_exists( 'cora_log_lead_assignment_change' ) ) {
            cora_log_lead_assignment_change( $lead_id, $assigned_to_param );
        }

        wp_send_json_success( array(
            'message'   => 'Lead stage/assignment updated successfully.',
            'lead_id'   => $lead_id,
            'new_stage' => $new_stage,
        ) );
    }
    add_action( 'wp_ajax_cora_ajax_update_lead_stage', 'cora_ajax_update_lead_stage' );
    add_action( 'wp_ajax_cora_update_lead_stage', 'cora_ajax_update_lead_stage' );
}

/**
 * AJAX Endpoint: cora_ajax_save_lead_field
 */
if ( ! function_exists( 'cora_ajax_save_lead_field' ) ) {
    function cora_ajax_save_lead_field() {
        $nonce = '';
        if ( isset( $_REQUEST['security'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['security'] );
        } elseif ( isset( $_REQUEST['nonce'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['nonce'] );
        } elseif ( isset( $_REQUEST['_wpnonce'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['_wpnonce'] );
        }

        $verified = false;
        if ( ! empty( $nonce ) && wp_verify_nonce( $nonce, 'cora_ajax_nonce' ) ) {
            $verified = true;
        } elseif ( current_user_can( 'manage_options' ) ) {
            $verified = true;
        }

        if ( ! $verified ) {
            wp_send_json_error( array( 'message' => 'Security check failed.' ), 403 );
        }

        global $wpdb;
        $lead_id     = isset( $_POST['lead_id'] ) ? sanitize_text_field( $_POST['lead_id'] ) : ( isset( $_POST['id'] ) ? sanitize_text_field( $_POST['id'] ) : '' );
        $field_name  = isset( $_POST['field_name'] ) ? sanitize_text_field( $_POST['field_name'] ) : ( isset( $_POST['field'] ) ? sanitize_text_field( $_POST['field'] ) : '' );
        $field_value = isset( $_POST['field_value'] ) ? sanitize_text_field( $_POST['field_value'] ) : ( isset( $_POST['value'] ) ? sanitize_text_field( $_POST['value'] ) : '' );

        if ( empty( $lead_id ) ) {
            wp_send_json_error( array( 'message' => 'Lead ID is required.' ) );
        }

        if ( isset( $_POST['assigned_to'] ) || $field_name === 'assigned_to' ) {
            $assigned_to_id = isset( $_POST['assigned_to'] ) ? intval( $_POST['assigned_to'] ) : intval( $field_value );

            $old_assigned_to = $wpdb->get_var( $wpdb->prepare(
                "SELECT assigned_to FROM {$wpdb->prefix}cora_leads WHERE id = %s OR id = %d",
                $lead_id, intval( $lead_id )
            ) );
            $old_assigned_to = $old_assigned_to !== null ? intval( $old_assigned_to ) : 0;

            $wpdb->query( $wpdb->prepare(
                "UPDATE {$wpdb->prefix}cora_leads SET assigned_to = %d, updated_at = %s WHERE id = %s OR id = %d",
                $assigned_to_id ? $assigned_to_id : null, current_time( 'mysql' ), $lead_id, intval( $lead_id )
            ) );

            $existing_leads = get_option( 'cora_workspace_leads', array() );
            if ( is_array( $existing_leads ) ) {
                foreach ( $existing_leads as &$el ) {
                    if ( (string) ( $el['id'] ?? '' ) === (string) $lead_id ) {
                        $el['assigned_to'] = $assigned_to_id;
                        break;
                    }
                }
                remove_filter( 'pre_update_option_cora_workspace_leads', 'cora_pre_update_tenancy_data', 10 );
                update_option( 'cora_workspace_leads', $existing_leads );
                add_filter( 'pre_update_option_cora_workspace_leads', 'cora_pre_update_tenancy_data', 10, 3 );
            }

            if ( $old_assigned_to !== $assigned_to_id && function_exists( 'cora_log_lead_assignment_change' ) ) {
                cora_log_lead_assignment_change( $lead_id, $assigned_to_id );
            }

            wp_send_json_success( array(
                'message'     => 'Lead assignment updated successfully.',
                'lead_id'     => $lead_id,
                'assigned_to' => $assigned_to_id,
            ) );
        }

        wp_send_json_error( array( 'message' => 'Invalid or unsupported field name.' ) );
    }
    add_action( 'wp_ajax_cora_ajax_save_lead_field', 'cora_ajax_save_lead_field' );
    add_action( 'wp_ajax_cora_save_lead_field', 'cora_ajax_save_lead_field' );
}

/**
 * AJAX Endpoint: cora_ajax_convert_lead_to_client_suite
 */
if ( ! function_exists( 'cora_ajax_convert_lead_to_client_suite' ) ) {
    function cora_ajax_convert_lead_to_client_suite() {
        $nonce = '';
        if ( isset( $_REQUEST['security'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['security'] );
        } elseif ( isset( $_REQUEST['nonce'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['nonce'] );
        } elseif ( isset( $_REQUEST['_wpnonce'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['_wpnonce'] );
        }

        $verified = false;
        if ( ! empty( $nonce ) && wp_verify_nonce( $nonce, 'cora_ajax_nonce' ) ) {
            $verified = true;
        } elseif ( current_user_can( 'manage_options' ) ) {
            $verified = true;
        }

        if ( ! $verified ) {
            wp_send_json_error( array( 'message' => 'Security check failed.' ), 403 );
        }

        $lead_id = isset( $_POST['lead_id'] ) ? sanitize_text_field( $_POST['lead_id'] ) : '';
        if ( empty( $lead_id ) ) {
            wp_send_json_error( array( 'message' => 'Lead ID required.' ) );
        }

        $existing_leads = get_option( 'cora_workspace_leads', array() );
        if ( ! is_array( $existing_leads ) ) {
            $existing_leads = array();
        }

        $converted_lead = null;
        foreach ( $existing_leads as &$el ) {
            if ( (string) $el['id'] === (string) $lead_id ) {
                $el['status'] = 'Converted';
                $el['converted_to_client'] = 1;
                $converted_lead = $el;
                break;
            }
        }
        update_option( 'cora_workspace_leads', $existing_leads );

        if ( $converted_lead ) {
            $clients = get_option( 'cora_workspace_clients', array() );
            if ( ! is_array( $clients ) ) {
                $clients = array();
            }

            $new_client = array(
                'id'         => 'client_' . time(),
                'lead_id'    => $lead_id,
                'names'      => $converted_lead['names'] ?? 'Client',
                'email'      => $converted_lead['email'] ?? '',
                'phone'      => $converted_lead['phone'] ?? '',
                'city'       => $converted_lead['city'] ?? '',
                'status'     => 'Active Client',
                'created_at' => time(),
            );

            array_unshift( $clients, $new_client );
            update_option( 'cora_workspace_clients', $clients );

            $booking_title = ($converted_lead['scale'] ?? 'Standard') . ' Shoot - ' . ($converted_lead['city'] ?? 'Mumbai');
            cora_auto_generate_client_tasks( $new_client['id'], $new_client['names'], $booking_title );
            cora_auto_generate_client_timeline( $new_client['id'], $new_client['names'], $booking_title, $converted_lead['phone'] ?? '' );

            wp_send_json_success( array(
                'message' => 'Lead converted to active client successfully!',
                'client'  => $new_client,
            ) );
        } else {
            wp_send_json_error( array( 'message' => 'Lead record not found.' ) );
        }
    }
    add_action( 'wp_ajax_cora_ajax_convert_lead_to_client_suite', 'cora_ajax_convert_lead_to_client_suite' );
    add_action( 'wp_ajax_cora_convert_lead_to_client_suite', 'cora_ajax_convert_lead_to_client_suite' );
}

/**
 * AJAX Endpoint: cora_ajax_delete_lead_suite
 */
if ( ! function_exists( 'cora_ajax_delete_lead_suite' ) ) {
    function cora_ajax_delete_lead_suite() {
        $nonce = '';
        if ( isset( $_REQUEST['security'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['security'] );
        } elseif ( isset( $_REQUEST['nonce'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['nonce'] );
        } elseif ( isset( $_REQUEST['_wpnonce'] ) ) {
            $nonce = sanitize_text_field( $_REQUEST['_wpnonce'] );
        }

        $verified = false;
        if ( ! empty( $nonce ) && wp_verify_nonce( $nonce, 'cora_ajax_nonce' ) ) {
            $verified = true;
        } elseif ( current_user_can( 'manage_options' ) ) {
            $verified = true;
        }

        if ( ! $verified ) {
            wp_send_json_error( array( 'message' => 'Security check failed.' ), 403 );
        }

        $lead_id = isset( $_POST['lead_id'] ) ? sanitize_text_field( $_POST['lead_id'] ) : '';
        if ( empty( $lead_id ) ) {
            wp_send_json_error( array( 'message' => 'Lead ID required.' ) );
        }

        $existing_leads = get_option( 'cora_workspace_leads', array() );
        if ( ! is_array( $existing_leads ) ) {
            $existing_leads = array();
        }

        $filtered = array_filter( $existing_leads, function( $l ) use ( $lead_id ) {
            return (string) $l['id'] !== (string) $lead_id;
        });

        update_option( 'cora_workspace_leads', array_values( $filtered ) );

        wp_send_json_success( array(
            'message' => 'Lead deleted from workspace.',
            'lead_id' => $lead_id,
        ) );
    }
    add_action( 'wp_ajax_cora_ajax_delete_lead_suite', 'cora_ajax_delete_lead_suite' );
    add_action( 'wp_ajax_cora_delete_lead_suite', 'cora_ajax_delete_lead_suite' );
}


/**
 * AJAX Action: Generate Automated Financial Report Summary & HTML Breakdown
 */
if ( ! function_exists( 'cora_ajax_generate_financial_report' ) ) {
function cora_ajax_generate_financial_report() {
    $nonce = '';
    if ( isset( $_REQUEST['security'] ) ) {
        $nonce = sanitize_text_field( $_REQUEST['security'] );
    } elseif ( isset( $_REQUEST['nonce'] ) ) {
        $nonce = sanitize_text_field( $_REQUEST['nonce'] );
    } elseif ( isset( $_REQUEST['_wpnonce'] ) ) {
        $nonce = sanitize_text_field( $_REQUEST['_wpnonce'] );
    }
    if ( ! empty( $nonce ) && ! wp_verify_nonce( $nonce, 'cora_ajax_nonce' ) ) {
        wp_send_json_error( array( 'message' => 'Security check failed.' ), 403 );
    }

    $valid_types = array( 'daily', 'weekly', 'monthly', 'quarterly' );
    $report_type = isset( $_REQUEST['report_type'] ) ? strtolower( sanitize_text_field( $_REQUEST['report_type'] ) ) : 'monthly';
    if ( ! in_array( $report_type, $valid_types, true ) ) {
        $report_type = 'monthly';
    }

    $ledger = get_option( 'cora_financial_ledger', array() );
    if ( ! is_array( $ledger ) || empty( $ledger ) ) {
        $ledger = get_option( 'cora_workspace_ledger', array() );
    }

    // Baseline Monthly Financial Standards (in INR ₹)
    $base_gross_revenue   = 485000;
    $base_operating_costs = 78000;
    $base_food_travel     = 22400;
    $base_gear_rental     = 34000;
    $base_agent_splits    = 28000;

    $multiplier = 1.0;
    $period_label = 'Current Month';
    switch ( $report_type ) {
        case 'daily':
            $multiplier = 1 / 30;
            $period_label = 'Daily Digest (' . date( 'M j, Y' ) . ')';
            break;
        case 'weekly':
            $multiplier = 7 / 30;
            $period_label = '7-Day Summary (' . date( 'M j', strtotime( '-6 days' ) ) . ' - ' . date( 'M j, Y' ) . ')';
            break;
        case 'monthly':
            $multiplier = 1.0;
            $period_label = 'Monthly P&L (' . date( 'F Y' ) . ')';
            break;
        case 'quarterly':
            $multiplier = 3.0;
            $period_label = 'Quarterly Tax & Revenue Audit (' . date( 'Y' ) . ' Q' . ceil( date( 'n' ) / 3 ) . ')';
            break;
    }

    $gross_revenue   = round( $base_gross_revenue * $multiplier, 2 );
    $operating_costs = round( $base_operating_costs * $multiplier, 2 );
    $food_travel     = round( $base_food_travel * $multiplier, 2 );
    $gear_rental     = round( $base_gear_rental * $multiplier, 2 );
    $agent_splits    = round( $base_agent_splits * $multiplier, 2 );

    if ( is_array( $ledger ) && count( $ledger ) > 0 ) {
        $calc_revenue = 0;
        foreach ( $ledger as $entry ) {
            $amt = floatval( $entry['amount'] ?? 0 );
            $type = strtolower( trim( $entry['type'] ?? 'inflow' ) );
            if ( $type === 'inflow' ) {
                $calc_revenue += $amt;
            }
        }
        if ( $calc_revenue > 0 ) {
            $gross_revenue = round( $calc_revenue * $multiplier, 2 );
        }
    }

    $total_expenses = $operating_costs + $food_travel + $gear_rental + $agent_splits;
    $net_profit     = $gross_revenue - $total_expenses;
    $margin_pct     = ( $gross_revenue > 0 ) ? round( ( $net_profit / $gross_revenue ) * 100, 1 ) : 0.0;

    $data = array(
        'report_type'      => $report_type,
        'report_title'     => ucfirst( $report_type ) . ' Financial Report Summary',
        'period_label'     => $period_label,
        'generated_at'     => current_time( 'mysql' ),
        'gross_revenue'    => $gross_revenue,
        'operating_costs'  => $operating_costs,
        'food_travel'      => $food_travel,
        'gear_rental'      => $gear_rental,
        'agent_splits'     => $agent_splits,
        'total_expenses'   => $total_expenses,
        'net_profit'       => $net_profit,
        'margin_pct'       => $margin_pct,
        'formatted'        => array(
            'gross_revenue'   => '₹' . number_format( $gross_revenue ),
            'operating_costs' => '₹' . number_format( $operating_costs ),
            'food_travel'     => '₹' . number_format( $food_travel ),
            'gear_rental'     => '₹' . number_format( $gear_rental ),
            'agent_splits'    => '₹' . number_format( $agent_splits ),
            'total_expenses'  => '₹' . number_format( $total_expenses ),
            'net_profit'      => '₹' . number_format( $net_profit ),
            'margin_pct'      => $margin_pct . '%',
        ),
    );

    ob_start();
    ?>
    <div class="space-y-4 font-sans text-zinc-900 dark:text-zinc-100">
        <div class="flex items-center justify-between border-b border-zinc-200 dark:border-zinc-800 pb-3">
            <div>
                <h4 class="text-sm font-bold tracking-tight text-zinc-900 dark:text-zinc-100"><?php echo esc_html( ucfirst( $report_type ) ); ?> Financial P&L Statement</h4>
                <p class="text-[11px] text-zinc-500 dark:text-zinc-400"><?php echo esc_html( $period_label ); ?> &bull; Generated <?php echo esc_html( date( 'M j, Y g:i A' ) ); ?></p>
            </div>
            <span class="px-2.5 py-1 text-xs font-mono font-bold rounded-full bg-zinc-900 text-white dark:bg-zinc-100 dark:text-zinc-900">
                <?php echo esc_html( $margin_pct ); ?>% Margin
            </span>
        </div>

        <div class="grid grid-cols-2 gap-3 text-xs">
            <div class="p-3 rounded-lg bg-zinc-50 dark:bg-zinc-800/60 border border-zinc-200 dark:border-zinc-700">
                <span class="text-[10px] font-bold text-zinc-400 uppercase tracking-wider block">Gross Revenue</span>
                <div class="text-base font-extrabold text-zinc-900 dark:text-zinc-100 mt-1">₹<?php echo number_format( $gross_revenue ); ?></div>
            </div>
            <div class="p-3 rounded-lg bg-zinc-50 dark:bg-zinc-800/60 border border-zinc-200 dark:border-zinc-700">
                <span class="text-[10px] font-bold text-zinc-400 uppercase tracking-wider block">Net Profit</span>
                <div class="text-base font-extrabold text-zinc-900 dark:text-zinc-100 mt-1">₹<?php echo number_format( $net_profit ); ?></div>
            </div>
        </div>

        <div class="border border-zinc-200 dark:border-zinc-800 rounded-lg overflow-hidden">
            <table class="w-full text-left border-collapse text-xs">
                <thead>
                    <tr class="bg-zinc-100 dark:bg-zinc-800/80 text-zinc-600 dark:text-zinc-400 font-semibold uppercase text-[10px] tracking-wider border-b border-zinc-200 dark:border-zinc-700">
                        <th class="p-2.5">Category</th>
                        <th class="p-2.5 text-right">Amount (₹)</th>
                    </tr>
                </thead>
                <tbody class="divide-y divide-zinc-150 dark:divide-zinc-800">
                    <tr>
                        <td class="p-2.5 font-medium">Operating Costs</td>
                        <td class="p-2.5 text-right font-mono">₹<?php echo number_format( $operating_costs ); ?></td>
                    </tr>
                    <tr>
                        <td class="p-2.5 font-medium">Food & Travel Expenses</td>
                        <td class="p-2.5 text-right font-mono">₹<?php echo number_format( $food_travel ); ?></td>
                    </tr>
                    <tr>
                        <td class="p-2.5 font-medium">Gear Rental Costs</td>
                        <td class="p-2.5 text-right font-mono">₹<?php echo number_format( $gear_rental ); ?></td>
                    </tr>
                    <tr>
                        <td class="p-2.5 font-medium">Agent / Freelancer Splits</td>
                        <td class="p-2.5 text-right font-mono">₹<?php echo number_format( $agent_splits ); ?></td>
                    </tr>
                    <tr class="bg-zinc-50 dark:bg-zinc-800/40 font-bold border-t border-zinc-200 dark:border-zinc-700">
                        <td class="p-2.5">Total Outflows & Expenses</td>
                        <td class="p-2.5 text-right font-mono">₹<?php echo number_format( $total_expenses ); ?></td>
                    </tr>
                </tbody>
            </table>
        </div>
    </div>
    <?php
    $report_html = ob_get_clean();

    wp_send_json_success( array(
        'message'     => 'Report generated successfully',
        'report_html' => $report_html,
        'data'        => $data,
    ) );
}
}
