// batch_download_zip
add_action('wp_ajax_cora_batch_download_zip', 'cora_ajax_batch_download_zip');
if ( ! function_exists( 'cora_ajax_batch_download_zip' ) ) {
function cora_ajax_batch_download_zip() {
    check_ajax_referer('cora_ajax_nonce', 'nonce');
    if ( ! current_user_can('read') ) wp_send_json_error('Permission denied');
    $raw_ids = sanitize_text_field($_POST['ids'] ?? '');
    $ids     = array_filter(array_map('intval', explode(',', $raw_ids)));
    if ( empty($ids) ) wp_send_json_error('No files selected');

    if ( ! class_exists('ZipArchive') ) {
        wp_send_json_error('ZipArchive extension missing on server');
    }

    $upload_dir = wp_upload_dir();
    $zip_filename = 'cora_media_' . date('Ymd_His') . '_' . rand(100,999) . '.zip';
    $zip_filepath = $upload_dir['path'] . '/' . $zip_filename;
    $zip_fileurl  = $upload_dir['url']  . '/' . $zip_filename;

    $zip = new ZipArchive();
    if ( $zip->open($zip_filepath, ZipArchive::CREATE | ZipArchive::OVERWRITE) !== true ) {
        wp_send_json_error('Could not create ZIP file');
    }

    $count = 0;
    foreach ( $ids as $id ) {
        $file_path = get_attached_file($id);
        if ( $file_path && file_exists($file_path) ) {
            $zip->addFile($file_path, basename($file_path));
            $count++;
        }
    }
    $zip->close();

    if ( $count === 0 ) {
        @unlink($zip_filepath);
        wp_send_json_error('No physical files found to compress');
    }

    wp_send_json_success(array('url' => $zip_fileurl, 'count' => $count));
}
}

// share_folder
add_action('wp_ajax_cora_media_library_share_folder', 'cora_ajax_media_library_share_folder');
if ( ! function_exists( 'cora_ajax_media_library_share_folder' ) ) {
function cora_ajax_media_library_share_folder() {
    check_ajax_referer('cora_ajax_nonce', 'nonce');
    if ( ! current_user_can('read') ) wp_send_json_error('Permission denied');
    $folder_id = intval($_POST['folder_id']);
    if ( ! $folder_id ) wp_send_json_error('Folder ID required');
    $term = get_term($folder_id, 'cora_media_folder');
    if ( ! $term || is_wp_error($term) ) wp_send_json_error('Folder not found');

    $shares = get_option('cora_folder_shares', array());
    if ( ! is_array($shares) ) $shares = array();
    
    if ( empty($shares[$folder_id]) ) {
        $token = 'fshare_' . bin2hex(random_bytes(8));
        $shares[$folder_id] = array(
            'folder_id'  => $folder_id,
            'folder_name'=> $term->name,
            'token'      => $token,
            'created_at' => current_time('mysql')
        );
        update_option('cora_folder_shares', $shares);
    } else {
        $token = $shares[$folder_id]['token'];
    }

    $share_url = add_query_arg( array(
        'cora_share_folder' => $folder_id,
        'token'             => $token
    ), site_url('/workspace/media') );

    wp_send_json_success(array(
        'folder_id'   => $folder_id,
        'folder_name' => $term->name,
        'token'       => $token,
        'share_url'   => $share_url
    ));
}
}

// email_folder_share
add_action('wp_ajax_cora_media_library_email_folder', 'cora_ajax_media_library_email_folder');
if ( ! function_exists( 'cora_ajax_media_library_email_folder' ) ) {
function cora_ajax_media_library_email_folder() {
    check_ajax_referer('cora_ajax_nonce', 'nonce');
    if ( ! current_user_can('read') ) wp_send_json_error('Permission denied');
    $folder_id    = intval($_POST['folder_id']);
    $client_email = sanitize_email($_POST['email']);
    $share_url    = esc_url_raw($_POST['share_url']);

    if ( ! $folder_id || empty($client_email) || empty($share_url) ) {
        wp_send_json_error('Invalid email or folder URL.');
    }

    $term = get_term($folder_id, 'cora_media_folder');
    $folder_name = ($term && !is_wp_error($term)) ? $term->name : 'Media Gallery';

    $subject = "Media Folder Shared: " . $folder_name;
    $message = "Hello,\n\nYou have been granted access to view the folder '" . $folder_name . "'.\n\nClick the link below to access your media assets:\n" . $share_url . "\n\nBest regards,\nCora Workspace";

    $sent = wp_mail($client_email, $subject, $message);
    if ($sent) {
        wp_send_json_success('Folder link emailed to ' . $client_email);
    } else {
        wp_send_json_error('Email delivery failed. Please copy the link manually.');
    }
}
}

// ── SECURE DOCUMENT VAULT AJAX HANDLERS ────────────────────────────────────────

add_action('wp_ajax_cora_save_document', 'cora_ajax_vault_save_document');
if ( ! function_exists( 'cora_ajax_vault_save_document' ) ) {
function cora_ajax_vault_save_document() {
    check_ajax_referer('cora_ajax_nonce', 'nonce');
    if ( ! current_user_can('read') ) wp_send_json_error('Permission denied');

    $id           = sanitize_text_field($_POST['id'] ?? '');
    $number       = sanitize_text_field($_POST['number'] ?? '');
    $title        = sanitize_text_field($_POST['title'] ?? '');
    $type         = sanitize_text_field($_POST['type'] ?? 'Proposal');
    $status       = sanitize_text_field($_POST['status'] ?? 'Sent');
    $client_name  = sanitize_text_field($_POST['client_name'] ?? '');
    $client_email = sanitize_email($_POST['client_email'] ?? '');
    $client_phone = sanitize_text_field($_POST['client_phone'] ?? '');
    $client_gstin = sanitize_text_field($_POST['client_gstin'] ?? '');
    $pos_state    = sanitize_text_field($_POST['pos_state'] ?? 'Delhi (07)');
    $upi_vpa      = sanitize_text_field($_POST['upi_vpa'] ?? 'cora@icici');
    $password     = sanitize_text_field($_POST['password'] ?? '');
    $watermark    = sanitize_text_field($_POST['watermark'] ?? 'CONFIDENTIAL');
    $content      = wp_kses_post($_POST['content'] ?? '');
    $items_raw    = $_POST['items'] ?? '[]';
    $items        = json_decode(stripslashes($items_raw), true);

    if ( empty($title) || empty($client_name) ) {
        wp_send_json_error('Title and client name are required.');
    }

    $amount = floatval($_POST['amount'] ?? 0);
    $tax_total = 0;
    if ( is_array($items) ) {
        $calc_amount = 0;
        foreach ($items as $it) {
            $r = floatval($it['rate'] ?? 0);
            $q = floatval($it['qty'] ?? 1);
            $t = floatval($it['tax'] ?? 18);
            $line = $r * $q;
            $calc_amount += $line;
            $tax_total += $line * ($t / 100);
        }
        if ($amount <= 0) $amount = $calc_amount;
    }

    $is_igst = ( strpos( $pos_state, 'Delhi' ) === false );
    $grand_total = $amount + $tax_total;
    $cgst_amount = $is_igst ? 0 : ($tax_total / 2);
    $sgst_amount = $is_igst ? 0 : ($tax_total / 2);
    $igst_amount = $is_igst ? $tax_total : 0;

    $docs = get_option('cora_documents', array());
    if ( ! is_array($docs) ) $docs = array();

    if ( empty($id) ) {
        $id = 'doc_' . date('Ymd') . '_' . rand(100,999);
        if ( empty($number) ) {
            $prefix = strtoupper(substr($type, 0, 3));
            $number = $prefix . '-' . date('Y') . '-' . rand(1000, 9999);
        }
        $new_doc = array(
            'id'             => $id,
            'number'         => $number,
            'title'          => $title,
            'type'           => $type,
            'status'         => $status,
            'client_name'    => $client_name,
            'client_email'   => $client_email,
            'client_phone'   => $client_phone,
            'client_gstin'   => $client_gstin,
            'pos_state'      => $pos_state,
            'is_igst'        => $is_igst,
            'amount'         => $amount,
            'tax_amount'     => $tax_total,
            'cgst_amount'    => $cgst_amount,
            'sgst_amount'    => $sgst_amount,
            'igst_amount'    => $igst_amount,
            'grand_total'    => $grand_total,
            'deposit'        => $grand_total * 0.5,
            'currency'       => 'INR',
            'upi_vpa'        => $upi_vpa,
            'password'       => $password,
            'watermark'      => $watermark,
            'content'        => $content,
            'created_at'     => date('Y-m-d'),
            'token'          => 'vtoken_' . bin2hex(random_bytes(6)),
            'secured_shares' => array(
                array(
                    'hash'        => wp_hash( $id . time() . uniqid() ),
                    'email'       => $client_email ?: 'client@example.com',
                    'expiry_time' => 0,
                    'created_at'  => time()
                )
            ),
            'signed'         => false,
            'items'          => $items
        );
        $docs[] = $new_doc;

        // Auto-Sync Financial Ledger Receivable
        $ledger = get_option('cora_financial_ledger', array());
        if ( ! is_array($ledger) ) $ledger = array();
        $ledger[] = array(
            'id'          => 'fin_' . uniqid(),
            'type'        => 'inflow',
            'category'    => 'Document Billing: ' . $type,
            'description' => $title . ' (' . $client_name . ')',
            'amount'      => $grand_total,
            'status'      => 'pending',
            'date'        => date('Y-m-d')
        );
        update_option('cora_financial_ledger', $ledger);

    } else {
        foreach ($docs as &$d) {
            if ($d['id'] === $id) {
                if ( ! empty($number) ) $d['number'] = $number;
                $d['title']        = $title;
                $d['type']         = $type;
                $d['status']       = $status;
                $d['client_name']  = $client_name;
                $d['client_email'] = $client_email;
                $d['client_phone'] = $client_phone;
                $d['client_gstin'] = $client_gstin;
                $d['pos_state']    = $pos_state;
                $d['is_igst']      = $is_igst;
                $d['upi_vpa']      = $upi_vpa;
                $d['amount']       = $amount;
                $d['tax_amount']   = $tax_total;
                $d['cgst_amount']  = $cgst_amount;
                $d['sgst_amount']  = $sgst_amount;
                $d['igst_amount']  = $igst_amount;
                $d['grand_total']  = $grand_total;
                $d['deposit']      = $grand_total * 0.5;
                $d['items']        = $items;
                break;
            }
        }
    }

    update_option('cora_documents', $docs);
    wp_send_json_success(array('message' => 'Document saved & financial ledger synced!', 'id' => $id));
}
}

add_action('wp_ajax_cora_sign_document', 'cora_ajax_sign_document');
if ( ! function_exists( 'cora_ajax_sign_document' ) ) {
function cora_ajax_sign_document() {
    check_ajax_referer('cora_ajax_nonce', 'nonce');
    if ( ! current_user_can('read') ) wp_send_json_error('Permission denied');

    $doc_id         = sanitize_text_field($_POST['doc_id'] ?? '');
    $signer_name    = sanitize_text_field($_POST['signer_name'] ?? '');
    $signer_email   = sanitize_email($_POST['signer_email'] ?? '');
    $signature_data = sanitize_textarea_field($_POST['signature_data'] ?? '');
    $sign_role      = sanitize_text_field($_POST['sign_role'] ?? 'admin'); // 'admin' or 'client'

    if ( empty($doc_id) || empty($signer_name) || empty($signer_email) ) {
        wp_send_json_error('Signer name and email are required.');
    }

    $docs = get_option('cora_documents', array());
    if ( ! is_array($docs) ) $docs = array();

    $found = false;
    foreach ($docs as &$d) {
        if ( (string)$d['id'] === (string)$doc_id ) {
            $time_now = current_time('mysql');
            $ip_now   = $_SERVER['REMOTE_ADDR'] ?? '127.0.0.1';
            $hash_now = 'ESIGN-HASH-' . strtoupper(substr(md5($doc_id . $signer_name . time()), 0, 12));

            if ($sign_role === 'client') {
                $d['client_signed']            = true;
                $d['client_signer_name']       = $signer_name;
                $d['client_signer_email']      = $signer_email;
                $d['client_signature_data']    = $signature_data;
                $d['client_signed_at']         = $time_now;
                $d['client_signer_ip']         = $ip_now;
                $d['client_verification_hash'] = $hash_now;

                // Keep legacy fields for backward compatibility
                $d['signed']                   = true;
                $d['signer_name']              = $signer_name;
                $d['signer_email']             = $signer_email;
                $d['signature_data']           = $signature_data;
                $d['signed_at']                = $time_now;
                $d['signer_ip']                = $ip_now;
                $d['verification_hash']         = $hash_now;
            } else {
                // Admin / Workspace Signatory
                $d['admin_signed']             = true;
                $d['admin_signer_name']        = $signer_name;
                $d['admin_signer_email']       = $signer_email;
                $d['admin_signature_data']     = $signature_data;
                $d['admin_signed_at']          = $time_now;
                $d['admin_signer_ip']          = $ip_now;
                $d['admin_verification_hash']   = $hash_now;
            }

            // Recalculate document status
            $admin_done = !empty($d['admin_signed']);
            $client_done = !empty($d['client_signed']);

            if ($admin_done && $client_done) {
                $d['status'] = 'Signed';
            } elseif ($admin_done || $client_done) {
                $d['status'] = 'Partially Signed';
            } else {
                $d['status'] = 'Sent';
            }

            $found = true;
            break;
        }
    }

    if ($found) {
        update_option('cora_documents', $docs);
        wp_send_json_success('Document e-signed successfully!');
    } else {
        wp_send_json_error('Document not found.');
    }
}
}

add_action('wp_ajax_cora_client_esign', 'cora_ajax_client_esign');
add_action('wp_ajax_nopriv_cora_client_esign', 'cora_ajax_client_esign');
if ( ! function_exists( 'cora_ajax_client_esign' ) ) {
function cora_ajax_client_esign() {
    $doc_id         = sanitize_text_field($_POST['doc_id'] ?? '');
    $share_hash     = sanitize_text_field($_POST['share_hash'] ?? '');
    $signer_name    = sanitize_text_field($_POST['signer_name'] ?? '');
    $signer_email   = sanitize_email($_POST['signer_email'] ?? '');
    $signature_data = sanitize_textarea_field($_POST['signature_data'] ?? '');

    if ( empty($doc_id) || empty($share_hash) || empty($signer_name) || empty($signer_email) || empty($signature_data) ) {
        wp_send_json_error('All fields and drawing signature are required.');
    }

    $time_now = current_time('mysql');
    $ip_now   = $_SERVER['REMOTE_ADDR'] ?? '127.0.0.1';
    $hash_now = 'ESIGN-HASH-' . strtoupper(substr(md5($doc_id . $signer_name . time()), 0, 12));

    // Try finding in cora_documents first
    $found_in_cora_docs = false;
    $cora_docs = get_option('cora_documents', array());
    if ( is_array($cora_docs) ) {
        foreach ($cora_docs as &$d) {
            if ( (string)$d['id'] === (string)$doc_id ) {
                // Verify hash exists in secured_shares
                $hash_match = false;
                if ( ! empty($d['secured_shares']) && is_array($d['secured_shares']) ) {
                    foreach ($d['secured_shares'] as $sh) {
                        if (isset($sh['hash']) && $sh['hash'] === $share_hash) {
                            $hash_match = true;
                            break;
                        }
                    }
                }
                
                if ($hash_match) {
                    $d['client_signed']            = true;
                    $d['client_signer_name']       = $signer_name;
                    $d['client_signer_email']      = $signer_email;
                    $d['client_signature_data']    = $signature_data;
                    $d['client_signed_at']         = $time_now;
                    $d['client_signer_ip']         = $ip_now;
                    $d['client_verification_hash'] = $hash_now;

                    // Backward compatibility
                    $d['signed']                   = true;
                    $d['signer_name']              = $signer_name;
                    $d['signer_email']             = $signer_email;
                    $d['signature_data']           = $signature_data;
                    $d['signature_image']          = $signature_data;
                    $d['signed_at']                = $time_now;
                    $d['signer_ip']                = $ip_now;
                    $d['verification_hash']         = $hash_now;

                    // Recalculate document status
                    $admin_done = !empty($d['admin_signed']);
                    $d['status'] = $admin_done ? 'Signed' : 'Partially Signed';

                    $found_in_cora_docs = true;
                    break;
                }
            }
        }
    }

    // Try finding in cora_workspace_vault_docs if not found or sync both
    $found_in_vault_docs = false;
    $vault_docs = get_option('cora_workspace_vault_docs', array());
    if ( is_array($vault_docs) ) {
        foreach ($vault_docs as &$d) {
            if ( (string)$d['id'] === (string)$doc_id ) {
                $hash_match = false;
                if ( ! empty($d['secured_shares']) && is_array($d['secured_shares']) ) {
                    foreach ($d['secured_shares'] as $sh) {
                        if (isset($sh['hash']) && $sh['hash'] === $share_hash) {
                            $hash_match = true;
                            break;
                        }
                    }
                }
                
                if ($hash_match) {
                    $d['client_signed']            = true;
                    $d['client_signer_name']       = $signer_name;
                    $d['client_signer_email']      = $signer_email;
                    $d['client_signature_data']    = $signature_data;
                    $d['client_signed_at']         = $time_now;
                    $d['client_signer_ip']         = $ip_now;
                    $d['client_verification_hash'] = $hash_now;

                    $d['signed']                   = true;
                    $d['signer_name']              = $signer_name;
                    $d['signer_email']             = $signer_email;
                    $d['signature_data']           = $signature_data;
                    $d['signature_image']          = $signature_data;
                    $d['signed_at']                = $time_now;
                    $d['signer_ip']                = $ip_now;
                    $d['verification_hash']         = $hash_now;

                    $admin_done = !empty($d['admin_signed']);
                    $d['status'] = $admin_done ? 'Signed' : 'Partially Signed';

                    $found_in_vault_docs = true;
                    break;
                }
            }
        }
    }

    if ($found_in_cora_docs || $found_in_vault_docs) {
        if ($found_in_cora_docs) {
            update_option('cora_documents', $cora_docs);
        }
        if ($found_in_vault_docs) {
            update_option('cora_workspace_vault_docs', $vault_docs);
        }
        wp_send_json_success('E-Signature executed successfully!');
    } else {
        wp_send_json_error('Verification error: Secure token or document target is invalid.');
    }
}
}

add_action('wp_ajax_cora_share_document_email', 'cora_ajax_share_document_email');
if ( ! function_exists( 'cora_ajax_share_document_email' ) ) {
function cora_ajax_share_document_email() {
    check_ajax_referer('cora_ajax_nonce', 'nonce');
    if ( ! current_user_can('read') ) wp_send_json_error('Permission denied');

    $doc_id = sanitize_text_field($_POST['doc_id'] ?? '');
    $email  = sanitize_email($_POST['email'] ?? '');
    $custom_msg = sanitize_textarea_field($_POST['message'] ?? '');

    if ( empty($doc_id) || empty($email) ) {
        wp_send_json_error('Valid recipient email required.');
    }

    $docs = get_option('cora_documents', array());
    if ( ! is_array($docs) ) $docs = array();

    $found = false;
    $share_hash = '';
    
    foreach ($docs as &$d) {
        if ( (string)$d['id'] === (string)$doc_id ) {
            $found = true;
            
            // Check if secured_shares exists
            if ( empty($d['secured_shares']) || ! is_array($d['secured_shares']) ) {
                $d['secured_shares'] = array();
            }

            // Look for existing share for this email
            foreach ($d['secured_shares'] as $sh) {
                if (isset($sh['email']) && $sh['email'] === $email) {
                    $share_hash = $sh['hash'];
                    break;
                }
            }

            // Create one if none exists
            if (empty($share_hash)) {
                $share_hash = wp_hash($doc_id . time() . uniqid());
                $d['secured_shares'][] = array(
                    'hash'        => $share_hash,
                    'email'       => $email,
                    'expiry_time' => 0, // No expiry
                    'created_at'  => time()
                );
            }
            
            $doc_title = $d['title'];
            break;
        }
    }

    if (!$found) {
        wp_send_json_error('Document not found.');
    }

    // Save changes to DB
    update_option('cora_documents', $docs);

    $share_url = home_url('/shared-doc/' . $share_hash);
    $subject   = "Official Document Access & E-Sign Request: " . $doc_title;
    $message   = "Hello,\n\nYou have been requested to review and e-sign an official document from Cora Workspace: '" . $doc_title . "'.\n\n" . ($custom_msg ? "Note: " . $custom_msg . "\n\n" : "") . "Please click the link below to view the document and sign your section online:\n" . $share_url . "\n\nBest regards,\nCora Studio Workspace";

    $sent = wp_mail($email, $subject, $message);
    if ($sent) {
        wp_send_json_success('Document secure e-sign link emailed to ' . $email);
    } else {
        wp_send_json_error('Email delivery failed.');
    }
}
}

add_action('wp_ajax_cora_delete_document', 'cora_ajax_delete_document');
if ( ! function_exists( 'cora_ajax_delete_document' ) ) {
function cora_ajax_delete_document() {
    check_ajax_referer('cora_ajax_nonce', 'nonce');
    if ( ! current_user_can('read') ) wp_send_json_error('Permission denied');

    $doc_id = sanitize_text_field($_POST['doc_id'] ?? '');
    if ( empty($doc_id) ) wp_send_json_error('Invalid document ID');

    $docs = get_option('cora_documents', array());
    if ( ! is_array($docs) ) $docs = array();

    $docs = array_filter($docs, function($d) use ($doc_id) {
        return (string)($d['id'] ?? '') !== (string)$doc_id;
    });

    update_option('cora_documents', array_values($docs));

    // Also remove from cora_workspace_vault_docs option key if present
    $vault_docs = get_option('cora_workspace_vault_docs', array());
    if ( is_array($vault_docs) ) {
        $vault_docs = array_filter($vault_docs, function($d) use ($doc_id) {
            return (string)($d['id'] ?? '') !== (string)$doc_id;
        });
        update_option('cora_workspace_vault_docs', array_values($vault_docs));
    }

    wp_send_json_success('Document deleted.');
}
}

add_action('wp_ajax_cora_export_gstr1', 'cora_ajax_export_gstr1');
if ( ! function_exists( 'cora_ajax_export_gstr1' ) ) {
function cora_ajax_export_gstr1() {
    check_ajax_referer('cora_ajax_nonce', 'nonce');
    if ( ! current_user_can('read') ) wp_send_json_error('Permission denied');

    $docs = get_option('cora_documents', array());
    if ( ! is_array($docs) ) $docs = array();

    $csv = "GSTIN/UIN of Recipient,Receiver Name,Invoice Number,Invoice Date,Invoice Value,Place Of Supply,Reverse Charge,Applicable % of Tax Rate,Invoice Type,E-Commerce GSTIN,Rate,Taxable Value,Cess Amount,CGST,SGST,IGST\n";
    foreach ($docs as $d) {
        $gstin = $d['client_gstin'] ?? 'URP';
        $name  = $d['client_name'] ?? 'Client';
        $num   = $d['number'] ?? 'INV-2026';
        $date  = $d['created_at'] ?? date('Y-m-d');
        $val   = floatval($d['grand_total'] ?? $d['amount'] ?? 0);
        $pos   = $d['pos_state'] ?? 'Delhi (07)';
        $taxable = $val / 1.18;
        $tax   = $val - $taxable;
        $is_igst = ! empty($d['is_igst']);

        $cgst = $is_igst ? 0 : ($tax / 2);
        $sgst = $is_igst ? 0 : ($tax / 2);
        $igst = $is_igst ? $tax : 0;

        $csv .= '"' . $gstin . '","' . $name . '","' . $num . '","' . $date . '",' . number_format($val, 2, '.', '') . ',"' . $pos . '","N","18%","Regular","",' . '18%,' . number_format($taxable, 2, '.', '') . ',0.00,' . number_format($cgst, 2, '.', '') . ',' . number_format($sgst, 2, '.', '') . ',' . number_format($igst, 2, '.', '') . "\n";
    }

    wp_send_json_success(array('csv' => $csv, 'filename' => 'GSTR1_Outward_Supplies_' . date('Y_m') . '.csv'));
}
}

